            {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}
                {% set currentDatatype = alterCurCol.dataType %}
                {% set currentNullable = alterCurCol.nullable %}
                {% set currentDefaultValue = alterCurCol.defaultValue %}
                {% set currentDescription = alterCurCol.description %}

                {% set desiredColumnName = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='name') | first %}
                {% set desiredDatatype = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='dataType') | first %}
                {% set desiredNullable = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='nullable') | first %}
                {% set desiredDefaultValue = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='defaultValue') | first %}
                {% set desiredDescription = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='description') | first %}

                {% set datatypeTest = currentDatatype == desiredDatatype %}
                {% set nullableTest = currentNullable == desiredNullable %}
                {% set defaultValueTest = currentDefaultValue == desiredDefaultValue %}
                {% set descriptionTest = currentDescription == desiredDescription %}

                {% if (datatypeTest == false or 
                        nullableTest == false  or
                        defaultValueTest == false or
                        descriptionTest == false) %}
                    {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}

                    {% if nsVariables.colchanges == 1 %}
                        {{ stage('Change Column Attributes') }}
                        ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                        MODIFY
                    {% endif %}
                    {% if datatypeTest == false %}
                        {% if nsVariables.colchanges > 1 %},{% endif %}
                        COLUMN "{{ desiredColumnName }}"
                        SET DATA TYPE {{ desiredDatatype }}
                        {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                    {% endif %}
                    {% if nullableTest == false %}
                        {% if nsVariables.colchanges > 1 %},{% endif %}
                        COLUMN "{{ desiredColumnName }}"
                        {% if currentNullable == true %}
                            SET
                        {% else %}
                            DROP
                        {% endif %}
                        NOT NULL
                        {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                    {% endif %}
                    {% if descriptionTest == false %}
                        {% if nsVariables.colchanges > 1 %},{% endif %}
                        COLUMN "{{ desiredColumnName }}"
                        COMMENT '{{ desiredDescription | escape }}'
                        {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                    {% endif %}
                    {% if defaultValueTest == false %}
                        {% if nsVariables.colchanges > 1 %},{% endif %}
                        COLUMN "{{ desiredColumnName }}"
                        {% if desiredDefaultValue == '' %}
                            DROP DEFAULT
                        {% else %}
                            SET DEFAULT {{ desiredDefaultValue }}
                        {% endif %}
                        {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                    {% endif %}

                    {# Metadata changes detected #}
                    {% if desiredState.config.devMode %}
                        {% set nsMetaVariables.metaDataChanged = true %}
                    {%endif%}

                {% else %}

                {% endif %}
            {% endif %}
        {% endfor %}

        {# Figure out cluster key #}
        {% set nsVariables = namespace(finalClusterKey="") %}
        {% if clusterTest == false %}
            {% if desiredState.config.clusterKeyExpressions == true %}
                {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='columnNameExpressions.name') | list, desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='sqlExpression') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% if expression[loop.index0] == "" %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                    {% else %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + [expression[loop.index0]] %}
                    {% endif %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% elif desiredState.config.clusterKey == true %}

                {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% else %}

                {% set nsVariables.finalClusterKey = 'DROP CLUSTERING KEY' %}

            {% endif %}

            {{ stage('Recluster TABLE') }}
            ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
            {{ nsVariables.finalClusterKey }}

            {# Metadata changes detected #}
            {% if desiredState.config.devMode %}
                {% set nsMetaVariables.metaDataChanged = true %}
            {%endif%}

        {% endif %}

        {% if desiredState.config.devMode %}
            {% if nsMetaVariables.metaDataChanged == false %}

                {# =========================================================
                Compare source counts
                ========================================================= #}
                {% set sourcesTest = currentState.sources | count == desiredState.sources | count %}

                {% if sourcesTest %}
                    {% for src in desiredState.sources %}
                        {% set matchingSource = currentState.sources | selectattr('name', 'equalto', src.name) | first %}
                        {% if matchingSource %}

                            {# =========================================================
                            Join comparison
                            ========================================================= #}
                            {% set desiredStateSources = src.join | replace("{{", '"{{"') | replace("}}", '"}}"') | replace('/*', '/ *') | replace('*/', '* /') %}
                            {% set currentStateSources = matchingSource.join | replace("{{", '"{{"') | replace("}}", '"}}"') | replace('/*', '/ *') | replace('*/', '* /') %}

                            {# Same number of sources — compare join transformations #}
                            {% if desiredStateSources != currentStateSources %}
                                {% set nsMetaVariables.joinTest = false %}
                                {% set _ = nsMetaVariables.joinDiff.append({
                                    "Source": src.name,
                                    "is": desiredStateSources,
                                    "was": currentStateSources }) %}
                            {% endif %}

                            {# =========================================================
                            Transformation and column source changes comparison (per column)
                            ========================================================= #}
                            {% for col in src.columns %}

                                {# Try to get matching column #}
                                {% set matched_column = matchingSource.columns
                                    | selectattr('id', 'equalto', col.id)
                                    | first
                                %}

                                {% if matched_column %}

                                    {# Transformation Changes #}
                                    {% set currentTransform = matchingSource.columns
                                        | selectattr('id', 'equalto', col.id)
                                        | map(attribute='transform')
                                        | first
                                        | default('')
                                    %}

                                    {% if currentTransform != col.transform %}
                                        {% set nsMetaVariables.transformTest = false %}
                                        {% set _ = nsMetaVariables.transformDiff.append({
                                            "Source Name": src.name,
                                            "Column Name": col.name,
                                            "is": col.transform | replace('/*', '/ *') | replace('*/', '* /'),
                                            "was": currentTransform | replace('/*', '/ *') | replace('*/', '* /')
                                        }) %}
                                    {% endif %}

                                    {# Column Source Changes #}
                                    {% set currentSource = matchingSource.columns
                                        | selectattr('id', 'equalto', col.id)
                                        | map(attribute='sourceColumns')
                                        | first
                                        | default('')
                                    %}

                                    {% if currentSource != col.sourceColumns %}
                                        {% set nsMetaVariables.sourceLinkTest = false %}
                                        {% set _ = nsMetaVariables.sourceLinkDiff.append({
                                            "Source Name": src.name,
                                            "Column Name": col.name,
                                            "is": (col.sourceColumns | selectattr('node','defined') | map(attribute='node.name') | first) | default('') ~ "-" ~ (col.sourceColumns | selectattr('column','defined') | map(attribute='column.name') | first) | default(''),
                                            "was": (currentSource | selectattr('node','defined') | map(attribute='node.name') | first) | default('') ~ "-" ~ (currentSource | selectattr('column','defined') | map(attribute='column.name') | first) | default('')
                                        }) %}
                                    {% endif %}
                                {% endif %}
                            {% endfor %}
                        {% endif %}
                    {% endfor %}

                    {% if nsMetaVariables.transformTest == false %}
                        {{ update_metadata("Transform", nsMetaVariables.transformDiff, "Transform") }}
                    {% endif %}

                    {% if nsMetaVariables.sourceLinkTest == false %}
                        {{ update_metadata("Source Link", nsMetaVariables.sourceLinkDiff, "Source Link") }}
                    {% endif %}
                {% else %}
                    {# Source count mismatch — compare source names instead #}
                    {% set desiredStateSources = desiredState.sources | map(attribute='name') | list | sort %}
                    {% set currentStateSources = currentState.sources | map(attribute='name') | list | sort %}

                    {% if desiredStateSources != currentStateSources %}
                        {% set nsMetaVariables.joinTest = false %}
                        {% set _ = nsMetaVariables.joinDiff.append({"is": desiredStateSources, "was": currentStateSources }) %}
                    {% endif %}
                {% endif %}

                {% if nsMetaVariables.joinTest == false %}
                        {{ update_metadata("Join", nsMetaVariables.joinDiff, "Join") }}
                {% endif %}

                {# =========================================================
                Insert Strategy comparison
                ========================================================= #}
                {% if currentState.config.insertStrategy | default('') != desiredState.config.insertStrategy %}
                    {% set _ = nsMetaVariables.insertStrategyDiff.append({
                        "is": desiredState.config.insertStrategy,
                        "was": currentState.config.insertStrategy | default('')
                    }) %}

                    {{ update_metadata("Insert Strategy", nsMetaVariables.insertStrategyDiff, "Insert Strategy") }}

                {% endif %}

                {# =========================================================
                Truncate Table comparison
                ========================================================= #}
                {% if currentState.config.truncateBefore | default(false) != desiredState.config.truncateBefore %}
                    {% set _ = nsMetaVariables.truncateBeforeDiff.append({
                        "is": desiredState.config.truncateBefore,
                        "was": currentState.config.truncateBefore | default(false)
                    }) %}

                    {{ update_metadata("Truncate Before", nsMetaVariables.truncateBeforeDiff, "Truncate Before") }}

                {% endif %}

                {# =========================================================
                Distinct Toggle comparison
                ========================================================= #}
                {% if currentState.config.selectDistinct | default(false) != desiredState.config.selectDistinct %}
                    {% set _ = nsMetaVariables.distinctDiff.append({
                        "is": desiredState.config.selectDistinct,
                        "was": currentState.config.selectDistinct | default(false)
                    }) %}

                    {{ update_metadata("Distinct", nsMetaVariables.distinctDiff, "Distinct") }}

                {% endif %}

                {# =========================================================
                GroupByAll Toggle comparison
                ========================================================= #}
                {% if currentState.config.groupByAll | default(false) != desiredState.config.groupByAll %}
                    {% set _ = nsMetaVariables.groupByAllDiff.append({
                        "is": desiredState.config.groupByAll,
                        "was": currentState.config.groupByAll | default(false)
                    }) %}

                    {{ update_metadata("GroupByAll", nsMetaVariables.groupByAllDiff, "GroupByAll") }}

                {% endif %}

                {# =========================================================
                Order By comparison (per column)
                ========================================================= #}
                {% if currentState.config.orderby | default(false) != desiredState.config.orderby %}

                    {% set nsMetaVariables.orderByTest = false %}
                    {% set _ = nsMetaVariables.orderByDiff.append({
                            "is": desiredState.config.orderby,
                        "was": currentState.config.orderby | default(false)
                    }) %}

                {% elif currentState.config.orderby and desiredState.config.orderby %}

                    {% set desiredSortColList = [] %}
                    {% set currentSortColList = [] %}

                    {# Desired Column sort order #}
                    {% for item in desiredState.config.orderbycolumn.get('items', []) %}
                        {% set _ = desiredSortColList.append({
                                    "Column Name": item.sortColName.name,
                                    "Sort Order": item.sortOrder
                        }) %}
                    {% endfor%}
                    {# Current Column sort order #}
                    {% for item in currentState.config.orderbycolumn.get('items', []) %}
                        {% set _ = currentSortColList.append({
                                    "Column Name": item.sortColName.name,
                                    "Sort Order": item.sortOrder
                        }) %}
                    {% endfor%}

                    {% if desiredSortColList != currentSortColList %}
                        {% set nsMetaVariables.orderByTest = false %}
                        {% set _ = nsMetaVariables.orderByDiff.append({
                            "is": desiredSortColList,
                            "was": currentSortColList
                        }) %}
                    {% endif %}
                    {% endif %}

                {% if nsMetaVariables.orderByTest == false %}
                    {{ update_metadata("Order By", nsMetaVariables.orderByDiff, "Order By") }}
                {% endif %}

                {# =========================================================
                DevMode Toggle comparison
                ========================================================= #}
                {% if currentState.config.devMode | default(false) != desiredState.config.devMode %}

                    {{ update_metadata("DevMode", {"is": desiredState.config.devMode, "was": currentState.config.devMode | default(false)}, "DevMode") }}

                {% endif %}

                {# =========================================================
                Handle detected metadata changes and update
                ========================================================= #}
                {% if nsMetaVariables.metaDataChanges | length == 0 %}
                    {{ stage('Metadata Update-Default') }}
                {% else %}
                    {{ stage(nsMetaVariables.metadataUpdate) }}
                    -- Metadata changes detected
                    /* {{ nsMetaVariables.metaDataChanges }} */
                {% endif %}
                select 1=0
            {% endif %}
        {% endif %}
    {% endif %}

{% elif currentState != undefined and desiredState == undefined %}

    {# Table or View Name #}
    {% set targetObjectDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetObjectSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetObjectName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

    {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
    {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
    DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

{% endif %}

{# Create Task Second #}

{% if desiredState and  desiredState != currentState%}

        {# Target Table Info #}
        {% set targetTableDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %} 
        {% set targetTableSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %} 
        {% set fullyQualifiedTargetTableName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}


		{% if desiredState.config.devMode == false %}
			{%- if desiredState.config.schedulePeriodOption == 'Predecessor' -%} 
				{% set fullyQualifiedRootTaskName = ref_no_link(desiredState.node.location.name, desiredState.config.rootTask) %}
				{{ stage('Suspend Root Task',true,"sql","create") }}
				ALTER TASK {{ fullyQualifiedRootTaskName }} SUSPEND
			{%- endif -%}

        {%-if currentState !=undefined and (currentState.config.schedulePeriodOption | default('') != desiredState.config.schedulePeriodOption or currentState.config.rootTask | default('') != desiredState.config.rootTask)-%}            
         {%- if currentState.config.schedulePeriodOption | default('') == 'Predecessor' -%}
            {% set fullyQualifiedRootTaskName = ref_no_link(currentState.node.location.name, currentState.config.rootTask) %}

            {{ stage('Suspend Root Task',true,"sql","create") }}

            ALTER TASK {{ fullyQualifiedRootTaskName }} SUSPEND

          {%- endif -%}
        {%-endif -%}

            {# Set Namespace Variables #}
            {% set nsVariables = namespace(taskWhenRun="") %}
            {% set nsVariables = namespace(poll="WHEN ") %}

			{# Task Info - Use ref() #}
			{% set taskName = desiredState.node.name + '_TASK' %}
			{% set fullyQualifiedTaskName = ref_no_link(desiredState.node.location.name, taskName) %}

            {# Task Type #}
            {%- if desiredState.config.schedulingMode == 'Warehouse Task' -%} 
                {# Can be updated during deployment via a parameter to account for different warehouse names in different deployments #}
			  {% if 'targetTaskWarehouse'  in  desiredState.parameters %}
                {% if desiredState.parameters.targetTaskWarehouse == 'DEV ENVIRONMENT' %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.config.whName %}
                {% else %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.parameters.targetTaskWarehouse %}
                {% endif %}
			  {% endif %}
            {%- else -%}
                {% set taskType = 'USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = ' + getServerSize(desiredState.config.serverlessSize) -%}
                {%- if desiredState.config.sizeBoundToggle -%}
                    {% set minSrvSize = 'SERVERLESS_TASK_MIN_STATEMENT_SIZE = ' + getServerSize(desiredState.config.minServerlessSize) -%}
                    {% set maxSrvSize = 'SERVERLESS_TASK_MAX_STATEMENT_SIZE = ' + getServerSize(desiredState.config.maxServerlessSize) -%}
                {%- endif -%} 
            {%- endif -%}

            {# Schedule Type #}
        {%- if desiredState.config.schedulePeriodOption == 'Minutes' %} 
            {%- set execValue = desiredState.config.get('execTime', {})
                                .get('items', [])
                                | map(attribute='value')
                                | first
            %}
            {%- set execPeriod = desiredState.config.get('execTime', {})
                                .get('items', [])
                                | map(attribute='period')
                                | first
            %}
            {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + execValue | trim ~ ' ' ~ execPeriod | trim + "'" %}
        {% elif desiredState.config.schedulePeriodOption == 'CRON' %}
            {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + 'USING CRON ' + desiredState.config.scheduleCRON | trim + "'" %}
            {%- else -%}
                {%- set nsVariables.taskWhenRun = 'AFTER ' -%}
                {%- set predecessorTasks = (desiredState.config.predTask).split(",") -%}

                {%- for p in predecessorTasks -%}
                    {%- set nsVariables.taskWhenRun = nsVariables.taskWhenRun + targetTableDatabase + '.' + targetTableSchema + '."' + p + '"' -%}
                    {%- if not loop.last -%} 
                        {%- set nsVariables.taskWhenRun = nsVariables.taskWhenRun + ',' -%}
                    {%- endif %}
                {% endfor %}    
            {%- endif -%}

            {# When Stream has data logic #}
            {# Source Stream Location and Name #}
            {% if desiredState.config.flagSrcStream == true %}
                {% for source in desiredState.sources %}
                    {% for dep in source.dependencies %}
                        {% if (dep.node.materializationType == 'stream') %}
                            {% set streamStorageLocation = dep.node.location.name %}
                            {% set streamSourceDatabase = desiredState.storageLocations | selectattr('name', 'equalto', streamStorageLocation) | map(attribute='database') | first %}
                            {% set streamSourceSchema = desiredState.storageLocations | selectattr('name', 'equalto', streamStorageLocation) | map(attribute='schema') | first %}
                            {% set streamSourceName = dep.node.name %}

                            {%- if nsVariables.poll == 'WHEN ' -%}
                                {% set nsVariables.poll = nsVariables.poll + 'SYSTEM$STREAM_HAS_DATA(\'"' + streamSourceDatabase + '"."'  + streamSourceSchema + '"."' + streamSourceName + '"\')'  %}
                            {% else %}
                                {% set nsVariables.poll = nsVariables.poll + desiredState.config.multiStreamBehavior + ' SYSTEM$STREAM_HAS_DATA(\'"' + streamSourceDatabase + '"."'  + streamSourceSchema + '"."' + streamSourceName + '"\')'  %}
                            {%- endif -%}
                        {%- endif -%}
                    {% endfor %}
                {% endfor %}
            {% endif -%}

        {%- set nsTaskVar = namespace(nodeComment='',
                                    userServiceAcct='',
                                    suspendTask='',
                                    autoTry='',
                                    overLapExec='',
                                    configJSON='',
                                    errorIntegration='',
                                    successIntegration='') %}
        {{ getadvancedTaskOptions(nsTaskVar) }}

            {# To mimic truncate behavior #}
            {% if desiredState.config.truncateBefore == true %}
                {% set truncateBehavior = 'INSERT OVERWRITE' %}
            {% else %}
                {% set truncateBehavior = 'INSERT' %}
            {% endif -%}

            {{ stage('Create Task',true,"sql","create") }}
            CREATE OR REPLACE TASK 
                {{ fullyQualifiedTaskName }} 
                {{ taskType }}
                {% if desiredState.config.schedulingMode == 'Serverless Task' and desiredState.config.sizeBoundToggle -%}
                    {{ minSrvSize }}
                    {{ maxSrvSize }}
                {% endif -%}
                {{ nsTaskVar.nodeComment }}
                {{ nsVariables.taskWhenRun }}
                {%- if desiredState.config.schedulePeriodOption != 'Predecessor' %}
                    {{ nsTaskVar.overLapExec }}
                    {%- if desiredState.config.autoSuspendToggle %}
                    {{ nsTaskVar.suspendTask }}
                    {%- endif %}
                    {%- if desiredState.config.autoRetryToggle %}
                        {{ nsTaskVar.autoTry }}
                    {%- endif %}
                    {%- if desiredState.config.taskGraphToggle %}
                        {{ nsTaskVar.configJSON }}
                    {%- endif %}
                {%- if desiredState.config.errNotifyToggle %}
                    {{ nsTaskVar.errorIntegration }}
                {%- endif %}
                {%- if desiredState.config.successNotifyToggle %}
                    {{ nsTaskVar.successIntegration }}
                {%- endif %}
                {%- endif %}
                {%- if desiredState.config.spfcUserToggle %}
                    {{ nsTaskVar.userServiceAcct }}
                {%- endif %}
                {% if nsVariables.poll != 'WHEN ' %} {{ nsVariables.poll }} {% endif %}
            AS 
            {{ truncateBehavior }} INTO {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                (
                    {% for col in desiredState.columns %}
                        "{{ col.name }}"
                        {%- if not loop.last -%},{% endif %}
                    {% endfor %}
                )

                {% for source in desiredState.sources %}
                    /* Combine Sources if needed */
                    {% if loop.first %}
                        SELECT {% if desiredState.config.selectDistinct %} DISTINCT {% endif %}
                        {% for col in desiredState.columns  %}
                            "{{ col.name }}" AS "{{ col.name }}"
                            {% if not loop.last %}, {% endif %}
                        {% endfor %}
                        FROM (
                    {% endif %}
                    SELECT {% if desiredState.config.selectDistinct %} DISTINCT {% endif %}
                    {% for col in source.columns if not col.isSurrogateKey %}
                        {{ get_source_transform(col) }} AS "{{ col.name }}"{% if not loop.last %}, {% endif %}
                    {% endfor %}
                    {{ source.join }}                  
                    {% if not loop.last %}
                        {{ desiredState.config.insertStrategy }}
                    {% endif %}
                    {% if loop.last %}
                        )
                    {% endif %}
                {% endfor %}
                {% if desiredState.config.groupByAll %}GROUP BY ALL{% endif %}
                {{ sortorder_by_colv() }}

            {%- if desiredState.config.schedulePeriodOption != 'Predecessor' -%} 
                {{ stage('Resume Task',true,"sql","create") }}
                ALTER TASK {{ fullyQualifiedTaskName }} RESUME;
            {%- endif -%}       
        {%- endif -%}

{% elif currentState != undefined and desiredState == undefined %}

    {# Target Table Info #}
    {% set targetTableDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetTableSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetTableName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

    {% if currentState.config.devMode | default(false) == false %}
		{% set fullyQualifiedRootTaskName = ref_no_link(currentState.node.location.name, currentState.config.rootTask) %}

        {# Task Info #}
        {% set taskName = currentState.node.name + '_TASK' %}
        {% set fullyQualifiedTaskName = ref_no_link(currentState.node.location.name, taskName) %}
        {%- if currentState.config.schedulePeriodOption | default('') == 'Predecessor' -%}
        {{ stage('Suspend Root Task') }}
            ALTER TASK IF EXISTS {{ fullyQualifiedRootTaskName }} SUSPEND
        {{ stage('Drop Current Task') }}
            DROP TASK IF EXISTS {{ fullyQualifiedTaskName }} 
        {%- else -%}
        {{ stage('Drop Current Task') }}
            DROP TASK IF EXISTS {{ fullyQualifiedTaskName }} 
        {%- endif -%}
    {%- endif -%}

{% endif %}

run.templateString:
{#
    Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalsce but
does not permit copying or modification for any other purpose.  
#}
{# == Node Type Version        : 1  == #}
{# == Node Type Name           : Stream and Insert or Merge == #}
{# == Node Type Description    : This node inserts/merge data into target table == #}

{# Development mode -To test the SQL the task will execute to make sure it runs without errors and returns the expected data #}

{% if config.devMode == true %}

    {% set nsVariables = namespace() %}

    {# Target Stream Location and Name #}
    {% set streamTargetLocationName = node.location.name %}
    {% set streamTargetDatabaseName = storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='database') | first %}
    {% set streamTargetSchemaName = storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='schema') | first %}
    {% set streamName = node.name + '_STREAM' %}
    {% set fullyQualifiedStreamName = '"' + streamTargetDatabaseName + '"."' + streamTargetSchemaName + '"."' + streamName + '"' %}

    {# Target Table Info #}
    {% set targetTableDatabase = ref_no_link(node.location.name, node.name).split('.')[0] %} 
    {% set targetTableSchema = ref_no_link(node.location.name, node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetTableName = ref_no_link(node.location.name, node.name) %}
    {% set targetTableName = node.name %}

    {% set tableColumnIds = columns | map(attribute='id') | list %}
    {% set tableColumnNames = columns | map(attribute='name') | list %}
    {# Split the FROM clause if it contains an ORDER BY to ensure the correct order. #}
	{% set ret_clause = get_clause( sources[0].join ).lstrip()%}
    {% set upper_query = ret_clause | upper %}
    {% if 'ORDER BY' in upper_query %}
	   {% set index = upper_query.find('ORDER BY') %}
	   {% set before_order_by = ret_clause[:index] %}
	   {% set after_order_by = ret_clause[index:]%}
       {% set ret_clause = before_order_by  %}
    {% else %}
       {% set before_order_by = ret_clause %}
       {% set after_order_by = '' %}
    {% endif %}
	{# Check if the WHERE clause contains column aliases and replace them with the correct stream name #}
	{% set modified_string = namespace(value="") %}
	{% set words = ret_clause.split() %}
	{% for word in words %}
    {% if '.' in word %}
        {% set parts = word.split('.') %}
        {% set modified_word = streamName ~ "." ~ parts[1] %}
        {% set modified_word = modified_word.replace('"', "") %}
    {% else %}
        {% set modified_word = word %}
    {% endif %}
    {% set modified_string.value = modified_string.value ~ " " ~ modified_word %}
{% endfor %}
{% set ret_clause = modified_string.value %}

    {# Merge partition by and order by #}
    {%- if config.loadType == 'Merge' -%} 
        {% set tableColumnNamesUpdate = tableColumnNames | reject('in', config.partitionBy.get('items') | map(attribute='partColName.name')) | list %}

        {% for i in config.partitionBy.get('items') %}
            {%- if loop.first -%}
                {% set nsVariables.partition = '"' + i.partColName.name + '"' %}
            {% else %}
                {% set nsVariables.partition = nsVariables.partition + ', "' + i.partColName.name + '"' %}
            {%- endif -%}

            {% set tableColumnNamesUpdate = tableColumnNames | reject('in', i.partColName.name) | list %}

        {% endfor %}

        {% for i in config.orderBy.get('items') %}
            {%- if loop.first -%}
                {% set nsVariables.orderBy = '"' + i.colName.name + '" ' + i.sortOrd %}
            {% else %}
                {% set nsVariables.orderBy = nsVariables.orderBy + ', "' + i.colName.name + '" ' + i.sortOrd %}
            {%- endif -%}
        {% endfor %}
        {% set nsVariables.rowNumber = 'ROW_NUMBER() OVER (PARTITION BY ' + nsVariables.partition + ' ORDER BY ' + nsVariables.orderBy + ')' %}

        {%- set nsVariables.tableKey = config.partitionBy.get('items') %}
        {% set nsVariables.tableKey = nsVariables.tableKey | map(attribute='partColName.name') | list %}
    {%- endif -%}

    {# Merge partition by and order by #}
    {%- if config.loadType == 'Merge' -%} 
        {% set tableColumnNamesUpdate = tableColumnNames | reject('in', config.partitionBy.get('items') | map(attribute='partColName.name')) | list %}

        {% for i in config.partitionBy.get('items') %}
            {%- if loop.first -%}
                {% set nsVariables.partition = '"' + i.partColName.name + '"' %}
            {% else %}
                {% set nsVariables.partition = nsVariables.partition + ', "' + i.partColName.name + '"' %}
            {%- endif -%}

            {% set tableColumnNamesUpdate = tableColumnNames | reject('in', i.partColName.name) | list %}

        {% endfor %}

        {% for i in config.orderBy.get('items') %}
            {%- if loop.first -%}
                {% set nsVariables.orderBy = '"' + i.colName.name + '" ' + i.sortOrd %}
            {% else %}
                {% set nsVariables.orderBy = nsVariables.orderBy + ', "' + i.colName.name + '" ' + i.sortOrd %}
            {%- endif -%}
        {% endfor %}
        {% set nsVariables.rowNumber = 'ROW_NUMBER() OVER (PARTITION BY ' + nsVariables.partition + ' ORDER BY ' + nsVariables.orderBy + ')' %}

        {%- set nsVariables.tableKey = config.partitionBy.get('items') %}
        {% set nsVariables.tableKey = nsVariables.tableKey | map(attribute='partColName.name') | list %}
    {%- endif -%}

    {{ stage('Insert or Merge Data') }}

        {% if config.loadType == 'Insert' -%} 
            INSERT INTO {{ fullyQualifiedTargetTableName }}
            SELECT  {% if config.selectDistinct %} DISTINCT {% endif %}
                    {% for id in tableColumnIds %}

                    {% set columnTransformation = sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='transform') | first -%}
                    {%- if columnTransformation == "" -%}
                    {% set col =  sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='sourceColumns') | first  |  map(attribute='column')  | list |  map(attribute='name') | first   -%}
                    "{{ col }}" as "{{ col }}" {%- if not loop.last -%}, {%- endif -%}
                    {%- else -%}
                    {% set col = sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='name') | first -%}
                    {{ columnTransformation  }} as "{{ col }}" {%- if not loop.last -%}, {%- endif -%}
                    {%- endif %}
                {%- endfor %}
            FROM {{ fullyQualifiedStreamName }}
			{% if config.propagateDeletes %} WHERE  METADATA$ACTION != 'DELETE'
			{% if ret_clause|trim !='' %}
			{{ret_clause}}
			{% endif %}
			{%- else -%}
			{% set join_clause = ret_clause.lstrip() | replace("AND ", "WHERE ", 1) if ret_clause.lstrip().startswith("AND ") else ret_clause %}
			{{join_clause}}
			{% endif %}            
			{% if config.groupByAll %}GROUP BY ALL{% endif %}
			{{after_order_by}}
            {% else -%}
            MERGE INTO {{ fullyQualifiedTargetTableName }} tgt USING
            -- Select Statement Preparing Data for Merge
            (SELECT {% if config.selectDistinct %} DISTINCT {% endif %}
                    {% for id in tableColumnIds %}

                    {% set columnTransformation = sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='transform') | first -%}
                    {%- if columnTransformation == "" -%}
                    {% set col =  sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='sourceColumns') | first  |  map(attribute='column')  | list |  map(attribute='name') | first   -%}
                    "{{ col }}" as "{{ col }}" {%- if not loop.last -%}, {%- endif -%}
                    {%- else -%}
                    {% set col = sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='name') | first -%}
                    {{ columnTransformation }} as "{{ col }}" {%- if not loop.last -%}, {%- endif -%}
                    {%- endif %}
                {%- endfor %}
            FROM {{ fullyQualifiedStreamName }}
			{% if config.propagateDeletes %} WHERE  METADATA$ACTION != 'DELETE'
			{% if ret_clause|trim !='' %}
			{{ret_clause}}
			{% endif %}
			{%- else -%}
			{% set join_clause = ret_clause.lstrip() | replace("AND ", "WHERE ", 1) if ret_clause.lstrip().startswith("AND ") else ret_clause %}
			{{join_clause}}
			{% endif %}           
			{% if config.groupByAll %}GROUP BY ALL{% endif %}
            QUALIFY {{ nsVariables.rowNumber }} = 1
			{{after_order_by}}
			) src

            -- Join Condition
            ON {% for col in nsVariables.tableKey -%}
                src."{{ col }}" = tgt."{{ col }}"
            {% if not loop.last %} AND {% endif %}
                {%- endfor -%}

            -- What to do if data is matched based on table key
            WHEN MATCHED THEN UPDATE SET 
                {%- for col in tableColumnNamesUpdate %}
                    {% if col not in ["SYSTEM_CREATE_DATE"]%}
                        tgt."{{ col }}" = src."{{ col }}"
                        {%- if not loop.last -%}, {%- endif %}
                    {%endif%}
                {%- endfor %}
            -- What to do with new records based on table key
            WHEN NOT MATCHED THEN INSERT 
                (
                {%- for col in columns -%}
                        "{{ col.name }}"
                        {%- if not loop.last -%}, {% endif %}
                {% endfor %}) 
            VALUES (
                {%- for col in columns -%}
                        src."{{ col.name }}"
                        {%- if not loop.last -%}, {% endif %}
                {% endfor %})
            {%- endif -%}
{% else %}
    {{ stage('Task Mode - No Manual Run') }}
    -- This node is configured to run as a scheduled task
    -- Manual Run is only available when Development Mode is enabled
    -- To execute this task, wait for the scheduled run or manually execute: EXECUTE TASK {{node.name + '_TASK'}}
    SELECT 1 AS INFO_MESSAGE WHERE FALSE
{% endif -%}

create.templateString:
{#Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.  
#} 
{# == Node Type Name           : Stream and Insert or Merge == #}
{# == Node Type Description    : This node creates and deploys a stream on top of a table, view or external table.Also provides option to create a target table/transient  able to insert or merge data from source with a task on top of it.
== #}

{# Parameter Check for Deployment #}
{%if desiredState and currentState != desiredState and desiredState.config.schedulingMode == 'Warehouse Task' %}
     {% if desiredState.parameters == {} or 'targetTaskWarehouse' not in  desiredState.parameters or desiredState.parameters.targetTaskWarehouse == ''%}

         {{stage('WARNING')}}

          /*Add parameter targetTaskWarehouse in workspace settings and deployment environment for successful execution of node.
          The default value for the parameter is 'DEV ENVIRONMENT'.
          For more information, refer to the documentation.*/
	{%endif%}
{%endif%}


{# Create Stream First #}
{% if desiredState %}

    {% if desiredState.config.sourceType == 'Directory Table' %}
	{% set stageStorageLocation =  desiredState.config.storageLocation | string %}
	{% set stageNameVar =  desiredState.config.stageName | string %}
    {% set refLink = "{{ ref_no_link('" + stageStorageLocation + "', '" + stageNameVar + "') }}" %}

    {% else %}

    {# Source Object Location and Name #}

    {% set ns = namespace(sourceStorageLocation ="",sourceTableName ="") %}  

     --{#Code modified to support all task,SIM and DSM node types as upstream nodes #}
     -- {% for dependency in desiredState.sources[0].dependencies %}
      --  {% if dependency.node.materializationType != 'root task' %} 
          --  {% set ns.sourceStorageLocation = dependency.node.location.name %}
          --  {% set ns.sourceTableName = dependency.node.name %}
      --  {% endif %}
      --{% endfor %}

    {% set ns.sourceStorageLocation = (desiredState.sources[0].columns| selectattr("sourceColumns", "defined")| selectattr("sourceColumns", "ne", [{}])| first).sourceColumns[0].node.location.name %}
    {% set ns.sourceTableName = (desiredState.sources[0].columns| selectattr("sourceColumns", "defined")| selectattr("sourceColumns", "ne", [{}])| first).sourceColumns[0].node.name %}

    {% set sourceDatabaseName = desiredState.storageLocations | selectattr('name', 'equalto', ns.sourceStorageLocation) | map(attribute='database') | first %}
    {% set sourceSchemaName = desiredState.storageLocations | selectattr('name', 'equalto', ns.sourceStorageLocation) | map(attribute='schema') | first %}

    {% set fullyQualifiedSourceTableName = '"' + sourceDatabaseName + '"."' + sourceSchemaName + '"."' + ns.sourceTableName + '"' %}
    {% set refLink = "{{ ref('" + ns.sourceStorageLocation + "', '" + ns.sourceTableName + "') }}" %}
    {% endif %}

    {# Target Stream Location and Name #}
    {% set streamTargetLocationName = desiredState.node.location.name %}
    {% set streamTargetDatabaseName = desiredState.storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='database') | first %}
    {% set streamTargetSchemaName = desiredState.storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='schema') | first %}
    {% set streamName = desiredState.node.name + '_STREAM' %}


    {# Target Table Info #}
    {% set targetTableDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %}
    {% set targetTableSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %}
    {% set fullyQualifiedTargetTableName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}
    {% set targetTableName = desiredState.node.name %}

    {# Stream Type #}
    {% if desiredState.config.sourceType == 'Table' %}
        {% set streamType = 'TABLE' %}
        {% set streamSourceObjectName = fullyQualifiedSourceTableName %}
    {% elif desiredState.config.sourceType == 'Dynamic Table' %}
        {% set streamType = 'DYNAMIC TABLE' %}
        {% set streamSourceObjectName = fullyQualifiedSourceTableName %}
    {% elif desiredState.config.sourceType == 'External Table' %}
        {% set streamType = 'EXTERNAL TABLE' %}
        {% set streamSourceObjectName = fullyQualifiedSourceTableName %}
    {% elif desiredState.config.sourceType == 'External Iceberg Table' %} 
        {% set streamType = 'TABLE' %}
        {% set streamSourceObjectName = fullyQualifiedSourceTableName %}
    {% elif desiredState.config.sourceType == 'Directory Table' %}
        {% set streamType = 'STAGE' %}
        {% set streamSourceObjectName = desiredState.config.stageName %}
    {% else %}
        {% set streamType = 'VIEW' %}
        {% set streamSourceObjectName = fullyQualifiedSourceTableName %}
    {% endif %}

    {# Stream Append Behavior #}
    {% if  (streamType == 'TABLE' and desiredState.config.sourceType != 'External Iceberg Table') or streamType == 'VIEW' %}
        {% if desiredState.config.appendOnly == true %}
            {% set streamAppendMode = 'APPEND_ONLY = TRUE' %}
        {% else %}
            {% set streamAppendMode = 'APPEND_ONLY = FALSE' %}
        {% endif %}
    {% else %}
        {% set streamAppendMode = '' %}
    {% endif %}

    {# Stream Initial Row Behavior #}
    {% if (streamType == 'TABLE' and desiredState.config.sourceType != 'External Iceberg Table') or streamType == 'VIEW' or streamType == 'DYNAMIC TABLE'%}
        {% if desiredState.config.initialRows == true %}
            {% set streamInitialRowsMode = 'SHOW_INITIAL_ROWS = TRUE' %}
        {% else %}
            {% set streamInitialRowsMode = 'SHOW_INITIAL_ROWS = FALSE' %}
        {% endif %}
    {% else %}
        {% set streamInitialRowsMode = '' %}
    {% endif %}

    {# Stream Insert Only Behavior #}
    {% if streamType == 'EXTERNAL TABLE' or desiredState.config.sourceType == 'External Iceberg Table' %}      
            {% set streamInsertOnlyMode = 'INSERT_ONLY = TRUE' %}
    {% else %}
        {% set streamInsertOnlyMode = '' %}
    {% endif %}
{% endif %}


{# Create Stream first #}

{% if desiredState and currentState != desiredState%}

    {% if currentState == undefined %}
        {{ stage('Create Stream',true,"sql","create") }}
        CREATE OR REPLACE STREAM {{ ref(streamTargetLocationName, streamName) }}
            ON {{ streamType }} {{ refLink }}
            {{ streamAppendMode }}
            {{ streamInitialRowsMode }}
            {{ streamInsertOnlyMode }}


    {% elif currentState != undefined and desiredState.config.redeploymentBehavior == 'Create If Not Exists'%}
        {{ stage('Create Stream If Not Exists',true,"sql","create") }}
        CREATE STREAM IF NOT EXISTS {{ ref(streamTargetLocationName, streamName) }}
            ON {{ streamType }} {{ refLink }}
            {{ streamAppendMode }}
            {{ streamInitialRowsMode }}
            {{ streamInsertOnlyMode }}

    {% elif currentState != undefined and desiredState.config.redeploymentBehavior == 'Create At Existing Stream'%}
        {{ stage('Re-Create Stream at existing offset',true,"sql","create") }}
        CREATE OR REPLACE STREAM {{ ref(streamTargetLocationName, streamName) }}
            ON {{ streamType }} {{ refLink }}
            AT(STREAM => '{{ ref(streamTargetLocationName, streamName) }}');

        {% elif currentState != undefined and desiredState.config.redeploymentBehavior == 'Create or Replace'%}
        {{ stage('Create Stream',true,"sql","create") }}
        CREATE OR REPLACE STREAM {{ ref(streamTargetLocationName, streamName) }}
            ON {{ streamType }} {{ refLink }}
            {{ streamAppendMode }}
            {{ streamInitialRowsMode }}
            {{ streamInsertOnlyMode }}
{% endif %}


{% elif desiredState == undefined and currentState.storageLocations | length > 0%}

    {# Source Stream Location and Name #}
    {% set streamTargetLocationName = currentState.node.location.name %}
    {% set streamTargetDatabaseName = currentState.storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='database') | first %}
    {% set streamTargetSchemaName = currentState.storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='schema') | first %}
    {% set streamName = currentState.node.name + '_STREAM' %}


    {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
    {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
    DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}
 {% endif %}

{# Create / Alter Table Second #}

{% if desiredState and currentState != desiredState %}

    {%- if currentState != undefined and currentState.node.nodeType != desiredState.node.nodeType %}
        {%- set warningMsg = getNodeTypeSwitchWarning() | default('') %}

        {# Warning display - Node type changes can impact related tasks, streams, or services. #}
        {%- if warningMsg | trim | length > 0 -%}
            {{ stage('Warning! Node Type Switching Detected', false) }}
            {{ warningMsg }}
            select 1=0
        {%- endif -%}
    {%- endif -%}

    {% if desiredState.config.createas == 'table' or desiredState.config.createas == 'transient table'  %}

        {# Figure out cluster key #}
        {% set nsVariables = namespace(finalClusterKey="") %}
        {% if desiredState.config.clusterKey == true %}
            {% if desiredState.config.clusterKeyExpressions == true %}
                {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='columnNameExpressions.name') | list, desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='sqlExpression') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% if expression[loop.index0] == "" %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues   + ['"'+r+'"'] %}
                    {% else %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + [expression[loop.index0]] %}
                    {% endif %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% else %}

                {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% set nsVariables.clusterValues = nsVariables.clusterValues  + ['"'+r+'"'] %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% endif %}
        {% endif %}


        {% if  currentState != undefined and (currentState.config.createas | default('') != desiredState.config.createas or currentState.node.materializationType | lower not in ['task', 'table']) %}

            {# Change in materialization type #}
            {% if currentState != undefined and currentState.node.materializationType != desiredState.node.materializationType %}
                {# Change in materialization type #}

                {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
                {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
                DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}
            {% endif %}

                {{ stage('Create Work '+ ' {{desiredState.config.createas}}',true,"sql","create") }}
               CREATE OR REPLACE {{desiredState.config.createas}} {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                (
                {% for col in desiredState.columns %}
                    "{{ col.name }}" {{ col.dataType }}
                    {%- if not col.nullable %} NOT NULL
                        {%- if col.defaultValue | length > 0 %} DEFAULT {{ col.defaultValue }}{% endif %}
                    {% endif %}
                    {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
                    {%- if not loop.last -%}, {% endif %}
                {% endfor %}
                )
               {%- if desiredState.node.description | length > 0 %} COMMENT = '{{ desiredState.node.description | escape }}'{% endif %}

               {% if desiredState.config.clusterKey == true %}
                  {{ stage('Apply Table Clustering',true,"sql","create") }}
                 ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }} {{ nsVariables.finalClusterKey }}

                   {{ stage('Resume Recluster Table',true,"sql","create") }}
                  ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }} RESUME RECLUSTER

               {% endif %}

        {% endif %}

       {% if currentState == undefined or currentState.storageLocations | length == 0%}
            {{ stage('Create Work '+ ' {{desiredState.config.createas}}',true,"sql","create") }}
            CREATE OR REPLACE {{desiredState.config.createas}} {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
            (
                {% for col in desiredState.columns %}
                    "{{ col.name }}" {{ col.dataType }}
                    {%- if not col.nullable %} NOT NULL
                        {%- if col.defaultValue | length > 0 %} DEFAULT {{ col.defaultValue }}{% endif %}
                    {% endif %}
                    {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
