        {% if desiredState.config.schedulingMode == 'Warehouse Task' %}
            {# Can be updated during deployment via a parameter to account for different warehouse names in different deployments #}
            {% if 'targetTaskWarehouse' in desiredState.parameters %}
                {% if desiredState.parameters.targetTaskWarehouse == 'DEV ENVIRONMENT' %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.config.whName %}
                {% else %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.parameters.targetTaskWarehouse %}
                {% endif %}
            {% endif %}
        {%- else -%}
            {% set taskType = 'USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = ' + getServerSize(desiredState.config.serverlessSize) -%}
            {%- if desiredState.config.sizeBoundToggle -%}
                {% set minSrvSize = 'SERVERLESS_TASK_MIN_STATEMENT_SIZE = ' + getServerSize(desiredState.config.minServerlessSize) -%}
                {% set maxSrvSize = 'SERVERLESS_TASK_MAX_STATEMENT_SIZE = ' + getServerSize(desiredState.config.maxServerlessSize) -%}
            {%- endif -%} 
        {%- endif -%}

        {# Schedule Type #}
        {%- if desiredState.config.schedulePeriodOption == 'Minutes' %}
            {%- set execValue = desiredState.config.get('execTime', {})
                                .get('items', [])
                                | map(attribute='value')
                                | first
            %}
            {%- set execPeriod = desiredState.config.get('execTime', {})
                                .get('items', [])
                                | map(attribute='period')
                                | first
            %}
            {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + execValue | trim ~ ' ' ~ execPeriod | trim + "'" %}
        {% elif desiredState.config.schedulePeriodOption == 'CRON' %}
            {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + 'USING CRON ' + desiredState.config.scheduleCRON | trim + "'" %}
        {% else %}
            {%- set nsVariables.taskWhenRun = 'AFTER ' -%}
            {% set predecessorTasks = (desiredState.config.predTask).split(",") %}

            {% for p in predecessorTasks %}
                {% set nsVariables.taskWhenRun = nsVariables.taskWhenRun + targetTableDatabase + '.' + targetTableSchema + '.' + p %}
                {% if not loop.last %}
                    {% set nsVariables.taskWhenRun = nsVariables.taskWhenRun + ',' %}
                {% endif %}
            {% endfor %}    
        {% endif %}

        {# When Stream has data logic #}
        {# Source Stream Location and Name #}
        {% if desiredState.config.flagSrcStream == true %}
            {% if nsVariables.poll == 'WHEN ' %}
                {% set nsVariables.poll = nsVariables.poll + 'SYSTEM$STREAM_HAS_DATA (\'' + ref(streamTargetLocationName, streamName) + '\')' %}							
            {% endif %}
        {% endif %}

        {% set tableColumnIds = desiredState.columns | map(attribute='id') | list %}
        {% set tableColumnNames = desiredState.columns | map(attribute='name') | list %}
        {%- set nsTaskVar = namespace(nodeComment='',
                                    userServiceAcct='',
                                    suspendTask='',
                                    autoTry='',
                                    overLapExec='',
                                    configJSON='',
                                    errorIntegration='',
                                    successIntegration='') %}
        {{ getadvancedTaskOptions(nsTaskVar) }}

        {{ stage('Create Task',true,"sql","create") }}
        CREATE OR REPLACE TASK
            {{ fullyQualifiedTaskName }}
            {{ taskType }}
            {% if desiredState.config.schedulingMode == 'Serverless Task' and desiredState.config.sizeBoundToggle -%}
                {{ minSrvSize }}
                {{ maxSrvSize }}
            {% endif -%}
            {{ nsTaskVar.nodeComment }}
            {{ nsVariables.taskWhenRun }}
            {%- if desiredState.config.schedulePeriodOption != 'Predecessor' %}
                {{ nsTaskVar.overLapExec }}
                {%- if desiredState.config.autoSuspendToggle %}
                {{ nsTaskVar.suspendTask }}
                {%- endif %}
                {%- if desiredState.config.autoRetryToggle %}
                    {{ nsTaskVar.autoTry }}
                {%- endif %}
                {%- if desiredState.config.taskGraphToggle %}
                    {{ nsTaskVar.configJSON }}
                {%- endif %}
            {%- if desiredState.config.errNotifyToggle %}
                {{ nsTaskVar.errorIntegration }}
            {%- endif %}
            {%- if desiredState.config.successNotifyToggle %}
                {{ nsTaskVar.successIntegration }}
            {%- endif %}
            {%- endif %}
            {%- if desiredState.config.spfcUserToggle %}
                {{ nsTaskVar.userServiceAcct }}
            {%- endif %}
            {% if nsVariables.poll != 'WHEN ' %} {{ nsVariables.poll }} {% endif %}
        AS
       BEGIN
            BEGIN TRANSACTION;
            {# First MERGE: Handle DELETEs (both standalone and DELETE portion of UPDATEs) #}
            MERGE INTO {{ fullyQualifiedTargetTableName }} tgt USING
            -- Select Statement Preparing Data for Merge - DELETE Operations
            (SELECT  
                    {% for id in tableColumnIds %}

                        {% set columnTransformation = desiredState.sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='transform') | first -%}
                        {%- if columnTransformation == "" -%}
                        {% set col =  desiredState.sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='sourceColumns') | first  |  map(attribute='column')  | list |  map(attribute='name') | first   -%}
                        "{{ col }}" as "{{ col }}" {%- if not loop.last -%}, {%- endif -%}
                        {%- else -%}
                        {% set col = desiredState.sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='name') | first -%}
                        {{ columnTransformation | replace(ns.sourceTableName, streamName) }} as "{{ col }}" {%- if not loop.last -%}, {%- endif -%}
                        {%- endif %}
                    {%- endfor %}
                    ,"METADATA$ACTION" AS METADATA$ACTION,
                    "METADATA$ISUPDATE" AS METADATA$ISUPDATE    
            FROM {{ ref(streamTargetLocationName, streamName) }}
            WHERE METADATA$ACTION = 'DELETE'
            AND   METADATA$ISUPDATE = FALSE

            {% set join_clause = ret_clause.lstrip() | replace("AND ", "WHERE ", 1) if ret_clause.lstrip().startswith("AND ") else ret_clause %}
            {% if join_clause.strip() != "" %}
                AND ({{ join_clause }})
            {% endif %}
            {% if desiredState.config.latestRowFromSource %}
              QUALIFY {{ nsVariables.rowNumber }} = 1
            {% endif %}
            {{after_order_by}}
            ) src

            -- Join Condition
            ON {% for col in nsVariables.tableKey -%}
                src."{{ col }}" = tgt."{{ col }}"
            {% if not loop.last %} AND {% endif %}
                {%- endfor -%}

            -- Handle all DELETE operations (standalone deletes and DELETE portion of updates)
            WHEN MATCHED AND METADATA$ACTION = 'DELETE'
            THEN DELETE;

            {# Second MERGE: Handle INSERTs and UPDATEs #}
            MERGE INTO {{ fullyQualifiedTargetTableName }} tgt USING
            -- Select Statement Preparing Data for Merge - INSERT/UPDATE Operations
            (SELECT  
                    {% for id in tableColumnIds %}

                        {% set columnTransformation = desiredState.sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='transform') | first -%}
                        {%- if columnTransformation == "" -%}
                        {% set col =  desiredState.sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='sourceColumns') | first  |  map(attribute='column')  | list |  map(attribute='name') | first   -%}
                        "{{ col }}" as "{{ col }}" {%- if not loop.last -%}, {%- endif -%}
                        {%- else -%}
                        {% set col = desiredState.sources[0].columns | selectattr('id', 'equalto', id) | map(attribute='name') | first -%}
                        {{ columnTransformation | replace(ns.sourceTableName, streamName) }} as "{{ col }}" {%- if not loop.last -%}, {%- endif -%}
                        {%- endif %}
                    {%- endfor %}
                    ,"METADATA$ACTION" AS METADATA$ACTION,
                    "METADATA$ISUPDATE" AS METADATA$ISUPDATE    
            FROM {{ ref(streamTargetLocationName, streamName) }}
            WHERE METADATA$ACTION = 'INSERT'

            {% if join_clause.strip() != "" %}
                AND ({{ join_clause }})
            {% endif %}
            {% if desiredState.config.latestRowFromSource %}
                QUALIFY {{ nsVariables.rowNumber }} = 1
            {% endif %}
            {{after_order_by}}
            ) src

            -- Join Condition
            ON {% for col in nsVariables.tableKey -%}
                src."{{ col }}" = tgt."{{ col }}"
            {% if not loop.last %} AND {% endif %}
                {%- endfor -%}

            -- What to do if data is matched based on table key
            WHEN MATCHED AND METADATA$ACTION = 'INSERT' AND METADATA$ISUPDATE = 'TRUE' THEN UPDATE SET 
                {%- for col in desiredState.columns %}
                    {% if not (col.isBusinessKey or col.isSystemCreateDate)%}
                        tgt."{{ col.name }}" = src."{{ col.name }}"
                        {%- if not loop.last -%}, {%- endif %}
                    {% endif %}
                {%- endfor %}
            -- What to do with new records based on table key
            WHEN NOT MATCHED AND METADATA$ACTION = 'INSERT' AND METADATA$ISUPDATE = 'FALSE' THEN INSERT 
                (
                {%- for col in desiredState.columns -%}
                    "{{ col.name }}"
                    {%- if not loop.last -%}, {% endif %}
                {% endfor %}) 
            VALUES (
                {%- for col in desiredState.columns -%}
                    src."{{ col.name }}"
                    {%- if not loop.last -%}, {% endif %}
                {% endfor %});
        COMMIT;
        EXCEPTION
        WHEN OTHER THEN
            -- If any error occurs, rollback
            ROLLBACK;
            -- Optionally re-raise the exception to see the error details
        RAISE;
        END;

        {% if desiredState.config.schedulePeriodOption != 'Predecessor' %}
            {{ stage('Resume Task',true,"sql","create") }}
            ALTER TASK {{ fullyQualifiedTaskName }} RESUME;
        {% endif %}
    {% endif %}

{% elif currentState != undefined and desiredState == undefined %}
    {# Target Table Info #}
    {% set targetTableDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %}
    {% set targetTableSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %}
    {% set fullyQualifiedTargetTableName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

    {% if currentState.config.devMode | default(false) == false %}
        {# FQ Root Task name #}							   
        {% set fullyQualifiedRootTaskName = ref_no_link(currentState.node.location.name, currentState.config.rootTask | default('')) %}

        {# Task Info #}
        {% set taskName = currentState.node.name + '_TASK' %}
        {% set fullyQualifiedTaskName = ref_no_link(currentState.node.location.name, taskName) %}

        {% if currentState.config.schedulePeriodOption | default('') == 'Predecessor' %}
            {{ stage('Suspend Root Task') }}
            ALTER TASK IF EXISTS {{ fullyQualifiedRootTaskName }} SUSPEND
            {{ stage('Drop Current Task') }}
            DROP TASK IF EXISTS {{ fullyQualifiedTaskName }}
        {% else %}
            {{ stage('Drop Current Task') }}
            DROP TASK IF EXISTS {{ fullyQualifiedTaskName }}
        {% endif %}
    {% endif %}
{% endif %}

run.templateString:
{#
        Copyright (c) 2025 Coalesce. All rights reserved.
    This script and its associated documentation are confidential and proprietary to Coalesce.
    Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
    Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
    does not permit copying or modification for any other purpose.  
    #}
    {# == Node Type Name           : Insert Or Merge With Task == #}
    {# == Node Type Description    : This node insert data into table == #}

{# Development mode -To test the SQL the task will execute to make sure it runs without errors and returns the expected data #}

{% if config.devMode == true %}

    {% set nsVariables = namespace() %}

    {# To mimic truncate behavior only incase of insert loadType#}
    {% if config.loadType == 'Insert' %}
        {% if config.truncateBefore %}
            {% set truncateBehavior = 'INSERT OVERWRITE' %}
        {% else %}
            {% set truncateBehavior = 'INSERT' %}
        {% endif -%}
    {% endif -%}

    {# Merge partition by and order by #}
    {%- if config.loadType == 'Merge' -%}
        {% set tableColumnNames = columns
                                    | map(attribute='name')
                                    | list %}
        {% set tableColumnNamesUpdate = tableColumnNames
                                            | reject('in', config.partitionBy.get('items')
                                            | map(attribute='partColName.name'))
                                            | list %}

        {% for partCol in config.partitionBy.get('items') %}
            {%- if loop.first -%}
                {% set nsVariables.partition = '"' + partCol.partColName.name + '"' %}
            {% else %}
                {% set nsVariables.partition = nsVariables.partition + ', "' + partCol.partColName.name + '"' %}
            {%- endif -%}

            {% set tableColumnNamesUpdate = tableColumnNames | reject('in', partCol.partColName.name) | list %}
        {% endfor %}

        {% for ordCol in config.mergeOrderBy.get('items') %}
            {%- if loop.first -%}
                {% set nsVariables.mergeOrderBy = '"' + ordCol.colName.name + '" ' + ordCol.sortOrd %}
            {% else %}
                {% set nsVariables.mergeOrderBy = nsVariables.mergeOrderBy + ', "' + ordCol.colName.name + '" ' + ordCol.sortOrd %}
            {%- endif -%}
        {% endfor %}

        {% set nsVariables.rowNumber = 'ROW_NUMBER() OVER (PARTITION BY ' + nsVariables.partition + ' ORDER BY ' + nsVariables.mergeOrderBy + ')' %}

        {%- set nsVariables.tableKey = config.partitionBy.get('items') %}
        {% set nsVariables.tableKey = nsVariables.tableKey | map(attribute='partColName.name') | list %}
    {%- endif -%}

    {{ stage('Insert or Merge Data') }}

        {% if config.loadType == 'Insert' -%} 
            {{ truncateBehavior }} INTO {{ ref_no_link(node.location.name, node.name) }}
            (
                {% for col in columns %}
                    "{{ col.name }}"
                    {%- if not loop.last -%},{% endif %}
                {% endfor %}
            )
            {% for source in sources %}
                /* Combine Sources if needed */
                    {% if loop.first %}
                SELECT
                    {% if config.selectDistinct %}
                DISTINCT
                    {% endif %}
                    {% for col in columns  %}
                "{{ col.name }}" AS "{{ col.name }}"
                    {% if not loop.last %}, {% endif %}
                    {% endfor %}
                FROM
                (
                        {% endif %}
                    SELECT
                        {% if config.selectDistinct %}
                    DISTINCT
                        {% endif %}
                        {% for col in source.columns %}
                    {{ get_source_transform(col) }} AS "{{ col.name }}"{% if not loop.last %}, {% endif %}
                        {% endfor %}
                    {{ source.join }}                  
                        {% if not loop.last %}
                    {{ config.insertStrategy }}
                        {% endif %}
                        {% if loop.last %}
                )
                        {% endif %}
                    {% endfor %}
                    {% if config.groupByAll %}
                GROUP BY ALL
                    {% endif %}
                {{ sortorder_by_colv() }}
            {% else -%}
            MERGE INTO {{ ref_no_link(node.location.name, node.name) }} tgt USING
        -- Select Statement Preparing Data for Merge
        (
            {% for source in sources %}
                /* Combine Sources if needed */
                        {% if loop.first %}
                    SELECT
                        {% if config.selectDistinct %}
                    DISTINCT
                        {% endif %}
                        {% for col in columns  %}
                    "{{ col.name }}" AS "{{ col.name }}"
                        {% if not loop.last %}, {% endif %}
                        {% endfor %}
                    FROM
                    (
                            {% endif %}
                        SELECT
                            {% if config.selectDistinct %}
                        DISTINCT
                            {% endif %}
                            {% for col in source.columns %}
                        {{ get_source_transform(col) }} AS "{{ col.name }}"{% if not loop.last %}, {% endif %}
                            {% endfor %}
                        {{ source.join }}                 
                            {% if not loop.last %}
                        {{ config.insertStrategy }}
                            {% endif %}
                            {% if loop.last %}
                    )
                        {% endif %}
                        {% endfor %}
                        {% if config.groupByAll %}
                    GROUP BY ALL{% endif %}
                    QUALIFY {{ nsVariables.rowNumber }} = 1
                    {{ sortorder_by_colv() }}
                ) src
                -- Join Condition
            ON
                {% for col in nsVariables.tableKey -%}
            src."{{ col }}" = tgt."{{ col }}"
                    {% if not loop.last %} AND {% endif %}
                {%- endfor -%}
                -- What to do if data is matched based on table key
            WHEN MATCHED THEN UPDATE SET
                {%- for col in tableColumnNamesUpdate %}
                    {% if col not in ["SYSTEM_CREATE_DATE"]%}
            tgt."{{ col }}" = src."{{ col }}"
                        {%- if not loop.last -%}, {%- endif %}
                    {% endif %}
                {%- endfor %}
            -- What to do with new records based on table key
            WHEN NOT MATCHED THEN INSERT
                (
                {%- for col in columns -%}
            "{{ col.name }}"
                        {%- if not loop.last -%}, {% endif %}
                {% endfor %})
            VALUES (                                                        
                {%- for col in columns -%}
            src."{{ col.name }}"
                        {%- if not loop.last -%}, {% endif %}
                {% endfor %}
        )
            {%- endif -%}
{% else %}
    {{ stage('Task Mode - No Manual Run') }}
    -- This node is configured to run as a scheduled task
    -- Manual Run is only available when Development Mode is enabled
    -- To execute this task, wait for the scheduled run or manually execute: EXECUTE TASK {{node.name + '_TASK'}}
    SELECT 1 AS INFO_MESSAGE WHERE FALSE
{% endif -%}

create.templateString:
{#
        Copyright (c) 2025 Coalesce. All rights reserved.
    This script and its associated documentation are confidential and proprietary to Coalesce.
    Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
    Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
    does not permit copying or modification for any other purpose.  
    #}
    {# == Node Type Name           : Insert Or Merge With Task == #}
    {# == Node Type Description    : This node creates a work table and a task to insert data into work table == #}

{# Parameter Check for Deployment #}
{% if desiredState and currentState != desiredState and desiredState.config.schedulingMode == 'Warehouse Task' %}
    {% if desiredState.parameters == {}
        or 'targetTaskWarehouse' not in  desiredState.parameters
        or desiredState.parameters.targetTaskWarehouse == '' %}

        {{ stage('WARNING') }}

        /* Add parameter targetTaskWarehouse in workspace settings and deployment environment for successful execution of node.
        The default value for the parameter is 'DEV ENVIRONMENT'.
        For more information, refer to the documentation. */

    {% endif %}
{% endif %}

{# Create / Alter (Transient/)Table first #}

{% if desiredState and desiredState != currentState %}

    {%- if currentState != undefined and currentState.node.nodeType != desiredState.node.nodeType %}
        {%- set warningMsg = getNodeTypeSwitchWarning() | default('') %}

        {# Warning display - Node type changes can impact related tasks, streams, or services. #}
        {%- if warningMsg | trim | length > 0 -%}
            {{ stage('Warning! Node Type Switching Detected', false) }}
            {{ warningMsg }}
            select 1=0
        {%- endif -%}
    {%- endif -%}

    {# Target Table Info #}
    {% set targetTableDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %} 
    {% set targetTableSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetTableName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}

    {% if currentState == undefined
            or (currentState != defined and currentState.storageLocations | length == 0)
            or (currentState != defined and currentState.node.materializationType != desiredState.node.materializationType)  
            or (currentState.node.materializationType | lower not in ['task', 'table']) %}

        {# Figure out cluster key #}
        {% set nsVariables = namespace(finalClusterKey = "") %}
        {% if desiredState.config.clusterKey == true %}
            {% if desiredState.config.clusterKeyExpressions == true %}
                {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items')
                                            | map(attribute='columnNameExpressions.name')
                                            | list, desiredState.config.clusterKeyConfigExpressions.get('items')
                                            | map(attribute='sqlExpression')
                                            | list %}

                {%- set nsVariables = namespace(clusterValues = []) %}

                {% for clustCol in column %}
                    {% if expression[loop.index0] == "" %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"' + clustCol + '"'] %}
                    {% else %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + [expression[loop.index0]] %}
                    {% endif %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% else %}

                {% set column = desiredState.config.clusterKeyConfig.get('items')
                                | map(attribute='columnName.name')
                                | list %}

                {%- set nsVariables = namespace(clusterValues = []) %}

                {% for clustCol in column %}
                    {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"' + clustCol + '"'] %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% endif %}
        {% endif %}

        {# Change in materialization type #}
        {% if currentState != defined and currentState.node.materializationType != desiredState.node.materializationType %}

            {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
            {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
            DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

        {% endif %}

        {{ stage('Create ' ~ desiredState.node.materializationType, true, "sql", "create") }}
        CREATE OR REPLACE {{ desiredState.node.materializationType }} {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
        (
            {% for col in desiredState.columns %}
                "{{ col.name }}" {{ col.dataType }}
                {%- if not col.nullable %} NOT NULL
                    {%- if col.defaultValue | length > 0 %}
                        DEFAULT {{ col.defaultValue }}
                    {% endif %}
                {% endif %}
                {%- if col.description | length > 0 %}
                    COMMENT '{{ col.description | escape }}'
                {% endif %}
                {%- if not loop.last -%}, {% endif %}
            {% endfor %}
        )
        {%- if desiredState.node.description | length > 0 %}
            COMMENT = '{{ desiredState.node.description | escape }}'
        {% endif %}

        {% if desiredState.config.clusterKey == true %}
            {{ stage('Apply Table Clustering', true, "sql", "create") }}
            ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }} {{ nsVariables.finalClusterKey }}

            {{ stage('Resume Recluster Table', true, "sql", "create") }}
            ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }} RESUME RECLUSTER
        {% endif %}

    {% elif currentState != undefined %}

        {# Change Node Name or Change Storage Location #}
        {# Storage Location Tests #}
        {# Only need to account for updated Storage Location mappings   #}     
        {# Current and Desired Namespace Varialbes initialisation #}

        {% set nsVariables = namespace(storageLocationTest = true) %}

        {% if desiredState.config.devMode %}
            {% set nsMetaVariables = namespace(
                joinTest            = true,
                transformTest       = true,
                sourceLinkTest      = true,
                orderByTest         = true,
                mergeOrderByTest    = true,
                metaDataChanged     = false,
                joinDiff            = [],
                transformDiff       = [],
                sourceLinkDiff      = [],
                insertStrategyDiff  = [],
                truncateBeforeDiff  = [],
                distinctDiff        = [],
                groupByAllDiff      = [],
                orderByDiff         = [],
                loadTypeDiff        = [],
                partByDiff          = [],
                mergeOrderByDiff    = [],
                metaDataChanges     = [],
                metadataUpdate      = 'Metadata Update'
            ) %}
        {% endif %}

        {% if currentState.storageLocations|length == 0 %}          
            {% set currentDatabase = currentState.storageLocations
                                    | selectattr('name', 'equalto', currentState.node.location.name)
                                    | map(attribute='database')
                                    | string %}
            {% set currentSchema = currentState.storageLocations
                                    | selectattr('name', 'equalto', currentState.node.location.name)
                                    | map(attribute='schema')
                                    | string %}
            {% set currentDatabaseSchema = currentDatabase + '.' + currentSchema %}

        {% else %}

            {# Current target node mappings #}
            {% set currentDatabase = currentState.storageLocations
                                    | selectattr('name', 'equalto', currentState.node.location.name)
                                    | map(attribute='database')
                                    | first %}
            {% set currentSchema = currentState.storageLocations
                                    | selectattr('name', 'equalto', currentState.node.location.name)
                                    | map(attribute='schema')
                                    | first %}
            {% set currentDatabaseSchema = currentDatabase + '.' + currentSchema %}  
        {% endif %}		 

        {# Desired target node mappings #}
        {% set desiredDatabase = desiredState.storageLocations
                                | selectattr('name', 'equalto', desiredState.node.location.name)
                                | map(attribute='database')
                                | first %}
        {% set desiredSchema = desiredState.storageLocations
                                | selectattr('name', 'equalto', desiredState.node.location.name)
                                | map(attribute='schema')
                                | first %}
        {% set desiredDatabaseSchema = desiredDatabase + '.' + desiredSchema %}           

        {% if currentDatabaseSchema != desiredDatabaseSchema %}
            {% set nsVariables.storageLocationTest = false %}
        {% endif %}

        {% set nodeCommentTest = currentState.node.description == desiredState.node.description %}

        {# Rename / Move Object #}
        {% if (nsVariables.storageLocationTest == false
                or currentState.node.name != desiredState.node.name) %}

            {{ stage('Rename and / or Move Table') }}
            {% set srcSchName = currentState.node.location.name %}
            {% set cdb = currentState.storageLocations
                        | selectattr('name', 'equalto', srcSchName)
                        | map(attribute='database')
                        | first %}
            {% set csch = currentState.storageLocations
                        | selectattr('name', 'equalto', srcSchName)
                        | map(attribute='schema')
                        | first %}

            ALTER TABLE  "{{cdb}}"."{{csch}}"."{{currentState.node.name}}"
            RENAME TO   {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}

            {# Metadata changes detected #}
            {% if desiredState.config.devMode %}
                {% set nsMetaVariables.metaDataChanged = true %}
            {%endif%}
        {% endif %}

        {# Change table description #}
        {% if (nodeCommentTest == false or currentState.node.description != desiredState.node.description) %}

            {{ stage('Change table description') }}
            ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
            SET COMMENT = '{{ desiredState.node.description | escape }}'

            {# Metadata changes detected #}
            {% if desiredState.config.devMode %}
                {% set nsMetaVariables.metaDataChanged = true %}
            {%endif%}

        {% endif %}

        {# Drop Columns #}
        {% set nsVariables = namespace(colchanges = 0) %}
        {% for dropCurCol in currentState.columns %}
            {% if dropCurCol.id not in desiredState.columns | map(attribute="id") %}
                {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}

                {% if nsVariables.colchanges == 1 %}
                    {{ stage('Drop Columns') }}
                    ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                    DROP COLUMN 
                {% else %}
                    , 
                {% endif %}
                "{{ dropCurCol.name }}"

                {# Metadata changes detected #}
                {% if desiredState.config.devMode %}
                    {% set nsMetaVariables.metaDataChanged = true %}
                {%endif%}

            {% endif %}
        {% endfor %}

        {# Add Columns #}
        {% set nsVariables = namespace(colchanges = 0) %}
        {% for addDesCol in desiredState.columns %}
            {% if addDesCol.id not in currentState.columns | map(attribute="id") %}
                {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}

                {% if nsVariables.colchanges == 1 %}
                    {{ stage('Add Columns') }}
                    ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                    ADD COLUMN
                {% else %}
                    ,
                {% endif %}
                "{{ addDesCol.name }}" {{ addDesCol.dataType }}
                {%- if not addDesCol.nullable %} NOT NULL
                    {%- if addDesCol.defaultValue | length > 0 %} DEFAULT {{ addDesCol.defaultValue }}{% endif %}
                {% endif %}
                {%- if addDesCol.description | length > 0 %} COMMENT '{{ addDesCol.description | escape }}'{% endif %}

                {# Metadata changes detected #}
                {% if desiredState.config.devMode %}
                    {% set nsMetaVariables.metaDataChanged = true %}
                {%endif%}

            {% endif %}
        {% endfor %}

        {# Rename Columns #}
        {% for renameCurCol in currentState.columns %}
            {% if renameCurCol.id in desiredState.columns | map(attribute="id") %}
                {% set desiredColumnName = desiredState.columns
                                            | selectattr('id', 'equalto', renameCurCol.id)
                                            | map(attribute='name')
                                            | first %}
                {% if renameCurCol.name != desiredColumnName %}
                    {{ stage('Rename Column ' + renameCurCol.name) }}
                    ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                    RENAME COLUMN "{{ renameCurCol.name }}"
                    TO "{{ desiredColumnName }}"

                    {# Metadata changes detected #}
                    {% if desiredState.config.devMode %}
                        {% set nsMetaVariables.metaDataChanged = true %}
                    {%endif%}

                {% endif %}
            {% endif %}
        {% endfor %}

        {# Change data types or other column level chnages #}
        {% set nsVariables.colchanges = 0 %}
        {% for alterCurCol in currentState.columns %}        
            {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}
                {% set currentDatatype = alterCurCol.dataType %}
                {% set currentNullable = alterCurCol.nullable %}
                {% set currentDefaultValue = alterCurCol.defaultValue %}
                {% set currentDescription = alterCurCol.description %}

                {% set desiredColumnName = desiredState.columns
                                            | selectattr('id', "equalto", alterCurCol.id)
                                            | map(attribute='name')
                                            | first %}
                {% set desiredDatatype = desiredState.columns
                                        | selectattr('id', "equalto", alterCurCol.id)
                                        | map(attribute='dataType')
                                        | first %}
                {% set desiredNullable = desiredState.columns
                                        | selectattr('id', "equalto", alterCurCol.id)
                                        | map(attribute='nullable')
                                        | first %}
                {% set desiredDefaultValue = desiredState.columns
                                            | selectattr('id', "equalto", alterCurCol.id)
                                            | map(attribute='defaultValue')
                                            | first %}
                {% set desiredDescription = desiredState.columns
                                            | selectattr('id', "equalto", alterCurCol.id)
                                            | map(attribute='description')
                                            | first %}

                {% set datatypeTest = currentDatatype == desiredDatatype %}
                {% set nullableTest = currentNullable == desiredNullable %}
                {% set defaultValueTest = currentDefaultValue == desiredDefaultValue %}
                {% set descriptionTest = currentDescription == desiredDescription %}

                {% if (datatypeTest == false or 
                        nullableTest == false  or
                        defaultValueTest == false or
                        descriptionTest == false) %}
                    {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}

                    {% if nsVariables.colchanges == 1 %}
                        {{ stage('Change Column Attributes') }}
                        ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                        MODIFY
                    {% endif %}
                    {% if datatypeTest == false %}
                        {% if nsVariables.colchanges > 1 %},{% endif %}
                        COLUMN "{{ desiredColumnName }}"
                        SET DATA TYPE {{ desiredDatatype }}
                        {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                    {% endif %}
                    {% if nullableTest == false %}
                        {% if nsVariables.colchanges > 1 %},{% endif %}
                        COLUMN "{{ desiredColumnName }}"
                        {% if currentNullable == true %}
                            SET
                        {% else %}
                            DROP
                        {% endif %}
                        NOT NULL
                        {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                    {% endif %}
                    {% if descriptionTest == false %}
                        {% if nsVariables.colchanges > 1 %},{% endif %}
                        COLUMN "{{ desiredColumnName }}"
                        COMMENT '{{ desiredDescription | escape }}'
                        {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                    {% endif %}
                    {% if defaultValueTest == false %}
                        {% if nsVariables.colchanges > 1 %},{% endif %}
                        COLUMN "{{ desiredColumnName }}"
                        {% if desiredDefaultValue == '' %}
                            DROP DEFAULT
                        {% else %}
                            SET DEFAULT {{ desiredDefaultValue }}
                        {% endif %}
                        {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                    {% endif %}

                    {# Metadata changes detected #}
                    {% if desiredState.config.devMode %}
                        {% set nsMetaVariables.metaDataChanged = true %}
                    {%endif%}

                {% else %}

                {% endif %}
            {% endif %}
        {% endfor %}

        {# Clustering Test #}
        {% set clusterKeyTest = currentState.config.clusterKey | default(false) == desiredState.config.clusterKey %}
        {% set clusterKeyExpressionsTest = currentState.config.clusterKeyExpressions | default(false) == desiredState.config.clusterKeyExpressions %}
        {% set clusterKeyConfigTest = currentState.config.clusterKeyConfig  | default({'items': [{}]}) == desiredState.config.clusterKeyConfig %}
        {% set clusterKeyConfigExpressionsTest = currentState.config.clusterKeyConfigExpressions  | default({'items': [{}]}) == desiredState.config.clusterKeyConfigExpressions %}

        {% if 
            clusterKeyTest == false or
            clusterKeyExpressionsTest == false or
            clusterKeyConfigTest == false or
            clusterKeyConfigExpressionsTest == false %}

            {% set clusterTest = false %}
        {% else %}
            {% set clusterTest = true %}
        {% endif %}

        {# Figure out cluster key #}
        {% set nsVariables = namespace(finalClusterKey = "") %}
        {% if clusterTest == false %}
            {% if desiredState.config.clusterKey == true %}
                {% if desiredState.config.clusterKeyExpressions == true %}

                    {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='columnNameExpressions.name') | list, desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='sqlExpression') | list %}
                    {%- set nsVariables = namespace(clusterValues=[]) %}

                    {% for clustCol in column %}
                        {% if expression[loop.index0] == "" %}
                            {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"' + clustCol + '"'] %}
                        {% else %}
                            {% set nsVariables.clusterValues = nsVariables.clusterValues + [expression[loop.index0]] %}
                        {% endif %}
                    {% endfor %}

                    {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

                {% else %}

                    {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}
                    {%- set nsVariables = namespace(clusterValues=[]) %}

                    {% for clustCol in column %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"' + clustCol + '"'] %}
                    {% endfor %}

                    {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}
                {% endif %}

            {% else %}

                {% set nsVariables.finalClusterKey = 'DROP CLUSTERING KEY' %}

            {% endif %}

            {{ stage('Recluster TABLE') }}
            ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
            {{ nsVariables.finalClusterKey }}

            {# Metadata changes detected #}
            {% if desiredState.config.devMode %}
                {% set nsMetaVariables.metaDataChanged = true %}
            {%endif%}
        {%endif%}

        {% if desiredState.config.devMode %}
            {% if nsMetaVariables.metaDataChanged == false %}

                {# =========================================================
                Compare source counts
                ========================================================= #}
                {% set sourcesTest = currentState.sources | count == desiredState.sources | count %}

                {% if sourcesTest %}
                    {% for src in desiredState.sources %}
                        {% set matchingSource = currentState.sources | selectattr('name', 'equalto', src.name) | first %}
                        {% if matchingSource %}

                            {# =========================================================
                            Join comparison
                            ========================================================= #}
                            {% set desiredStateSources = src.join | replace("{{", '"{{"') | replace("}}", '"}}"') | replace('/*', '/ *') | replace('*/', '* /') %}
                            {% set currentStateSources = matchingSource.join | replace("{{", '"{{"') | replace("}}", '"}}"') | replace('/*', '/ *') | replace('*/', '* /') %}

                            {# Same number of sources — compare join transformations #}
                            {% if desiredStateSources != currentStateSources %}
                                {% set nsMetaVariables.joinTest = false %}
                                {% set _ = nsMetaVariables.joinDiff.append({
                                    "Source": src.name,
                                    "is": desiredStateSources,
                                    "was": currentStateSources }) %}
                            {% endif %}

                            {# =========================================================
                            Transformation and column source changes comparison (per column)
                            ========================================================= #}
                            {% for col in src.columns %}

                                {# Try to get matching column #}
                                {% set matched_column = matchingSource.columns
                                    | selectattr('id', 'equalto', col.id)
                                    | first
                                %}

                                {% if matched_column %}

                                    {# Transformation Changes #}
                                    {% set currentTransform = matchingSource.columns
                                        | selectattr('id', 'equalto', col.id)
                                        | map(attribute='transform')
                                        | first
                                        | default('')
                                    %}

                                    {% if currentTransform != col.transform %}
                                        {% set nsMetaVariables.transformTest = false %}
                                        {% set _ = nsMetaVariables.transformDiff.append({
                                            "Source Name": src.name,
                                            "Column Name": col.name,
                                            "is": col.transform | replace('/*', '/ *') | replace('*/', '* /'),
                                            "was": currentTransform | replace('/*', '/ *') | replace('*/', '* /')
                                        }) %}
                                    {% endif %}

                                    {# Column Source Changes #}
                                    {% set currentSource = matchingSource.columns
                                        | selectattr('id', 'equalto', col.id)
                                        | map(attribute='sourceColumns')
                                        | first
                                        | default('')
                                    %}

                                    {% if currentSource != col.sourceColumns %}
                                        {% set nsMetaVariables.sourceLinkTest = false %}
                                        {% set _ = nsMetaVariables.sourceLinkDiff.append({
                                            "Source Name": src.name,
                                            "Column Name": col.name,
                                            "is": (col.sourceColumns
                                                    | selectattr('node','defined')
                                                    | map(attribute='node.name')
                                                    | first)
                                                    | default('') ~ "-" ~ (col.sourceColumns
                                                    | selectattr('column','defined')
                                                    | map(attribute='column.name')
                                                    | first)
                                                    | default(''),
                                            "was": (currentSource | selectattr('node','defined')
                                                    | map(attribute='node.name')
                                                    | first)
                                                    | default('') ~ "-" ~ (currentSource
                                                    | selectattr('column','defined')
                                                    | map(attribute='column.name')
                                                    | first)
                                                    | default('')
                                        }) %}
                                    {% endif %}
                                {% endif %}
                            {% endfor %}
                        {% endif %}
                    {% endfor %}

                    {% if nsMetaVariables.transformTest == false %}
                        {{ update_metadata("Transform", nsMetaVariables.transformDiff, "Transform") }}
                    {% endif %}

                    {% if nsMetaVariables.sourceLinkTest == false %}
                        {{ update_metadata("Source Link", nsMetaVariables.sourceLinkDiff, "Source Link") }}
                    {% endif %}
                {% else %}
                    {# Source count mismatch — compare source names instead #}
                    {% set desiredStateSources = desiredState.sources | map(attribute='name') | list | sort %}
                    {% set currentStateSources = currentState.sources | map(attribute='name') | list | sort %}

                    {% if desiredStateSources != currentStateSources %}
                        {% set nsMetaVariables.joinTest = false %}
                        {% set _ = nsMetaVariables.joinDiff.append({"is": desiredStateSources, "was": currentStateSources }) %}
                    {% endif %}
                {% endif %}

                {% if nsMetaVariables.joinTest == false %}
                        {{ update_metadata("Join", nsMetaVariables.joinDiff, "Join") }}
                {% endif %}

                {# =========================================================
                Insert Strategy comparison
                ========================================================= #}
                {% if currentState.config.insertStrategy | default('') != desiredState.config.insertStrategy %}
                    {% set _ = nsMetaVariables.insertStrategyDiff.append({
                        "is": desiredState.config.insertStrategy,
                        "was": currentState.config.insertStrategy | default('')
                    }) %}

                    {{ update_metadata("Insert Strategy", nsMetaVariables.insertStrategyDiff, "Insert Strategy") }}

                {% endif %}

                {# =========================================================
                Truncate Table comparison
                ========================================================= #}
                {% if currentState.config.truncateBefore | default(false) != desiredState.config.truncateBefore %}
                    {% set _ = nsMetaVariables.truncateBeforeDiff.append({
                        "is": desiredState.config.truncateBefore,
                        "was": currentState.config.truncateBefore | default(false)
                    }) %}

                    {{ update_metadata("Truncate Before", nsMetaVariables.truncateBeforeDiff, "Truncate Before") }}

                {% endif %}

                {# =========================================================
                Distinct Toggle comparison
                ========================================================= #}
                {% if currentState.config.selectDistinct | default(false) != desiredState.config.selectDistinct %}
                    {% set _ = nsMetaVariables.distinctDiff.append({
                        "is": desiredState.config.selectDistinct,
                        "was": currentState.config.selectDistinct | default(false)
                    }) %}

                    {{ update_metadata("Distinct", nsMetaVariables.distinctDiff, "Distinct") }}

                {% endif %}

                {# =========================================================
                GroupByAll Toggle comparison
                ========================================================= #}
                {% if currentState.config.groupByAll | default(false) != desiredState.config.groupByAll %}
                    {% set _ = nsMetaVariables.groupByAllDiff.append({
                        "is": desiredState.config.groupByAll,
                        "was": currentState.config.groupByAll | default(false)
                    }) %}

                    {{ update_metadata("GroupByAll", nsMetaVariables.groupByAllDiff, "GroupByAll") }}

                {% endif %}

                {# =========================================================
                Order By comparison (per column)
                ========================================================= #}
                {% if currentState.config.orderby | default(false) != desiredState.config.orderby %}

                    {% set nsMetaVariables.orderByTest = false %}
                    {% set _ = nsMetaVariables.orderByDiff.append({
                            "is": desiredState.config.orderby,
                            "was": currentState.config.orderby | default(false)
                    }) %}

                {% elif currentState.config.orderby | default(false) and desiredState.config.orderby %}

                    {% set desiredSortColList = [] %}
                    {% set currentSortColList = [] %}

                    {# Desired Column sort order #}
                    {% for item in desiredState.config.orderbycolumn.get('items', []) %}
                        {% set _ = desiredSortColList.append({
                                    "Column Name": item.sortColName.name,
                                    "Sort Order": item.sortOrder
                        }) %}
                    {% endfor%}
                    {# Current Column sort order #}
                    {% for item in currentState.config.orderbycolumn.get('items', []) %}
                        {% set _ = currentSortColList.append({
                                    "Column Name": item.sortColName.name,
                                    "Sort Order": item.sortOrder
                        }) %}
                    {% endfor%}

                    {% if desiredSortColList != currentSortColList %}
                        {% set nsMetaVariables.orderByTest = false %}
                        {% set _ = nsMetaVariables.orderByDiff.append({
                            "is": desiredSortColList,
                            "was": currentSortColList
                        }) %}
                    {% endif %}
                    {% endif %}

                {% if nsMetaVariables.orderByTest == false %}
                    {{ update_metadata("Order By", nsMetaVariables.orderByDiff, "Order By") }}
                {% endif %}

                {# =========================================================
                DevMode Toggle comparison
                ========================================================= #}
                {% if currentState.config.devMode | default(false) != desiredState.config.devMode %}

                    {{ update_metadata("DevMode", {"is": desiredState.config.devMode, "was": currentState.config.devMode | default(false)}, "DevMode") }}

                {% endif %}

                {# =========================================================
                Load Type comparison
                ========================================================= #}
                {% if currentState.config.loadType | default('') != desiredState.config.loadType %}
                    {% set _ = nsMetaVariables.loadTypeDiff.append({
                        "is": desiredState.config.loadType,
                        "was": currentState.config.loadType | default('')
                    }) %}

                    {{ update_metadata("Load Type", nsMetaVariables.loadTypeDiff, "Load Type") }}

                {% elif currentState.config.loadType | default('') == desiredState.config.loadType == "Merge" %}

                    {# =========================================================
                    Record Date / Timestamp comparison
                    ========================================================= #}

                    {% set desiredSortColList = [] %}
                    {% set currentSortColList = [] %}

                    {# Desired Column sort order #}
                    {% for item in desiredState.config.mergeOrderBy.get('items', []) %}
                        {% set _ = desiredSortColList.append({
                                    "Column Name": item.colName.name,
                                    "Sort Order": item.sortOrd
                        }) %}
                    {% endfor%}
                    {# Current Column sort order #}
                    {% for item in currentState.config.mergeOrderBy.get('items', []) %}
                        {% set _ = currentSortColList.append({
                                    "Column Name": item.colName.name,
                                    "Sort Order": item.sortOrd
                        }) %}
                    {% endfor%}

                    {% if desiredSortColList != currentSortColList %}
                        {% set nsMetaVariables.mergeOrderByTest = false %}
                        {% set _ = nsMetaVariables.mergeOrderByDiff.append({
                            "is": desiredSortColList,
                            "was": currentSortColList
                        }) %}
                    {% endif %}

                    {% if nsMetaVariables.mergeOrderByTest == false %}
                        {{ update_metadata("Record Date / Timestamp", nsMetaVariables.mergeOrderByDiff, "Record Date / Timestamp") }}
                    {% endif %}

                    {# =========================================================
                    Table Key(s) comparison
                    ========================================================= #}
                    {% set desPartBy = desiredState.config.partitionBy["items"]
                                        | default([], true) 
                                        | map(attribute='partColName.name')
                                        | join(', ') %}

                    {% set currPartBy = currentState.config.partitionBy["items"]
                                        | default([], true) 
                                        | map(attribute='partColName.name')
                                        | join(', ') %}

                    {% if desPartBy != currPartBy %}
                        {% set _ = nsMetaVariables.partByDiff.append({
                            "is": desPartBy,
                            "was": currPartBy
                        }) %}

                        {{ update_metadata("Table Key(s)", nsMetaVariables.partByDiff, "Table Key(s)") }}

                    {% endif %}

                {% endif %}

                {# =========================================================
                Handle detected metadata changes and update
                ========================================================= #}
                {% if nsMetaVariables.metaDataChanges | length == 0 %}
                    {{ stage('Metadata Update-Default') }}
                {% else %}
                    {{ stage(nsMetaVariables.metadataUpdate) }}
                    -- Metadata changes detected
                    /* {{ nsMetaVariables.metaDataChanges }} */
                {% endif %}
                select 1=0
            {% endif %}
        {% endif %}
    {% endif %}

{% elif currentState != undefined and desiredState == undefined %}

    {# Table or View Name #}
    {% set targetObjectDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetObjectSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetObjectName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

    {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
    {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
    DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

{% endif %}

{# Create Task Second - only when DEV MODE is false #}

{% if desiredState and  desiredState != currentState %}

    {# Target Table Info #}
    {% set targetTableDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %} 
    {% set targetTableSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetTableName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}

    {% if desiredState.config.devMode == false %}
        {%- if desiredState.config.schedulePeriodOption == 'Predecessor' -%} 
            {% set fullyQualifiedRootTaskName = ref_no_link(desiredState.node.location.name, desiredState.config.rootTask) %}

            {{ stage('Suspend Root Task', true, "sql", "create") }}
            ALTER TASK {{ fullyQualifiedRootTaskName }} SUSPEND
        {%- endif -%}

        {%- if currentState != undefined
                and (currentState.config.schedulePeriodOption | default('') != desiredState.config.schedulePeriodOption
                or currentState.config.rootTask | default('') != desiredState.config.rootTask) -%}

            {%- if currentState.config.schedulePeriodOption | default('') == 'Predecessor' -%}
                {% set fullyQualifiedRootTaskName = ref_no_link(currentState.node.location.name, currentState.config.rootTask) %}

                {{ stage('Suspend Root Task', true, "sql", "create") }}
                ALTER TASK {{ fullyQualifiedRootTaskName }} SUSPEND

            {%- endif -%}
        {%- endif -%}

        {# Set Namespace Variables #}
        {% set nsVariables = namespace(taskWhenRun="") %}
        {% set nsVariables = namespace(poll="WHEN ") %}

        {# Task Info - Use ref() #}
        {% set taskName = desiredState.node.name + '_TASK' %}
        {% set fullyQualifiedTaskName = ref_no_link(desiredState.node.location.name, taskName) %}

        {# Task Type #}
        {%- if desiredState.config.schedulingMode == 'Warehouse Task' -%} 
            {# Can be updated during deployment via a parameter to account for different warehouse names in different deployments #}
            {% if 'targetTaskWarehouse'  in  desiredState.parameters %}
                {% if desiredState.parameters.targetTaskWarehouse == 'DEV ENVIRONMENT' %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.config.whName %}
                {% else %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.parameters.targetTaskWarehouse %}
                {% endif %}
            {% endif %}
        {%- else -%}
            {% set taskType = 'USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = ' + getServerSize(desiredState.config.serverlessSize) -%}
            {%- if desiredState.config.sizeBoundToggle -%}
                {% set minSrvSize = 'SERVERLESS_TASK_MIN_STATEMENT_SIZE = ' + getServerSize(desiredState.config.minServerlessSize) -%}
                {% set maxSrvSize = 'SERVERLESS_TASK_MAX_STATEMENT_SIZE = ' + getServerSize(desiredState.config.maxServerlessSize) -%}
            {%- endif -%} 
        {%- endif -%}

        {# Schedule Type #}
        {%- if desiredState.config.schedulePeriodOption == 'Minutes' -%} 
            {%- set execValue = desiredState.config.get('execTime', {})
                                .get('items', [])
                                | map(attribute='value')
                                | first
            %}
            {%- set execPeriod = desiredState.config.get('execTime', {})
                                .get('items', [])
                                | map(attribute='period')
                                | first
            %}
            {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + execValue | trim ~ ' ' ~ execPeriod | trim + "'" %}
        {% elif desiredState.config.schedulePeriodOption == 'CRON' %}
            {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + 'USING CRON ' + desiredState.config.scheduleCRON | trim + "'" %}
        {%- else -%}
            {%- set nsVariables.taskWhenRun = 'AFTER ' -%}
            {%- set predecessorTasks = (desiredState.config.predTask).split(",") -%}

            {%- for predTsk in predecessorTasks -%}
                {%- set nsVariables.taskWhenRun = nsVariables.taskWhenRun + targetTableDatabase + '.' + targetTableSchema + '."' + predTsk + '"'-%}
                {%- if not loop.last -%} 
                    {%- set nsVariables.taskWhenRun = nsVariables.taskWhenRun + ',' -%}
                {%- endif %}
            {% endfor %}    
        {%- endif -%}

        {# When Stream has data logic #}
        {# Source Stream Location and Name #}
        {% if desiredState.config.flagSrcStream == true %}
            {% for source in desiredState.sources %}
                {% for dep in source.dependencies %}
                    {% if (dep.node.materializationType == 'stream') %}
                        {% set streamStorageLocation = dep.node.location.name %}
                        {% set streamSourceDatabase = desiredState.storageLocations
                                                        | selectattr('name', 'equalto', streamStorageLocation)
                                                        | map(attribute='database')
                                                        | first %}
                        {% set streamSourceSchema = desiredState.storageLocations
                                                    | selectattr('name', 'equalto', streamStorageLocation)
                                                    | map(attribute='schema')
                                                    | first %}
                        {% set streamSourceName = dep.node.name %}

                        {%- if nsVariables.poll == 'WHEN ' -%}
                            {% set nsVariables.poll = nsVariables.poll + 'SYSTEM$STREAM_HAS_DATA(\'"' + streamSourceDatabase + '"."'  + streamSourceSchema + '"."' + streamSourceName + '"\')'  %}
                        {% else %}
                            {% set nsVariables.poll = nsVariables.poll + desiredState.config.multiStreamBehavior + ' SYSTEM$STREAM_HAS_DATA(\'"' + streamSourceDatabase + '"."'  + streamSourceSchema + '"."' + streamSourceName + '"\')'  %}
                        {%- endif -%}
                    {%- endif -%}
                {% endfor %}
            {% endfor %}
        {% endif -%}

        {%- set nsTaskVar = namespace(nodeComment='',
                                    userServiceAcct='',
                                    suspendTask='',
                                    autoTry='',
                                    overLapExec='',
                                    configJSON='',
                                    errorIntegration='',
                                    successIntegration='') %}
        {{ getadvancedTaskOptions(nsTaskVar) }}

        {# To mimic truncate behavior only incase of insert loadType#}
        {% if desiredState.config.loadType == 'Insert' %}
            {% if desiredState.config.truncateBefore %}
                {% set truncateBehavior = 'INSERT OVERWRITE' %}
            {% else %}
                {% set truncateBehavior = 'INSERT' %}
            {% endif -%}
        {% endif -%}

        {# Merge partition by and order by #}
        {%- if desiredState.config.loadType == 'Merge' -%}
            {% set tableColumnNames = desiredState.columns
                                        | map(attribute='name')
                                        | list %}
            {% set tableColumnNamesUpdate = tableColumnNames
                                            | reject('in', desiredState.config.partitionBy.get('items')
                                            | map(attribute='partColName.name'))
                                            | list %}

            {% for partCol in desiredState.config.partitionBy.get('items') %}
                {%- if loop.first -%}
                    {% set nsVariables.partition = '"' + partCol.partColName.name + '"' %}
                {% else %}
                    {% set nsVariables.partition = nsVariables.partition + ', "' + partCol.partColName.name + '"' %}
                {%- endif -%}
                {% set tableColumnNamesUpdate = tableColumnNames | reject('in', partCol.partColName.name) | list %}
            {% endfor %}

            {% for ordCol in desiredState.config.mergeOrderBy.get('items') %}
                {%- if loop.first -%}
                    {% set nsVariables.mergeOrderBy = '"' + ordCol.colName.name + '" ' + ordCol.sortOrd %}
                {% else %}
                    {% set nsVariables.mergeOrderBy = nsVariables.mergeOrderBy + ', "' + ordCol.colName.name + '" ' + ordCol.sortOrd %}
                {%- endif -%}
            {% endfor %}

            {% set nsVariables.rowNumber = 'ROW_NUMBER() OVER (PARTITION BY ' + nsVariables.partition + ' ORDER BY ' + nsVariables.mergeOrderBy + ')' %}

            {%- set nsVariables.tableKey = desiredState.config.partitionBy.get('items') %}
            {% set nsVariables.tableKey = nsVariables.tableKey | map(attribute='partColName.name') | list %}
        {%- endif -%}

        {{ stage('Create Task', true, "sql", "create") }}
        CREATE OR REPLACE TASK 
            {{ fullyQualifiedTaskName }} 
            {{ taskType }}
            {% if desiredState.config.schedulingMode == 'Serverless Task' and desiredState.config.sizeBoundToggle -%}
                {{ minSrvSize }}
                {{ maxSrvSize }}
            {% endif -%}
            {{ nsTaskVar.nodeComment }}
            {{ nsVariables.taskWhenRun }}
            {%- if desiredState.config.schedulePeriodOption != 'Predecessor' %}
                {{ nsTaskVar.overLapExec }}
                {%- if desiredState.config.autoSuspendToggle %}
                {{ nsTaskVar.suspendTask }}
                {%- endif %}
                {%- if desiredState.config.autoRetryToggle %}
                    {{ nsTaskVar.autoTry }}
                {%- endif %}
                {%- if desiredState.config.taskGraphToggle %}
                    {{ nsTaskVar.configJSON }}
                {%- endif %}
            {%- if desiredState.config.errNotifyToggle %}
                {{ nsTaskVar.errorIntegration }}
            {%- endif %}
            {%- if desiredState.config.successNotifyToggle %}
                {{ nsTaskVar.successIntegration }}
            {%- endif %}
            {%- endif %}
            {%- if desiredState.config.spfcUserToggle %}
                {{ nsTaskVar.userServiceAcct }}
            {%- endif %}
            {% if nsVariables.poll != 'WHEN ' %} {{ nsVariables.poll }} {% endif %}
        AS
        {% if desiredState.config.loadType == 'Insert' -%}
            {{ truncateBehavior }} INTO {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                (
                    {% for col in desiredState.columns %}
                        "{{ col.name }}"
                        {%- if not loop.last -%},{% endif %}
                    {% endfor %}
                )
                {% for source in desiredState.sources %}
                    /* Combine Sources if needed */
                        {% if loop.first %}
                    SELECT
                        {% if desiredState.config.selectDistinct %}
                    DISTINCT
                        {% endif %}
                        {% for col in desiredState.columns  %}
                    "{{ col.name }}" AS "{{ col.name }}"
                        {% if not loop.last %}, {% endif %}
                        {% endfor %}
                    FROM
                    (
                            {% endif %}
                        SELECT
                            {% if desiredState.config.selectDistinct %}
                        DISTINCT
                            {% endif %}
                            {% for col in source.columns %}
                        {{ get_source_transform(col) }} AS "{{ col.name }}"{% if not loop.last %}, {% endif %}
                            {% endfor %}
                        {{ source.join }}                  
                            {% if not loop.last %}
                        {{ desiredState.config.insertStrategy }}
                            {% endif %}
                            {% if loop.last %}
                    )
                            {% endif %}
                        {% endfor %}
                        {% if desiredState.config.groupByAll %}
                    GROUP BY ALL
                        {% endif %}
                    {{ sortorder_by_colv() }}
        {% else %}
            MERGE INTO {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }} tgt USING
            -- Select Statement Preparing Data for Merge
            (
                {% for source in desiredState.sources %}
                    /* Combine Sources if needed */
                            {% if loop.first %}
                        SELECT
                            {% if desiredState.config.selectDistinct %}
                        DISTINCT
                            {% endif %}
                            {% for col in desiredState.columns  %}
                        "{{ col.name }}" AS "{{ col.name }}"
                            {% if not loop.last %}, {% endif %}
                            {% endfor %}
                        FROM
                        (
                                {% endif %}
                            SELECT
                                {% if desiredState.config.selectDistinct %}
                            DISTINCT
                                {% endif %}
                                {% for col in source.columns %}
                            {{ get_source_transform(col) }} AS "{{ col.name }}"{% if not loop.last %}, {% endif %}
                                {% endfor %}
                            {{ source.join }}                  
                                {% if not loop.last %}
                            {{ desiredState.config.insertStrategy }}
                                {% endif %}
                                {% if loop.last %}
                        )
                            {% endif %}
                            {% endfor %}
                            {% if desiredState.config.groupByAll %}
                        GROUP BY ALL
                            {% endif %}
                        QUALIFY {{ nsVariables.rowNumber }} = 1
                        {{ sortorder_by_colv() }}
                    ) src
                    -- Join Condition
                ON
                    {% for col in nsVariables.tableKey -%}
                src."{{ col }}" = tgt."{{ col }}"
                        {% if not loop.last %} AND {% endif %}
                    {%- endfor -%}
                    -- What to do if data is matched based on table key
                WHEN MATCHED THEN UPDATE SET
                    {%- for col in tableColumnNamesUpdate %}
                        {% if col not in ["SYSTEM_CREATE_DATE"]%}
                tgt."{{ col }}" = src."{{ col }}"
                            {%- if not loop.last -%}, {%- endif %}
                        {% endif %}
                    {%- endfor %}
                -- What to do with new records based on table key
                WHEN NOT MATCHED THEN INSERT
                    (
                    {%- for col in desiredState.columns -%}
                "{{ col.name }}"
                            {%- if not loop.last -%}, {% endif %}
                    {% endfor %})
                VALUES (                                                        
                    {%- for col in desiredState.columns -%}
                src."{{ col.name }}"
                            {%- if not loop.last -%}, {% endif %}
                    {% endfor %}
            )
        {%- endif -%}

        {%- if desiredState.config.schedulePeriodOption != 'Predecessor' -%} 
            {{ stage('Resume Task', true, "sql", "create") }}
            ALTER TASK {{ fullyQualifiedTaskName }} RESUME;
        {%- endif -%}
    {%- endif -%}

{% elif currentState != undefined and desiredState == undefined %}

        {# Target Table Info #}
        {% set targetTableDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
        {% set targetTableSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
        {% set fullyQualifiedTargetTableName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

    {% if currentState.config.devMode | default(false) == false %}
        {% set fullyQualifiedRootTaskName = ref_no_link(currentState.node.location.name, currentState.config.rootTask) %}

        {# Task Info #}
        {% set taskName = currentState.node.name + '_TASK' %}
        {% set fullyQualifiedTaskName = ref_no_link(currentState.node.location.name, taskName) %}
        {%- if currentState.config.schedulePeriodOption == 'Predecessor' -%}
            {{ stage('Suspend Root Task') }}
            ALTER TASK IF EXISTS {{ fullyQualifiedRootTaskName }} SUSPEND
            {{ stage('Drop Current Task') }}
            DROP TASK IF EXISTS {{ fullyQualifiedTaskName }} 
        {%- else -%}
            {{ stage('Drop Current Task') }}
            DROP TASK IF EXISTS {{ fullyQualifiedTaskName }} 
        {%- endif -%}
    {%- endif -%}
{%- endif -%}

contents.macros:
{###########################################################################################
  **Macro: build_expr(expr)**

  **Description** Formats a transformation expression by removing any table prefix from a column reference and quoting the column name.
  This is useful when dynamically generating SQL where expressions like `COUNT(table.column)` must become `COUNT("column")` in the final query.

  **Input** expr (string) - A SQL transformation expression. It may contain a function with a table-qualified column reference such as `COUNT(orders.o_orderkey)

  **Output** - Returns a formatted SQL expression with the column name quoted and the table prefix removed.
    and/or triggers a stage-level warning UI notification for critical switches.
#############################################################################################}
{% macro build_expr(expr) -%}
    {%- if expr and '(' in expr -%}
        {%- set func = expr.split('(')[0] -%}
        {%- set inner = expr.split('(')[1].replace(')','') -%}
        {%- set col = inner.split('.')[-1] -%}

        {%- if col == '*' -%}
            {{ func ~ '(*)' }}
        {%- else -%}
            {{ func ~ '("' ~ col ~ '")' }}
        {%- endif -%}

    {%- else -%}
        {{ expr }}
    {%- endif -%}
{%- endmacro %}

{###########################################################################################
**Macro: build_alias(alias)

**Description** Extracts the final column name from a dot-separated alias.
If the alias is provided as `table.column`, the macro returns only column

**Input** alias (string) - A column alias that may include a prefix such as customer.cust_name
**Output** Returns the final column name without the prefix.
    and/or triggers a stage-level warning UI notification for critical switches.
#############################################################################################}
{% macro build_alias(alias) -%}
    {{- alias.split('.')[-1] if alias else '' -}}
{%- endmacro %}

{###########################################################################################
Description: Renders WITH SYNONYMS and COMMENT clauses if synonym or comment values exist.

Input: obj – Object or list of objects containing optional synonym and comment fields.

Output: WITH SYNONYMS ('value') if synonym exists
        COMMENT = 'value' if comment exists
    and/or triggers a stage-level warning UI notification for critical switches.
#############################################################################################}
{% macro renderSynonymAndComment(obj) %}

    {%- if obj.synonym is defined or obj.comment is defined -%}

        {%- if obj.synonym is defined and obj.synonym | trim != '' %}
            {%- set syn_list = obj.synonym.split(',') | map('trim') | reject('equalto','') | list -%}
            WITH SYNONYMS ('{{ syn_list | join("', '") }}')
        {%- endif %}

        {%- if obj.comment is defined and obj.comment | trim != '' %}
        COMMENT = '{{ obj.comment }}'
        {%- endif %}

    {%- else -%}

        {# grouped case (item.list) #}
        {%- set synonyms = obj
            | selectattr('synonym','defined')
            | map(attribute='synonym')
            | map('trim')
            | reject('equalto','')
            | unique
            | list
        -%}

        {%- if synonyms %}
        WITH SYNONYMS ({{ "'" ~ synonyms | join("', '") ~ "'" }})
        {%- endif %}

        {%- set comments = obj
            | selectattr('comment','defined')
            | map(attribute='comment')
            | map('trim')
            | reject('equalto','')
            | unique
            | list
        -%}

        {%- if comments %}
        COMMENT = '{{ comments | join(', ') }}'
        {%- endif %}

    {%- endif %}

{%- endmacro %}

{###########################################################################################
Description: Builds an SQL ORDER BY clause from the configured sort columns.

Input: config.orderby – enables ordering
config.orderbycolumn.items – list of columns with sortColName.name and sortOrder

Output: Returns a formatted ORDER BY clause or an empty string if no ordering is defined.
    and/or triggers a stage-level warning UI notification for critical switches.
#############################################################################################}
{%- macro sortOrderByColumn() -%}

    {%- set ns = namespace(sortCols="") -%}

    {%- if config.orderby -%}

        {%- for item in config.orderbycolumn.get('items') -%}

            {%- set colName  = item.sortColName.name -%}
            {%- set colOrder = item.sortOrder -%}

            {%- if loop.first -%}
                {%- set ns.sortCols = colName ~ ' ' ~ colOrder -%}
            {%- else -%}
                {%- set ns.sortCols = ns.sortCols ~ ', ' ~ colName ~ ' ' ~ colOrder -%}
            {%- endif -%}

        {%- endfor -%}

        {%- set ns.sortCols = 'ORDER BY ' ~ ns.sortCols -%}

    {%- endif -%}

    {{- ns.sortCols -}}

{%- endmacro -%}

{###########################################################################################
Description: Extracts the WHERE, GROUP BY, or ORDER BY clause from a SQL string.

Input: join – SQL text that may contain filtering or sorting clauses.

Output: Returns the SQL portion starting from WHERE, GROUP BY, or ORDER BY. Returns an empty string if none are found.
    and/or triggers a stage-level warning UI notification for critical switches.
#############################################################################################}
{%- macro extractClause(join) -%}

    {%- set sql = join | replace('\n',' ') -%}
    {%- set lowerSql = sql | lower -%}

    {%- set whereClause = lowerSql.find(' where ') -%}
    {%- set groupByClause = lowerSql.find(' group by ') -%}
    {%- set orderByClause = lowerSql.find(' order by ') -%}

    {%- set idx = [whereClause, groupByClause, orderByClause] | reject('equalto', -1) | list | min if [whereClause, groupByClause, orderByClause] | reject('equalto', -1) | list else -1 -%}

    {{ sql[idx:] | trim if idx != -1 else '' }}

{%- endmacro -%}

{###########################################################################################
Purpose: Determines the correct Snowflake DROP object syntax based on the materialization type.

Input: materialization (string): The Snowflake object type to be dropped
  (e.g., table, view, materialized view, dynamic table, external table).

Returns: string: The appropriate DROP object keyword with IF EXISTS
  (e.g., 'table IF EXISTS', 'view IF EXISTS', 'materialized view IF EXISTS').
#############################################################################################}
{% macro dropMaterialization(materialization) %}
    {%- if materialization | lower in ['table', 'transient table','temporary table', 'hybrid table'] -%}
        TABLE IF EXISTS
    {%- elif materialization | lower in ['view', 'secure view', 'run view', 'cortex search service'] -%}
        VIEW IF EXISTS
    {%- elif materialization | lower in ['dynamic table','transient dynamic table', 'dynamic iceberg table'] -%}
        DYNAMIC TABLE IF EXISTS
    {%- elif materialization | lower == 'semantic view' -%}
        SEMANTIC VIEW IF EXISTS
    {%- elif materialization | lower == 'materialized view' -%}
        MATERIALIZED VIEW IF EXISTS
    {%- elif materialization | lower == 'external table' -%}
        EXTERNAL TABLE IF EXISTS
    {%- elif materialization | lower == 'iceberg table' -%}
        ICEBERG TABLE IF EXISTS
    {%- elif materialization | lower == 'interactive table' -%}
        INTERACTIVE TABLE IF EXISTS
    {%- elif materialization | lower == 'stream' -%}
        STREAM IF EXISTS
    {%- else -%}
        TABLE IF EXISTS
    {%- endif %}
{% endmacro %}

{###########################################################################################
Purpose: Generates SQL-commented warnings or UI notifications when a user attempts to 
change the Node Type or Materialization Type of a node. It identifies 
critical node configurations (Tasks, Streams, Hybrid Views, Cortex, etc.) 
that could lead to data loss or broken dependencies if switched.

Input: None

Returns: A string containing a SQL comment warning (starting with '-- ⚠️') 
    and/or triggers a stage-level warning UI notification for critical switches.
#############################################################################################}
{% macro getNodeTypeSwitchWarning() %}
    {%- if currentState.node.nodeType.split(':::')[-1] in ['300', '301'] -%}
        {# Current Node Type: Deferred Merge Nodes #}
        -- ⚠️ Warning: This table may be linked to streams and hybrid views. Any required updates/drops must be handled manually.
    {%- elif currentState.node.nodeType.split(':::')[-1] in ['549', '550', '154', '155'] -%}
        {# Current Node Type: Root and Resume Tasks Nodes #}
        -- ⚠️ Warning: These node types are not ideal for switching, as they may act as root or resume tasks. Changing them may disrupt related tasks, cause inconsistencies, or result in data loss. Any required updates/drops must be handled manually.
    {%- elif currentState.node.nodeType.split(':::')[-1] in ['416', '448'] -%}
        {# Current Node Type: Data Quality related statis table/view #}
        -- ⚠️ Warning: This node is used for data quality checks and may not represent the final static schema. Deployment or execution could fail or interrupt email notifications and task failures.
    {%- elif currentState.node.materializationType | lower in ['task'] or currentState.node.nodeType.split(':::')[-1] in ['429', '567'] -%}
        {# Current Node Type: Tasks Related, Insert or Merge with Task, Document AI Nodes#}
        -- ⚠️ Warning: Tasks or streams are attached to this node. Changing its type may cause task failures, stream inconsistencies, or data loss. Any required updates/drops must be handled manually.
    {%- elif currentState.node.materializationType | lower in ['stream'] -%}
        {# Current Node Type: Stream Nodes #}
        -- ⚠️ Warning: This is a stream node. Changing its type may cause task failures, stream inconsistencies, or data loss. Any required updates/drops must be handled manually.
    {%- elif currentState.node.materializationType | lower in ['cortex search service'] -%}
        {# Current Node Type: Cortex Nodes #}
        -- ⚠️ Warning: Cortex search service is attached to this node. Changing its type may cause service failures, inconsistencies, or data loss. Any required updates/drops must be handled manually.
    {%- endif %}
{% endmacro %}

