{{ stage('Create Semantic Query View') }}
CREATE OR REPLACE {{ node.materializationType }} {{ ref_no_link(node.location.name, node.name) }}
(
    {% for col in columns %}
        "{{ col.name }}"
        {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
        {%- if not loop.last -%}, {% endif %}
    {% endfor %}
)
{%- if node.description | length > 0 %} COMMENT = '{{ node.description | escape }}'{% endif %}
AS
SELECT * FROM SEMANTIC_VIEW
(
    {{ ref_no_link(sources[0].dependencies[0].node.location.name, sources[0].dependencies[0].node.name) }}

    {% set factColumns = columns
        | selectattr('isaFactColumn', 'equalto', true)
        | map(attribute='name')
        | list
    %}
    {%- if factColumns %}
    FACTS
    {{ factColumns | join(', ') }}
    {%- endif %}

    {% set dimColumns = columns
        | selectattr('isaDimColumn', 'equalto', true)
        | map(attribute='name')
        | list
    %}

    {%- if dimColumns %}
    DIMENSIONS
    {{ dimColumns | join(', ') }}
    {%- endif %}

    {% set metricColumns = columns
        | selectattr('isaMetricColumn', 'equalto', true)
        | map(attribute='name')
        | list
    %}
    {%- if metricColumns %}
    METRICS
    {{ metricColumns | join(', ') }}
    {%- endif %}
)
{{ extractClause(sources[0].join) }}
{{ sortOrderByColumn() }}

{#
    Copyright (c) 2026 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.
#}
{# == Node Type Name  : Semantic View == #}
{# == Node Type Description : This node creates basic semantic view == #}

{% if desiredState and (currentState == undefined or (currentState != undefined and desiredState != currentState)) %}

    {%- if currentState != undefined and currentState.node.nodeType != desiredState.node.nodeType %}
        {%- set warningMsg = getNodeTypeSwitchWarning() | default('') %}

        {# Warning display - Node type changes can impact related tasks, streams, or services. #}
        {%- if warningMsg | trim | length > 0 -%}
            {{ stage('Warning! Node Type Switching Detected', false) }}
            {{ warningMsg }}
            select 1=0
        {%- endif -%}

        {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
        {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
        DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

    {%- endif -%}

    {% set nsSVvariables = namespace(primKey=[], foreignKey=[], factDetails=[], dimDetails=[], metricDetails=[]) %}
    {% set objectFullPath = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}
    {% set desiredDatabase = desiredState.storageLocations
                                | selectattr('name', 'equalto', desiredState.node.location.name)
                                | map(attribute='database')
                                | first %}
    {% set desiredSchema = desiredState.storageLocations 
                                | selectattr('name', 'equalto', desiredState.node.location.name)
                                | map(attribute='schema')
                                | first %}

    {% for col in desiredState.config.primaryKeyConfig.get('items') %}

        {% set pk = col.primaryKey %}
        {%- set srcTableLocName = desiredState.sources[0].columns 
                                | selectattr('id','eq', pk.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | map(attribute='node.location.name')
                                | first -%}

        {%- set srcTableName = desiredState.sources[0].columns 
                                | selectattr('id','eq', pk.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | map(attribute='node.name')
                                | first -%}

        {% set _ = nsSVvariables.primKey.append({
            "id": pk.id,
            "name": pk.name,
            "alias": col.primAlias | trim,
            "synonym": col.primSynonym | trim,
            "comment": col.primComment | trim,
            "srcTablePath" : ref_no_link(srcTableLocName, srcTableName)
        }) %}

    {% endfor %}

    {% set ns = namespace(aliasMap={}) %}
    {% for item in nsSVvariables.primKey | groupby('srcTablePath') %}

        {# extract valid aliases #}
        {% set aliases = item.list
            | selectattr('alias','defined')
            | map(attribute='alias')
            | map('trim')
            | reject('equalto','')
            | list
        %}

        {# fallback to table name if alias missing #}
        {% set tbl_alias = aliases[0] if aliases else item.grouper.split('.')[-1] | replace('"','') %}

        {# store in alias map #}
        {% set _ = ns.aliasMap.update({ item.grouper: tbl_alias }) %}

    {% endfor %}

    {% for col in desiredState.config.foreignKeyConfig.get('items') if desiredState.config.foreignToggle | default(false) %}

        {% set fk = col.foreignKey %}
        {%- set srcTableName = desiredState.sources[0].columns 
                                | selectattr('id','eq', fk.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | map(attribute='node.name')
                                | first -%}

        {%- set srcTableLocName = desiredState.sources[0].columns 
                                | selectattr('id','eq', fk.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | map(attribute='node.location.name')
                                | first -%}

        {% set _ = nsSVvariables.foreignKey.append({
            "id": fk.id,
            "name": fk.name,
            "alias": col.refAlias | trim,
            "srcTablePath" : ref_no_link(srcTableLocName, srcTableName),
            "refTable": col.refTable | trim
        }) %}
    {% endfor %}

    {% for item in desiredState.config.factDetConfig.get('items') if desiredState.config.factToggle | default(false) %}

        {% set col = item.factCol %}
        {%- set srcTableName = desiredState.sources[0].columns 
                                | selectattr('id', 'eq', col.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | select('defined')
                                | selectattr('node', 'defined')
                                | map(attribute='node.name') 
                                | first 
                                | default('', true) -%}

        {%- set srcTableLocName = desiredState.sources[0].columns 
                                | selectattr('id','eq', col.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | select('defined')
                                | selectattr('node', 'defined')
                                | map(attribute='node.location.name') 
                                | first 
                                | default('', true) -%}

        {% set _ = nsSVvariables.factDetails.append({
            "id":   col.id   if col else None,
            "name": col.name if col else None,
            "srcTablePath": ref_no_link(srcTableLocName, srcTableName) if srcTableLocName and srcTableName else "",
            "transform": item.factTranform | trim or "",
            "alias": item.factAlias | trim or "",
            "layer": item.factLayer,
            "synonym": item.factSynonym | trim,
            "comment": item.factComment | trim
        }) %}
    {% endfor %}

    {% for item in desiredState.config.DimConfig.get('items') if desiredState.config.dimToggle | default(false) %}

        {% set col = item.dimCol %}
        {%- set srcTableName = desiredState.sources[0].columns 
                                | selectattr('id', 'eq', col.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | select('defined')
                                | selectattr('node', 'defined')
                                | map(attribute='node.name') 
                                | first 
                                | default('', true) -%}

        {%- set srcTableLocName = desiredState.sources[0].columns 
                                | selectattr('id','eq', col.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | select('defined')
                                | selectattr('node', 'defined')
                                | map(attribute='node.location.name') 
                                | first 
                                | default('', true) -%}

        {% set _ = nsSVvariables.dimDetails.append({
            "id": col.id if col else None,
            "name": col.name if col else None,
            "srcTablePath": ref_no_link(srcTableLocName, srcTableName) if srcTableLocName and srcTableName else "",
            "transform": item.dimTransform | trim or "",
            "alias": item.dimAlias | trim or "",
            "layer": item.dimLayer,
            "synonym": item.dimSynonym | trim,
            "comment": item.dimComment | trim
        }) %}
    {% endfor %}

    {% for item in desiredState.config.metricConfig.get('items') if desiredState.config.metricToggle | default(false) %}

        {% set col = item.metricCol %}
        {%- set srcTableName = desiredState.sources[0].columns 
                                | selectattr('id', 'eq', col.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | select('defined')
                                | selectattr('node', 'defined')
                                | map(attribute='node.name') 
                                | first 
                                | default('', true) -%}

        {%- set srcTableLocName = desiredState.sources[0].columns 
                                | selectattr('id','eq', col.id)
                                | map(attribute='sourceColumns')
                                | first 
                                | select('defined')
                                | selectattr('node', 'defined')
                                | map(attribute='node.location.name') 
                                | first 
                                | default('', true) -%}

        {% set col = item.metricCol %}
        {% set _ = nsSVvariables.metricDetails.append({
            "id": col.id if col else None,
            "name": col.name if col else None,
            "src": item.srcTable if item.srcTable else "",
            "metric": item.metricTransform,
            "derived": item.metricTransformExprn | trim if item.metricTransformExprn else "",
            "srcTablePath": ref_no_link(srcTableLocName, srcTableName) if srcTableLocName and srcTableName else "",
            "alias": item.metricAlias | trim if item.metricAlias else "",
            "layer": item.metricLayer,
            "synonym": item.metricSynonym | trim,
            "comment": item.metricComment | trim,
        }) %}
    {% endfor %}

    {% set baseCombined = nsSVvariables.primKey
                        +  nsSVvariables.foreignKey %}
    {% set layerCombined = nsSVvariables.factDetails
                        + nsSVvariables.dimDetails
                        + nsSVvariables.metricDetails %}

    {% set allBaseIds = baseCombined
        | map(attribute='id')
        | list
        | unique
        | list
    %}
    {% set allLayerIds = layerCombined
        | map(attribute='id')
        | list
        | unique
        | list
    %}

    {% set all_ids = allBaseIds + allLayerIds %}
    {% set allSrcTables = nsSVvariables.primKey | map(attribute='srcTablePath') | list | unique | list %}

    {# -------------------------------------------------------------- #}

    {% if desiredState.config.deriveCol %}

        {{ stage('Drop Semantic View') }}
        EXECUTE IMMEDIATE $$
        DECLARE
        -- Default to NULL or 'NONE' so the IF checks don't crash
        target_type STRING DEFAULT 'NONE';
        BEGIN
        -- 1. Use INTO to capture the result
        SELECT count(*) 
            INTO :target_type
            FROM {{desiredDatabase}}.information_schema.semantic_views
            WHERE name = '{{ desiredState.node.name }}'
            AND schema = '{{ desiredSchema }}'
            LIMIT 1;

        -- 2. Drop the existing object based on its type
        IF (target_type = 1) THEN
            DROP SEMANTIC VIEW {{ objectFullPath }};
            RETURN 'Success: Semantic View found and dropped.';
        END IF;
        END;
        $$;

        {{ stage('Create Schema Table', true, "sql", "create") }}
        CREATE OR REPLACE TABLE {{ objectFullPath }}
        AS
        SELECT
            layer2Columns.*
        {%- for group in [nsSVvariables.factDetails, nsSVvariables.dimDetails, nsSVvariables.metricDetails] %}
        {%- for col in group if col.id is none and col.layer == '3' %}
        {%- if col.transform %}
        {%- set final_expr = build_expr(col.transform) -%}
        {%- else %}
        {%- set final_expr = build_expr(col.metric + '(' + col.derived + ')') -%}
        {%- endif -%}
        {%- set alias = build_alias(col.alias) -%}
        , {{ final_expr }} AS "{{ alias }}"
        {%- endfor %}
        {%- endfor %}
        FROM
        (
            SELECT
                layer1Columns.*
        {%- for group in [nsSVvariables.factDetails, nsSVvariables.dimDetails, nsSVvariables.metricDetails] %}
        {%- for col in group if col.id is none and col.layer == '2' %}
        {%- if col.transform %}
        {%- set final_expr = build_expr(col.transform) -%}
        {%- else %}
        {%- set final_expr = build_expr(col.metric + '(' + col.derived + ')') -%}
        {%- endif -%}
        {%- set alias = build_alias(col.alias) -%}
        , {{ final_expr }} AS "{{ alias }}"
        {%- endfor %}
        {%- endfor %}
            FROM
            (
                SELECT
        {%- for col in desiredState.sources[0].columns if col.id in all_ids %}
                    {{ col.name }} AS "{{ col.name }}"
        {%- if not loop.last %},{% endif %}
        {%- endfor %}

        {%- for group in [nsSVvariables.factDetails, nsSVvariables.dimDetails, nsSVvariables.metricDetails] %}
        {%- for col in group if col.layer == '1' %}
        {%- set alias = build_alias(col.alias) -%}

        {%- if col.id and col.alias|trim != '' %}
        , {{ col.name }} AS "{{ alias }}"

        {%- elif col.id is none %}
        {%- set expr = build_expr(col.transform) | replace('"', '') -%}
        , {{ expr }} AS "{{ alias }}"

        {%- endif %}
        {%- endfor %}
        {%- endfor %}

                FROM
        {%- for tablePath in allSrcTables %}
                    {{ tablePath }} {{ tablePath.split('.')[-1].replace('"','') }}
        {%- if not loop.last %}, {% endif %}
        {%- endfor %}
                GROUP BY ALL
            ) layer1Columns
            GROUP BY ALL
        ) layer2Columns
        WHERE 1=0
        GROUP BY ALL
    {% else %}

        {{ stage('Drop Schema Table') }}
        EXECUTE IMMEDIATE $$
        DECLARE
        -- Default to NULL or 'NONE' so the IF checks don't crash
        target_type STRING DEFAULT 'NONE';
        BEGIN
        -- 1. Use INTO to capture the result
        SELECT table_type 
            INTO :target_type
            FROM {{desiredDatabase}}.information_schema.tables
            WHERE table_name = '{{ desiredState.node.name }}'
            AND table_schema = '{{ desiredSchema }}'
            LIMIT 1;

        -- 2. Drop the existing object based on its type
        IF (target_type = 'BASE TABLE') THEN
            DROP TABLE {{ objectFullPath }};
            RETURN 'Success: Table found and dropped.';
        END IF;
        END;
        $$;

        {{ stage('Create Semantic View', true, "sql", "create") }}
        CREATE OR REPLACE SEMANTIC VIEW {{ objectFullPath }}

        TABLES
        (
            {%- for item in nsSVvariables.primKey | groupby('srcTablePath') -%}

            {{ ns.aliasMap[item.grouper] }} AS {{ item.grouper | replace('"','') }}

            {%- if desiredState.config.tableOnlyToggle == false %}
            PRIMARY KEY (
                {{ item.list | map(attribute='name') | join(', ') }}
            )
            {%- endif %}
            {{ renderSynonymAndComment(item.list) }}
            {%- if not loop.last %},{%- endif %}
            {%- endfor %}
        )

        {%- if desiredState.config.foreignToggle | default(false) -%}
        RELATIONSHIPS
        (
            {%- for item in nsSVvariables.foreignKey -%}
                {%- if item.alias != '' %} {{ item.alias }} AS {% endif -%}
                 {{ ns.aliasMap[item.srcTablePath] }} ({{ item.name }}) REFERENCES {{ item.refTable }}
                {%- if not loop.last %},{% endif %}
            {%- endfor %}
        )
        {%- endif %}

        {%- if desiredState.config.factToggle | default(false) %}
        FACTS (
            {%- for col in nsSVvariables.factDetails -%}
                {%- if col.transform %}
                    {{ col.alias if col.alias 
                                else col.name }}
                    AS {{ col.transform }}
                {%- else %}
                    {% if col.alias != '' %}
                        {%- if col.alias.split('.') | length == 2 %}
                            {{ col.alias }}
                        {%- else %}
                            {{ ns.aliasMap[col.srcTablePath] + '.' + col.alias }}
                        {%- endif %}
                    {%- else %}
                        {{ ns.aliasMap[col.srcTablePath] + '.' + col.name }}
                    {%- endif %}
                    AS {{ ns.aliasMap[col.srcTablePath] }}.{{ col.name }}
                {%- endif %}
                {{ renderSynonymAndComment(col) }}
                {%- if not loop.last %},{% endif %}
            {%- endfor %}
        )
        {%- endif %}

        {%- if desiredState.config.dimToggle | default(false) %}
        DIMENSIONS (
            {%- for col in nsSVvariables.dimDetails -%}
                {%- if col.transform != '' %}
                    {{ col.alias if col.alias 
                                else col.name }}
                    AS {{ col.transform }}
                {%- else %}
                    {% if col.alias != '' %}
                        {%- if col.alias.split('.') | length == 2 %}
                            {{ col.alias }}
                        {%- else %}
                            {{ ns.aliasMap[col.srcTablePath] + '.' + col.alias }}
                        {%- endif %}
                    {%- else %}
                        {{ ns.aliasMap[col.srcTablePath] + '.' + col.name }}
                    {%- endif %}
                    AS {{ ns.aliasMap[col.srcTablePath] }}.{{ col.name }}
                {%- endif %}
                {{ renderSynonymAndComment(col) }}
                {%- if not loop.last %},{% endif %}
            {%- endfor %}
        )
        {%- endif %}

        {%- if desiredState.config.metricToggle | default(false) %}
        METRICS
        (
            {%- for item in nsSVvariables.metricDetails -%}
                {%- if item.derived and item.derived != "" %}
                    {{ item.alias }} AS {{ item.metric }}({{ item.derived }})
                {%- elif item.metric and item.name %}
                    {%- if item.alias.split('.') | length == 2 %}
                    {{ item.alias }}
                    {%- else %}
                    {{ ns.aliasMap[item.srcTablePath] + '.' + item.alias }}
                    {%- endif %} AS {{ item.metric }}({{ ns.aliasMap[item.srcTablePath] }}.{{ item.name }})
                {%- endif %}
                {{ renderSynonymAndComment(item) }}
                {%- if not loop.last %},{% endif %}
            {%- endfor %}
        )
        {%- if desiredState.node.description | length > 0 %} COMMENT = '{{ desiredState.node.description | escape }}'{% endif %}
        {%- endif %}
    {%- endif %}

{%- elif desiredState == undefined and currentState != undefined %}
    {{ stage('Drop ' + '{{currentState.node.materializationType}}') }}
    {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
    DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}
{%- endif %}

contents.macros:
{# ----------------------------------------------------------------------
  Macro: buildcoldict
  Purpose: Builds a dictionary (ns.column_dict) of columns for all sources
---------------------------------------------------------------------- #}
{% macro buildcoldict(ns) %}

    {% if sources is defined %}
        {% for source_idx in range(sources | length) %}
            {% set source = sources[source_idx] %}

            {# Initialize the source entry if missing #}
            {% if source_idx not in ns.column_dict %}
                {% set _ = ns.column_dict.update({source_idx: {}}) %}
            {% endif %}

            {# Add all columns in this source to the dictionary #}
            {% for column in source.columns %}
                {% set _ = ns.column_dict[source_idx].update({column.id: column}) %}
            {% endfor %}
        {% endfor %}

    {% endif %}
{% endmacro %}

{#--------------------------------------------------------
    The block of code below initializes variables for node types
    that use the advanced deployment strategy
----------------------------------------------------------#}
{% if desiredState %}
    {% set columns = desiredState.columns %}
    {% set storageLocations = desiredState.storageLocations %}
    {% set config = desiredState.config %}
    {% set sources = desiredState.sources %}
    {% set node = desiredState.node %}
    {% set parameters = desiredState.parameters %}

    {% set ns = namespace(column_dict = {}) %}
    {# Populate column dictionary #}
    {{ buildcoldict(ns) }}

{% endif %}

{#-----------------------------------------------------------------
 	Macro: icebergcoldatatype
  	Purpose: Converts Snowflake column data types into their equivalent Iceberg-compatible types.
           - VARCHAR → STRING
           - TIMESTAMP → TIMESTAMP
           - TIME → TIME
           - Otherwise, passes through the original type.
-------------------------------------------------------------------#}
{% macro icebergcoldatatype( coldatatype ) %}

	{% set nsVariables = namespace(ibcoldatatype = "") %}

	{% if 'VARCHAR' in coldatatype %}
		{% set nsVariables.ibcoldatatype = 'STRING' %}
	{% elif 'TIMESTAMP' in coldatatype %}
		{% set nsVariables.ibcoldatatype = 'TIMESTAMP' %}
	{% elif 'TIME' in coldatatype %}
		{% set nsVariables.ibcoldatatype = 'TIME' %}
	{% else %}
		{% set nsVariables.ibcoldatatype = coldatatype %}
	{% endif %}

	{{ nsVariables.ibcoldatatype }}

{% endmacro %}

{# ----------------------------------------------------------------------
  Macro: dimensionHistoryPk
  Builds a composite key for dimension history:
   - Joins partition columns from partition_by('DIM')
   - Adds order_by_col() for uniqueness
   - Uses epoch millis or MD5(order_by_col) depending on record versioning
----------------------------------------------------------------------  #}
{% macro dimensionHistoryPk() %}

    {%- set nsVariables = namespace(dimensionHistoryColumns = "") -%}
    {%- set partitionBy = partition_by('DIM').split("~") -%}
    {%- set orderBy = order_by_col() -%}

    {%- for col in partitionBy -%}
        {%- if loop.first -%}
            {%- set nsVariables.dimensionHistoryColumns = col -%}
        {%- else -%}
            {%- set nsVariables.dimensionHistoryColumns = nsVariables.dimensionHistoryColumns + ' || ' + '\'-\'' + ' ||' + col -%}
        {%- endif -%}
    {%- endfor -%}

    {% if config.recordVersioning not in ('Integer Column') %}
        {%- set nsVariables.dimensionHistoryColumns = nsVariables.dimensionHistoryColumns + ' || ' + '\'-\'' + ' || date_part(epoch_milliseconds, ' + orderBy + ')' -%}
    {% else %}
        {%- set nsVariables.dimensionHistoryColumns =  nsVariables.dimensionHistoryColumns ~ " || '-' || " ~ orderBy -%}
        {%- set nsVariables.dimensionHistoryColumns = "MD5(" ~ nsVariables.dimensionHistoryColumns ~")" -%}
    {% endif %}

    {{- nsVariables.dimensionHistoryColumns -}}

{% endmacro %}

{# ---------------------------------------------------------------------- 
  Macro: partition_by
  Purpose: Builds a partition key string for a node.
            - Uses '~' delimiter for DIM nodes, ',' otherwise.
            - Concatenates partitionBy config columns with proper transforms.
  Output: Returns the partition expression as a string.
----------------------------------------------------------------------  #}
{% macro partition_by(nodetype) %}

    {# Create namespaces #}
    {% set nsVars = namespace(partition = "", delim = "") %}

    {# Choose delimiter based on node type #}
    {% if nodetype == 'DIM' %}
        {% set nsVars.delim = '~' %}
    {% else %}
        {% set nsVars.delim = ',' %}
    {% endif %}

    {# Build partition expression #}
    {% if config is defined and config.partitionBy is defined %}
        {% for item in config.partitionBy.get('items', []) %}

        {% set part_col = ns.column_dict[0][item.partColName.id] %}

        {%- if loop.first -%}
                {%- set nsVars.partition = get_source_transform(part_col) -%}
            {%- else -%}
                {%- set nsVars.partition = nsVars.partition + nsVars.delim + get_source_transform(part_col) -%}
            {%- endif -%}
        {% endfor %}
    {% endif %}

  {{ nsVars.partition }}

{% endmacro %}

{# ----------------------------------------------------------------------
  Macro: order_by_col
  Purpose: Returns the column expression used for ordering in record versioning.
   - If "Datetime Column": uses the configured datetime column.
   - If "Integer Column": uses the configured sequence column.
   - Otherwise: combines separate date and time columns into a timestamp.
  Output: Order-by column expression as a string.
  ----------------------------------------------------------------------#}
{% macro order_by_col(return) %}

    {% set nsVariables = namespace(orderBy = "") -%}

    {% if config.recordVersioning in ('Datetime Column') -%}

        {% set datetimeColSort = config.orderBy.get('items', []) -%}		
        {% set dateTimeCol = ns.column_dict[0][datetimeColSort[0].colName.id] -%}        
        {% set nsVariables.orderBy = get_source_transform(dateTimeCol) -%}

	{% elif config.recordVersioning in ('Integer Column')%}

        {% set datetimeNumericColSort = config.orderseq.get('items',[]) -%}
	    {% set dateTimeCol = ns.column_dict[0][datetimeNumericColSort[0].colNameseq.id] -%}        
        {% set nsVariables.orderBy = get_source_transform(dateTimeCol) -%}

    {% else -%}

        {% set dateTimeColSort = config.orderByDateTime.get('items',[]) -%}
        {% set dateCol = ns.column_dict[0][dateTimeColSort[0].colNameDate.id] -%}
        {% set timeCol = ns.column_dict[0][dateTimeColSort[0].colNameTimestamp.id] -%}
        {% set nsVariables.orderBy = 'to_timestamp(' + get_source_transform(dateCol) +  '|| ' + '\'T\'' + ' ||' + get_source_transform(timeCol) +  ')' -%}

    {% endif -%}

    {{ nsVariables.orderBy }}

{% endmacro %}

{# ----------------------------------------------------------------------
  Macro: order_by_col_int
  Purpose:
    - Reads the configured "recordorderBy" column from the node settings.
    - Finds the matching column metadata by column ID.
 Output: Transformed column expression to be used in ORDER BY.
------------------------------------------------------------------------#}
{% macro order_by_col_int(return) %}

    {% set nsVariables = namespace(orderBy = "") -%}

      {% set datetimeNumericColSort = config.recordorderBy.get('items',[]) %}
	  {% set dateTimeCol = ns.column_dict[0][datetimeNumericColSort[0].ocolName.id] -%}    
      {% set nsVariables.orderBy = get_source_transform(dateTimeCol) -%} 

    {{ nsVariables.orderBy }}

{% endmacro %}

{###########################################################################################
Purpose: Determines the correct Snowflake DROP object syntax based on the materialization type.

Input: materialization (string): The Snowflake object type to be dropped
  (e.g., table, view, materialized view, dynamic table, external table).

Returns: string: The appropriate DROP object keyword with IF EXISTS
  (e.g., 'table IF EXISTS', 'view IF EXISTS', 'materialized view IF EXISTS').
#############################################################################################}
{% macro dropMaterialization(materialization) %}
    {%- if materialization | lower in ['table', 'transient table','temporary table', 'hybrid table'] -%}
        TABLE IF EXISTS
    {%- elif materialization | lower in ['view', 'secure view', 'run view', 'cortex search service'] -%}
        VIEW IF EXISTS
    {%- elif materialization | lower in ['dynamic table','transient dynamic table', 'dynamic iceberg table'] -%}
        DYNAMIC TABLE IF EXISTS
    {%- elif materialization | lower == 'materialized view' -%}
        MATERIALIZED VIEW IF EXISTS
    {%- elif materialization | lower == 'external table' -%}
        EXTERNAL TABLE IF EXISTS
    {%- elif materialization | lower == 'iceberg table' -%}
        ICEBERG TABLE IF EXISTS
    {%- elif materialization | lower == 'interactive table' -%}
        INTERACTIVE TABLE IF EXISTS
    {%- elif materialization | lower == 'stream' -%}
        STREAM IF EXISTS
    {%- else -%}
        TABLE IF EXISTS
    {%- endif %}
{% endmacro %}

{###########################################################################################
Purpose: Generates SQL-commented warnings or UI notifications when a user attempts to 
change the Node Type or Materialization Type of a node. It identifies 
critical node configurations (Tasks, Streams, Hybrid Views, Cortex, etc.) 
that could lead to data loss or broken dependencies if switched.

Input: None

Returns: A string containing a SQL comment warning (starting with '-- ⚠️') 
    and/or triggers a stage-level warning UI notification for critical switches.
#############################################################################################}
{% macro getNodeTypeSwitchWarning() %}
    {%- if currentState.node.nodeType.split(':::')[-1] in ['300', '301'] -%}
        {# Current Node Type: Deferred Merge Nodes #}
        -- ⚠️ Warning: This table may be linked to streams and hybrid views. Any required updates/drops must be handled manually.
    {%- elif currentState.node.nodeType.split(':::')[-1] in ['549', '550', '154', '155'] -%}
        {# Current Node Type: Root and Resume Tasks Nodes #}
        -- ⚠️ Warning: These node types are not ideal for switching, as they may act as root or resume tasks. Changing them may disrupt related tasks, cause inconsistencies, or result in data loss. Any required updates/drops must be handled manually.
    {%- elif currentState.node.nodeType.split(':::')[-1] in ['416', '448'] -%}
        {# Current Node Type: Data Quality related statis table/view #}
        -- ⚠️ Warning: This node is used for data quality checks and may not represent the final static schema. Deployment or execution could fail or interrupt email notifications and task failures.
    {%- elif currentState.node.materializationType | lower in ['task'] or currentState.node.nodeType.split(':::')[-1] in ['429', '567'] -%}
        {# Current Node Type: Tasks Related, Insert or Merge with Task, Document AI Nodes#}
        -- ⚠️ Warning: Tasks or streams are attached to this node. Changing its type may cause task failures, stream inconsistencies, or data loss. Any required updates/drops must be handled manually.
    {%- elif currentState.node.materializationType | lower in ['stream'] -%}
        {# Current Node Type: Stream Nodes #}
        -- ⚠️ Warning: This is a stream node. Changing its type may cause task failures, stream inconsistencies, or data loss. Any required updates/drops must be handled manually.
    {%- elif currentState.node.materializationType | lower in ['cortex search service'] -%}
        {# Current Node Type: Cortex Nodes #}
        -- ⚠️ Warning: Cortex search service is attached to this node. Changing its type may cause service failures, inconsistencies, or data loss. Any required updates/drops must be handled manually.
    {%- endif %}
{% endmacro %}

{####################################################################################################################################
Input: namespace – An object containing optional advanced configuration properties related to Snowflake task creation.
Description: This macro centralizes the logic for handling advanced Snowflake task configuration.
Output: A dynamically constructed SQL fragment containing all valid advanced task creation attributes derived from the provided namespace.
######################################################################################################################################}
{% macro getadvancedTaskOptions(ns) %}
    {%- set ns.nodeComment = "COMMENT = '" ~ node.description | trim ~ "'" if node.description | default('') | trim else "" %}

    {%- if config.spfcUserToggle -%}
        {%- if parameters.targetTaskExecuteAsUser | default('') == 'DEV ENVIRONMENT' -%}
            {%- set ns.userServiceAcct  = 'EXECUTE AS USER ' + config.userName | trim %}
        {%- else -%}
            {%- set ns.userServiceAcct = 'EXECUTE AS USER ' + parameters.targetTaskExecuteAsUser | default('') %}
        {%- endif -%}
    {%- endif -%}

    {%- if config.schedulePeriodOption not in ['Predecessor'] %}

        {%- if config.autoSuspendToggle %}
            {%- set ns.suspendTask = 'SUSPEND_TASK_AFTER_NUM_FAILURES = ' + config.numFailures | trim %}
        {%- endif -%}

        {%- if config.autoRetryToggle -%}
            {%- set ns.autoTry = 'TASK_AUTO_RETRY_ATTEMPTS = ' + config.retryAttmpt | trim %}
        {%- endif -%}

        {%- if config.overlapExecToggle %}
            {%- set ns.overLapExec = 'OVERLAP_POLICY  =  ALLOW_CHILD_OVERLAP' | string %}
        {% else %}
            {%- set ns.overLapExec = 'OVERLAP_POLICY  =  NO_OVERLAP' | string %}
        {%- endif -%}

        {%- if config.taskGraphToggle -%}
            {%- set ns.configJSON = 'CONFIG = $$' + config.configJSON | trim + '$$' %}
        {%- endif -%}

        {%- if config.errNotifyToggle -%}
            {%- if parameters.targetTaskErrorIntegration | default('') == 'DEV ENVIRONMENT' -%}
                {%- set ns.errorIntegration = 'ERROR_INTEGRATION = ' + config.errIntName | trim %}
            {%- else -%}
                {%- set ns.errorIntegration = 'ERROR_INTEGRATION = ' + parameters.targetTaskErrorIntegration | default('') %}
            {%- endif -%}
        {%- endif -%}

        {%- if config.successNotifyToggle -%}
            {% if parameters.targetTaskSuccessIntegration | default('') == 'DEV ENVIRONMENT' -%}
                {%- set ns.successIntegration = 'SUCCESS_INTEGRATION = ' + config.succIntName | trim %}
            {%- else -%}
                {%- set ns.successIntegration = 'SUCCESS_INTEGRATION = ' + parameters.targetTaskSuccessIntegration | default('') %}
            {%- endif -%}
        {%- endif -%}

    {%- endif -%}
{% endmacro %}

{####################################################################################################################################
Input: serverlessSize (string)

Output: Returns the server size only (e.g., XSMALL).

Description:
    Handles both old and new formats safely.
    If the value contains a '.', it returns the part after the dot.
    If there is no '.', it returns the value as-is.
    Returns nothing if input is missing.
######################################################################################################################################}
{%- macro getServerSize(serverlessSize) %}

    {%- if serverlessSize %}
        {%- set parts = serverlessSize.split('.') %}
        {{ parts[-1] }}
    {%- endif %}

{%- endmacro %}

