create.templateString:
{#
    Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : External Iceberg table == #}
{# == Node Type Description    :  == #}

{# Parameter Check for Deployment #}
{%if desiredState and currentState != desiredState and desiredState.config.schedulingMode == 'Warehouse Task' %}
     {% if desiredState.parameters == {} or 'targetTaskWarehouse' not in  desiredState.parameters or desiredState.parameters.targetTaskWarehouse == ''%}

         {{stage('WARNING')}}

          /*Add parameter targetTaskWarehouse in workspace settings and deployment environment for successful execution of node.
          The default value for the parameter is 'DEV ENVIRONMENT'.
          For more information, refer to the documentation.*/
	{%endif%}
{%endif%}

{# Create Iceberg table first #}

{% if (desiredState and currentState == undefined) or (currentState != desiredState and currentState != undefined and desiredState != undefined)%}


          {%set extvol = '' %}
          {%set catalogval = '' %}
          {%set catalogtablename ='' %}
          {%set catalogdbname ='' %}
          {%set metafilepath ='' %}
          {%set baseloc ='' %}

        {#External volume#}
           {%if desiredState.config.extvol != '' %}
            {%set extvol =  desiredState.config.extvolume %}
          {%endif%}

        {#Catalogintegration#}

          {%if desiredState.config.catint != '' %}
            {%set catalogval =   desiredState.config.catint %}
          {%else%}
            {%set catalogval =   'SNOWFLAKE' %}
          {%endif%}

        {#Catalogtablename#}

          {%if desiredState.config.cattable != '' and desiredState.config.tcatalog == 'AWS Glue' %}
            {%set catalogtablename = desiredState.config.cattable %}
          {%endif%}

        {#Catalogdbname#}
          {%if desiredState.config.catdb != '' and desiredState.config.tcatalog == 'AWS Glue' %}
            {%set catalogdbname = desiredState.config.catdb %}
          {%endif%}

        {#Metadatafilepath#}
          {%if desiredState.config.metafilepath != '' and desiredState.config.tcatalog == 'Object storage' %}
            {%set metafilepath =  desiredState.config.metafilepath %}
          {%endif%}



         {{ stage('Create Iceberg Table') }}

         CREATE OR REPLACE ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}


        {%if extvol != '' %} EXTERNAL_VOLUME = '{{extvol}}' {%endif%}
        {%if catalogval != '' %} CATALOG = '{{catalogval}}' {%endif%}
        {%if catalogtablename != ''%}CATALOG_TABLE_NAME = '{{catalogtablename}}' {%endif%}
        {%if catalogdbname != ''%}CATALOG_NAMESPACE = '{{catalogdbname}}' {%endif%}
        {%if metafilepath != ''%} METADATA_FILE_PATH= '{{metafilepath}}'{%endif%}

	    {%- if desiredState.node.description | length > 0 %} COMMENT = '{{ desiredState.node.description | escape }}'

    {% endif %}		    

{%elif  currentState != undefined and desiredState == undefined%}

    {# Table or View Name #}
    {% set targetObjectDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetObjectSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetObjectName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

        {{ stage('Drop iceberg table') }}
         DROP ICEBERG TABLE IF EXISTS {{ fullyQualifiedTargetObjectName }}

{%endif%}

{# Create Task Second #}

{% if (desiredState and currentState == undefined) or (currentState != desiredState and currentState != undefined and desiredState != undefined)  %}

        {# Target Table Info #}
        {% set targetTableDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %} 
        {% set targetTableSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %} 
        {% set fullyQualifiedTargetTableName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}


        {% if desiredState.config.schrefresh == true %}
            {%- if desiredState.config.schedulePeriodOption == 'Predecessor' -%} 
                {%- set fullyQualifiedRootTaskName = targetTableDatabase + '.' + targetTableSchema + '."' + desiredState.config.rootTask + '"' -%} 
                {{ stage('Suspend Root Task') }}
                ALTER TASK {{ fullyQualifiedRootTaskName }} SUSPEND
            {%- endif -%}

            {{ stage('Create Task') }}
            {# Set Namespace Variables #}
            {% set nsVariables = namespace(taskWhenRun="") %}
            {% set nsVariables = namespace(poll="WHEN ") %}

            {# Task Info #}
            {% set taskName = desiredState.node.name + '_TASK'  %}
            {%- set fullyQualifiedTaskName = targetTableDatabase + '.' + targetTableSchema + '."' + taskName + '"' -%} 

            {# Task Type #}
            {%- if desiredState.config.schedulingMode == 'Warehouse Task' -%} 
                {# Can be updated during deployment via a parameter to account for different warehouse names in different deployments #}

                {% if 'targetTaskWarehouse'  in  desiredState.parameters %}
                {% if desiredState.parameters.targetTaskWarehouse == 'DEV ENVIRONMENT' %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.config.whName %}
                {% else %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.parameters.targetTaskWarehouse %}
                {% endif %}
                {% endif %}
            {%- else -%}
                {% set taskType = 'USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = ' + getServerSize(desiredState.config.serverlessSize) -%} 
                {%- if desiredState.config.sizeBoundToggle -%}
                        {% set minSrvSize = 'SERVERLESS_TASK_MIN_STATEMENT_SIZE = ' + getServerSize(desiredState.config.minServerlessSize) -%}
                        {% set maxSrvSize = 'SERVERLESS_TASK_MAX_STATEMENT_SIZE = ' + getServerSize(desiredState.config.maxServerlessSize) -%}
                {%- endif -%}
            {%- endif -%}

            {%- set nsTaskVar = namespace(nodeComment='',
                                        userServiceAcct='',
                                        suspendTask='',
                                        autoTry='',
                                        overLapExec='',
                                        configJSON='',
                                        errorIntegration='',
                                        successIntegration='') %}
            {{ getadvancedTaskOptions(nsTaskVar) }}

            {# Schedule Type #}
            {%- if desiredState.config.schedulePeriodOption == 'Minutes' -%} 
                {%- set execValue = desiredState.config.get('execTime').get('items')
                                        | map(attribute='value')
                                        | first %}
                {%- set execPeriod = desiredState.config.get('execTime').get('items')
                                        | map(attribute='period')
                                        | first %}
                {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + execValue | trim ~ ' ' ~ execPeriod | trim + "'" %}
            {% elif desiredState.config.schedulePeriodOption == 'CRON' %}
                {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + 'USING CRON ' + desiredState.config.scheduleCRON | trim + "'" %}
            {%- else -%}
                {%- set nsVariables.taskWhenRun = 'AFTER ' -%}
                {%- set predecessorTasks = (desiredState.config.predTask).split(",") -%}

                {%- for p in predecessorTasks -%}
                    {%- set nsVariables.taskWhenRun = nsVariables.taskWhenRun + targetTableDatabase + '.' + targetTableSchema + '.' + p -%}
                    {%- if not loop.last -%} 
                        {%- set nsVariables.taskWhenRun = nsVariables.taskWhenRun + ',' -%}
                    {%- endif %}
                {% endfor %}    
            {%- endif -%}

            CREATE OR REPLACE TASK 
                {{ fullyQualifiedTaskName }} 
                {{ taskType}} 
            {% if desiredState.config.schedulingMode == 'Serverless Task' and desiredState.config.sizeBoundToggle -%}
                    {{ minSrvSize }}
                    {{ maxSrvSize }}
                {% endif -%}
                {{ nsTaskVar.nodeComment }}
                {{ nsVariables.taskWhenRun }}
                {%- if desiredState.config.schedulePeriodOption != 'Predecessor' %}
                    {{ nsTaskVar.overLapExec }}
                    {%- if desiredState.config.autoSuspendToggle %}
                        {{ nsTaskVar.suspendTask }}
                    {%- endif %}
                    {%- if desiredState.config.autoRetryToggle %}
                        {{ nsTaskVar.autoTry }}
                    {%- endif %}
                    {%- if desiredState.config.taskGraphToggle %}
                        {{ nsTaskVar.configJSON }}
                    {%- endif %}
                    {%- if desiredState.config.errNotifyToggle %}
                        {{ nsTaskVar.errorIntegration }}
                    {%- endif %}
                    {%- if desiredState.config.successNotifyToggle %}
                        {{ nsTaskVar.successIntegration }}
                    {%- endif %}
                {%- endif %}
                {%- if desiredState.config.spfcUserToggle %}
                    {{ nsTaskVar.userServiceAcct }}
                {%- endif %} 
                {% if nsVariables.poll != 'WHEN ' %} {{ nsVariables.poll }} {% endif %}
            AS 
            {%if desiredState.config.tcatalog == 'AWS Glue' %}

		          ALTER ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }} REFRESH

	        {%elif desiredState.config.tcatalog == 'Object storage' %}

		          ALTER ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }} REFRESH '{{desiredState.config.metafilepath}}'

	       {%endif%}


            {%- if desiredState.config.schedulePeriodOption != 'Predecessor' -%} 
                {{ stage('Resume Task') }}
                ALTER TASK {{ fullyQualifiedTaskName }} RESUME;
            {%- endif -%}

        {%- endif -%}

{% elif currentState != undefined and desiredState == undefined %}

    {# Target Table Info #}
    {% set targetTableDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetTableSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetTableName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

    {% if currentState.config.schrefresh == true %}
        {# FQ Root Task name #}
        {% set fullyQualifiedRootTaskName = targetTableDatabase + '.' + targetTableSchema + '."' + currentState.config.rootTask + '"'%}

        {# Task Info #}
        {% set taskName = currentState.node.name + '_TASK'  %}
        {%- set fullyQualifiedTaskName = targetTableDatabase + '.' + targetTableSchema + '."' + taskName + '"' -%} 

        {%- if currentState.config.schedulePeriodOption == 'Predecessor' -%} 
        {{ stage('Suspend Root Task') }}
            ALTER TASK IF EXISTS {{ fullyQualifiedRootTaskName }} SUSPEND
        {{ stage('Drop Current Task') }}
            DROP TASK IF EXISTS {{ fullyQualifiedTaskName }} 
        {%- else -%}
        {{ stage('Drop Current Task') }}
            DROP TASK IF EXISTS {{ fullyQualifiedTaskName }} 
        {%- endif -%}
    {%- endif -%}

{% endif %}

run.templateString:
{#
    Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : Copy-Into Iceberg tables == #}
{# == Node Type Description    : This node creates an Iceberg target table to load data from internal or external stages using Copy-Into == #}


# Storage Location-database and schema

{% set srcSchName = node.location.name %}
{% set db = storageLocations | selectattr('name', 'equalto', srcSchName) | map(attribute='database') | first %}
{% set sch = storageLocations | selectattr('name', 'equalto', srcSchName) | map(attribute='schema') | first %}

# Internal or External Stage locations

{% set stageStorageLocationName = config.stageStorageLocationName %}
{% set dbStage = storageLocations | selectattr('name', 'equalto', stageStorageLocationName) | map(attribute='database') | first %}
{% set schStage = storageLocations | selectattr('name', 'equalto', stageStorageLocationName) | map(attribute='schema') | first %}
{% set ns = namespace(counter=1, countercol=1, colist="") %}	

# File format locations

{% set fileFormatLocationName = config.fileFormatLoc %}
{% set dbff = storageLocations | selectattr('name', 'equalto',fileFormatLocationName) | map(attribute='database') | first %}
{% set schff = storageLocations | selectattr('name', 'equalto',fileFormatLocationName) | map(attribute='schema') | first %}


# File pattern

{%- if config.filePattern | length > 0 -%} 
    {%- set filePatternSQL = 'PATTERN = ' + config.filePattern -%} 
{%- else -%}
    {%- set filePatternSQL = "" -%} 
{%- endif -%}

# File name

{%- if config.fileNames | length > 0 %} 
    {% set fileNameSQL = 'FILES = (' + config.fileNames + ')' %} 
{%- else -%}
    {% set fileNameSQL = "" %} 
{% endif %}

# Checking on number of columns

     {%- for col in sources[0].columns %}
	    {% if not( col.sysLdTs or col.sysFlNm or col.sysFlRwNm or col.sysFlLtMd or col.sysFlScTm or col.sysJSON )%}
                        {% set ns.countercol = ns.countercol + 1 %}       
	    {%endif%}
    {%- endfor %}

{%- if parameters.loadType == 'Reload' or config.truncateBefore == true -%}

   {{ stage('Truncate Target Table') }}
    TRUNCATE TABLE IF EXISTS "{{ db }}"."{{ sch }}"."{{ node.name }}"

 {{ stage('Reload-Using Copy-into') }}

{%else %}

 {{ stage('Full Load-Using Copy-into') }}

{%endif%}

    {%if config.intextstage %}
             COPY INTO "{{ db }}"."{{ sch }}"."{{ node.name }}" (
            {%- for col in columns %}
                "{{ col.name }}"
            {%- if not loop.last -%}, {% endif %}
            {%- endfor %}
        )
        FROM (SELECT

            {%- for col in sources[0].columns %}
	           {% if not( col.sysLdTs or col.sysFlNm or col.sysFlRwNm or col.sysFlLtMd or col.sysFlScTm or col.sysJSON or col.transform != "" ) %}
                      {%if (config.fileType == 'JSON') or (config.fileType == 'PARQUET') or (config.fileType == 'ORC') or (config.fileType == 'AVRO')   %}
                         ${{ ns.counter}}:{{col.name}}::{{ col.dataType}}  AS "{{ col.name }}" 
                      {%else%}
                        ${{ ns.counter}}::{{ col.dataType}}   AS "{{ col.name }}"  
                        {% set ns.counter = ns.counter + 1 %}       
                      {%endif%}       
	           {% else %}
	                  {{ get_source_transform(col) }} AS "{{ col.name }}" 
	           {%endif%}
            {%- if not loop.last -%}, {% endif %}
            {%- endfor %}

           FROM '@{{ dbStage }}.{{ schStage }}.{{ config.stageName }}') 
           {{fileNameSQL}}
           {{ filePatternSQL }}

   {%elif config.extlocation %}  

        COPY INTO "{{ db }}"."{{ sch }}"."{{ node.name }}"        
       {%if ns.countercol == 1 %}  (SRC)
       {%elif ns.countercol >1 and config.fileType in ('CSV') %}
       (   {%- for col in sources[0].columns %}
	           {% if not( col.sysLdTs or col.sysFlNm or col.sysFlRwNm or col.sysFlLtMd or col.sysFlScTm or col.sysJSON )%}
	              {% set ns.colist = ns.colist ~ col.name ~ ',' %}
            {%endif%}
            {%- endfor %}
            {{ ns.colist.rstrip(',') }} )
       {%endif%}
        FROM '{{config.externalURI}}'

        {%- if config.storageintegration
            and config.storageintegration | trim | length > 0
            and config.storageintegration | lower != "null" %}

            STORAGE_INTEGRATION = {{config.storageintegration}}

        {%- endif %}

   {%endif%}


          {%- if config.fileFormatType == 'File Format Name' %}

              FILE_FORMAT = (FORMAT_NAME = '{{ dbff }}.{{ schff }}.{{ config.fileFormatName}}')


      {%else%}
            FILE_FORMAT = ( TYPE = {{ config.fileType}}
             {% if config.compression != "" %}
              COMPRESSION = {{ config.compression }}
             {%endif%}			 
             {% if config.recDelim and config.fileType in ('CSV')%}
              RECORD_DELIMITER = '{{ config.recDelim}}'
             {%endif%}
            {% if config.fieldDelim and config.fileType in ('CSV')%}
              FIELD_DELIMITER = '{{ config.fieldDelim}}'
            {%endif%}
          {% if config.fieldEnclosed and config.fileType in ('CSV')%}
               FIELD_OPTIONALLY_ENCLOSED_BY ='{{ config.fieldEnclosed }}'
          {%endif%}
          {% if config.skipBlankLines and config.fileType in ('CSV')%}
             SKIP_BLANK_LINES =  {{ config.skipBlankLines }}
          {%endif%}
          {% if config.skipHeader and config.fileType in ('CSV')%}
             SKIP_HEADER = {{config.skipHeader}}
          {%endif%}
          {% if config.trimSpace and config.fileType not in ('XML') %}
              TRIM_SPACE = {{ config.trimSpace }}
          {%endif%}
          {% if config.replaceinvalidcharacters%}
              REPLACE_INVALID_CHARACTERS = {{config.replaceinvalidcharacters}}
          {%endif%}
          {% if config.stripouterarray and config.fileType in ('JSON')%}
              STRIP_OUTER_ARRAY = {{config.stripouterarray}}
          {%endif%}
            {% if config.dateformat != "AUTO" and config.dateformat != ""   and config.fileType in ('JSON','CSV')%}
              DATE_FORMAT = '{{config.dateformat}}'
	       {% elif config.dateformat == "AUTO" %}
	         DATE_FORMAT = AUTO
           {%endif%}
             {% if config.timeformat != "AUTO" and config.timeformat != ""   and config.fileType in ('JSON','CSV')%}
              TIME_FORMAT = '{{config.timeformat}}'
	       {% elif config.timeformat == "AUTO" %}
	         TIME_FORMAT = AUTO
           {%endif%}
           {% if config.timestampformat != "AUTO" and config.timestampformat != ""   and config.fileType in ('JSON','CSV')%}
              TIMESTAMP_FORMAT = '{{config.timestampformat}}'
	         {% elif config.timestampformat == "AUTO" %}
	         TIMESTAMP_FORMAT = AUTO
           {%endif%})
        {%endif%}

        {% if config.onError != "" %}
            {% if config.onError in ('SKIP_FILE_<num>') %}
              {% set onErrorReplaced = config.onError | replace('<num>', config.errornumber|string) %}
               ON_ERROR = {{ onErrorReplaced }}
            {%elif config.onError in ('SKIP_FILE_<num>%') %}
              {% set onErrorReplaced = config.onError | replace('<num>', config.errornumber|string) %}
               ON_ERROR = '{{ onErrorReplaced }}'
            {%else%}
               ON_ERROR = {{ config.onError }}
            {%endif%}
        {%endif%}

        {% if config.sizeLimit != "" %}
             SIZE_LIMIT = {{ config.sizeLimit }}
        {%endif%}
        {% if config.returnFailedOnly != "" %}
             RETURN_FAILED_ONLY = {{ config.returnFailedOnly }}
        {%endif%}
        {% if config.loadUncertainFiles != ""%}
              LOAD_UNCERTAIN_FILES = {{ config.loadUncertainFiles }}
        {%endif%}
        {% if config.purgeBehavior != "" %}
              PURGE =  {{ config.purgeBehavior }}
        {%endif%}
        {% if config.enforceLength != ""%}
              ENFORCE_LENGTH = {{ config.enforceLength }}
        {%endif%}
        {% if config.truncateColumns != ""%}
              TRUNCATECOLUMNS = {{ config.truncateColumns }}
        {%endif%}
        {%if  config.extlocation and ns.countercol>1 and config.fileType not in ('CSV') %}
             MATCH_BY_COLUMN_NAME = CASE_SENSITIVE        
        {%endif%}
        {%- if parameters.loadType == 'Reload' or config.truncateBefore == true-%}
		     FORCE=TRUE
		{%endif%}

create.templateString:
{#
    Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : Copy-Into Iceberg tables == #}
{# == Node Type Description    : This node creates an Iceberg target table to load data from internal or external stages using Copy-Into == #}


# Create table first

{% if currentState == undefined or currentState.storageLocations|length == 0%}

          {%set extvol = '' %}
          {%set baseloc ='' %}

        #External volume
          {%if desiredState.config.extvol != '' %}
            {%set extvol =  desiredState.config.extvolume %}
          {%endif%}


        #Baselocation
        {%if desiredState.config.basename != '' %}
            {%set baseloc =  desiredState.config.basename %}
        {%endif%}

        #Catalog sync
        {%if desiredState.config.catint != '' and desiredState.config.tcatalog == 'Polaris' %}
           {%set catsync = desiredState.config.catint %}
        {%endif%}

        #Figure out cluster key

        {% set nsVariables = namespace(finalClusterKey="") %}
        {% if desiredState.config.clusterKey == true %}
            {% if desiredState.config.clusterKeyExpressions == true %}
                {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='columnNameExpressions.name') | list, desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='sqlExpression') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% if expression[loop.index0] == "" %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                    {% else %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + [expression[loop.index0]] %}
                    {% endif %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% else %}

                {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% endif %}
        {% endif %}


         {{ stage('Create Iceberg Table') }}

         CREATE OR REPLACE ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
        (
          {% for col in desiredState.columns %}
           "{{ col.name }}" {{icebergcoldatatype( col.dataType)}}
           {% if col.isSurrogateKey %}
               identity
           {% endif %}
           {%- if not col.nullable %} NOT NULL
               {%- if col.defaultValue | length > 0 %} DEFAULT {{ col.defaultValue }}{% endif %}
           {% endif %}
           {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
           {%- if not loop.last -%}, {% endif %}
          {% endfor %})

          {%if desiredState.config.clusterKey == true%} {{ nsVariables.finalClusterKey }}   {%endif%}

         CATALOG  =   'SNOWFLAKE'
        {%if extvol != '' %} EXTERNAL_VOLUME = '{{extvol}}' {%endif%}
        {%if baseloc != '' %} BASE_LOCATION = '{{baseloc}}'{%endif%} 
        {%if catsync != '' and desiredState.config.tcatalog == 'Polaris' %} CATALOG_SYNC = '{{catsync}}' {%endif%}


	    {%- if desiredState.node.description | length > 0 %} COMMENT = '{{ desiredState.node.description | escape }}'

    {% endif %}		    

{%elif currentState!=undefined and currentState!=desiredState and desiredState!=undefined%}


      {% if 
        clusterKeyTest == false or
        clusterKeyExpressionsTest == false or
        clusterKeyConfigTest == false or
        clusterKeyConfigExpressionsTest == false %}

             {% set clusterTest = false %}
        {% else %}
             {% set clusterTest = true %}
        {% endif %}



        {% set nodeCommentTest = currentState.node.description == desiredState.node.description %}
        {% set extvoltest = currentState.config.extvolume == desiredState.config.extvolume %}
        {% set baseloctest = currentState.config.basename == desiredState.config.basename%}


        {% set ns = namespace(
    colchanges = 0,
    colchangescdt = 0,
    acolchanges = 0,
    dcolchanges = 0,
    targetlocationtest =true
) %}

        {#Target location test#}
         {%set currenttargetlocation = currentState.node.location.name %}
         {%set desiredtargetlocation = desiredState.node.location.name %}


            {% set currentDatabase = currentState.storageLocations | selectattr('name', 'equalto', currenttargetlocation) | map(attribute='database') | first %}
            {% set currentSchema = currentState.storageLocations | selectattr('name', 'equalto', currenttargetlocation) | map(attribute='schema') | first %}
            {% set tcurrentDatabaseSchema = currentDatabase + '.' + currentSchema %}


            {% set desiredDatabase = desiredState.storageLocations | selectattr('name', 'equalto', desiredtargetlocation) | map(attribute='database') | first %}
            {% set desiredSchema = desiredState.storageLocations | selectattr('name', 'equalto', desiredtargetlocation) | map(attribute='schema') | first %}
            {% set tdesiredDatabaseSchema = desiredDatabase + '.' + desiredSchema %}

        {%if tdesiredDatabaseSchema != tcurrentDatabaseSchema  %}

         {%set ns.targetlocationtest = false %}
        {%endif%}      

            {# Drop Columns #}

            {% for dropCurCol in currentState.columns %}
                {% if dropCurCol.id not in desiredState.columns | map(attribute="id") %}
                     {% set ns.dcolchanges = ns.dcolchanges + 1 %}
                {% endif %}
            {% endfor %}

            {# Add Columns #}

            {% for addDesCol in desiredState.columns %}
                {% if addDesCol.id not in currentState.columns | map(attribute="id") %}
                   {% set ns.acolchanges = ns.acolchanges + 1 %}
                {%endif%}
            {% endfor %}


            {% for alterCurCol in currentState.columns %}  

             {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}


                    {% set currentDatatype = alterCurCol.dataType %}
                    {% set currentNullable = alterCurCol.nullable %}
                    {% set currentDefaultValue = alterCurCol.defaultValue %}
                    {% set currentDescription = alterCurCol.description %}


                    {% set desiredColumnName = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='name') | first %}
                    {% set desiredDatatype = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='dataType') | first %}
                    {% set desiredNullable = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='nullable') | first %}
                    {% set desiredDefaultValue = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='defaultValue') | first %}
                    {% set desiredDescription = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='description') | first %}


                    {% set datatypeTest = currentDatatype == desiredDatatype %}
                    {% set nullableTest = currentNullable == desiredNullable %}
                    {% set defaultValueTest = currentDefaultValue == desiredDefaultValue %}
                    {% set descriptionTest = currentDescription == desiredDescription %}
                        {% if (
                            nullableTest == false  or
                            defaultValueTest == false or
                            descriptionTest == false) %}
                        {% set ns.colchanges = ns.colchanges + 1 %}

                    {% endif %}
                    {%if 'OBJECT' not in alterCurCol.dataType and 'MAP' not in alterCurCol.dataType and 'ARRAY'  not in alterCurCol.dataType  %} 

                    {% if datatypeTest == false  %}
                        {% set ns.colchanges = ns.colchanges + 1 %}                                                 
                    {% endif %}
                    {%else%}

                    {% if datatypeTest == false  %}
                        {% set ns.colchangescdt = ns.colchangescdt + 1 %}                                                 
                    {% endif %}

                   {% endif %}
              {%endif%} 
            {% endfor %}



        {# Create Iceberg table-redeployment #}

{% if  currentState.node.name != desiredState.node.name or currentState.node.location.name!= desiredState.node.location.name or baseloctest == false  or ns.colchanges > 0 or ns.acolchanges >0 or ns.dcolchanges > 0 or nodeCommentTest == false or extvoltest == false or clusterTest == false or  ns.targetlocationtest  == false%}


          {%set extvol = '' %}
          {%set catalogval = '' %}
          {%set catalogtablename ='' %}
          {%set catalogdbname ='' %}
          {%set metafilepath ='' %}
          {%set baseloc ='' %}

        #External volume
        {%if desiredState.config.extvol != '' %}
            {%set extvol =  desiredState.config.extvolume %}
        {%endif%}

        #Baselocation
        {%if desiredState.config.basename != '' %}
            {%set baseloc =  desiredState.config.basename %}
        {%endif%}

        #Catalog sync
        {%if desiredState.config.catint != '' and desiredState.config.tcatalog == 'Polaris' %}
           {%set catsync = desiredState.config.catint %}
        {%endif%}

        #Figure out cluster key

        {% set nsVariables = namespace(finalClusterKey="") %}
        {% if desiredState.config.clusterKey == true %}
            {% if desiredState.config.clusterKeyExpressions == true %}
                {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='columnNameExpressions.name') | list, desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='sqlExpression') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% if expression[loop.index0] == "" %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                    {% else %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + [expression[loop.index0]] %}
                    {% endif %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% else %}

                {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% endif %}
        {% endif %}

        {%if currentState.node.name != desiredState.node.name or ns.targetlocationtest == false%}

           {{ stage('Drop Iceberg Table at previous target location') }}

           DROP ICEBERG TABLE IF EXISTS {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

        {%endif%}

        {{ stage('Create Iceberg Table') }}

         CREATE OR REPLACE ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
         (
          {% for col in desiredState.columns %}
           "{{ col.name }}" {{icebergcoldatatype( col.dataType)}}
           {% if col.isSurrogateKey %}
               identity
           {% endif %}
           {%- if not col.nullable %} NOT NULL
               {%- if col.defaultValue | length > 0 %} DEFAULT {{ col.defaultValue }}{% endif %}
           {% endif %}
           {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
           {%- if not loop.last -%}, {% endif %}
          {% endfor %}
           )
          {%if desiredState.config.clusterKey == true%} {{ nsVariables.finalClusterKey }}   {%endif%}


        {%if extvol != '' %} EXTERNAL_VOLUME = '{{extvol}}' {%endif%}
        {%if baseloc != '' %} BASE_LOCATION = '{{baseloc}}'{%endif%}
        {%if catsync != '' and desiredState.config.tcatalog == 'Polaris' %} CATALOG_SYNC = '{{catsync}}' {%endif%}
        CATALOG  =   'SNOWFLAKE'

	    {%- if desiredState.node.description | length > 0 %} COMMENT = '{{ desiredState.node.description | escape }}'	
        {%endif%}  

 {%elif  currentState.node.name == desiredState.node.name and
 currentState.node.location.name == desiredState.node.location.name  and ns.colchangescdt > 0 %}


{% set ns1 = namespace(renamefield = false,element_names1 = [],element_names2 = []) %}


     {% for alterCurCol in currentState.columns %}  
         {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}

                    {% set currentDatatype = alterCurCol.dataType %}
                    {% set desiredColname = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='name') | first %}
                    {% set desiredDatatype = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='dataType') | first %}


        {%if 'OBJECT'  in alterCurCol.dataType or 'MAP'  in alterCurCol.dataType or 'ARRAY'   in alterCurCol.dataType  %} 

            {%if 'ARRAY' not in alterCurCol.dataType %}

                    {%if 'OBJECT'  in alterCurCol.dataType %}
                      {% set elements1 = currentDatatype[7:-1].split(',') %}
                      {% set elements2 = desiredDatatype[7:-1].split(',') %}
                    {%elif 'MAP'  in alterCurCol.dataType %}
                      {% set elements1 = currentDatatype[4:-1].split(',') %}
                      {% set elements2 = desiredDatatype[4:-1].split(',') %}
                    {%endif%}


                    {% for element in elements1 %}
                       {% set element_name = element.split()[0] %}
                       {% set ns1.element_names1 = ns1.element_names1 + [element_name] %}
                    {% endfor %}


                    {% for element in elements2 %}
                        {% set element_name = element.split()[0] %}
                        {% set ns1.element_names2 = ns1.element_names2 + [element_name] %}
                    {% endfor %} 

                     {%set ele1 = ns1.element_names1|count %}
                     {%set ele2 = ns1.element_names2|count %}
                    {%if ele1 == ele2 %}
                    {% for name1 in ns1.element_names1 %}
                      {% if name1 not in ns1.element_names2%}

                        {%set  ns1.renamefield = true %}
                      {% endif %}
                    {% endfor %}
                    {%endif%}
            {%endif%}


                    {%if ns1.renamefield == true %}

					    {{ stage('Alter structured data type in Iceberg Table') }}

                        ALTER ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}ALTER COLUMN {{ desiredColname }} SET DATA TYPE {{ desiredDatatype }} RENAME FIELDS
                    {%else%}

                        {{ stage('Alter structured data type in Iceberg Table') }}

                        ALTER ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}ALTER COLUMN {{ desiredColname }} SET DATA TYPE {{ desiredDatatype }}
                    {%endif%}


                {% endif %}                   
         {% endif %}
      {% endfor %}



 {%endif%} 


{%elif  currentState != undefined and desiredState == undefined%}

    {# Table or View Name #}
    {% set targetObjectDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetObjectSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetObjectName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

        {{ stage('Drop iceberg table') }}
         DROP ICEBERG TABLE IF EXISTS {{ fullyQualifiedTargetObjectName }}

{%endif%}

run.templateString:
{#
    Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : SnowPipe == #}
{# == Node Type Description    : This node creates an Iceberg target table to load data from internal or external stages using Copy-Into.Also creates a pipe to  loads data from files as soon as they are available in a stage external == #}


{%if config.flagSnowpipe == 'Test Copy Statement'%}

     {% set srcSchName = node.location.name %}
     {% set db = storageLocations | selectattr('name', 'equalto', srcSchName) | map(attribute='database') | first %}
     {% set sch = storageLocations | selectattr('name', 'equalto', srcSchName) | map(attribute='schema') | first %}
     {% set tbl = node.name %}
     {% set fqTblName = '"' + db + '"."' + sch + '"."' + tbl + '"' %}
     {% set fqPipeName = '"' + db + '"."' + sch + '"."' + tbl + '_PIPE"' %}



     {% set stageStorageLocationName = config.stageStorageLocationName %}
     {% set dbStage = storageLocations | selectattr('name', 'equalto', stageStorageLocationName) | map(attribute='database') | first %}
     {% set schStage = storageLocations | selectattr('name', 'equalto', stageStorageLocationName) | map(attribute='schema') | first %}
     {% set ns = namespace(counter=1) %}

	  {%- if config.filePattern | length > 0 -%} 
        {%- set filePatternSQL = 'PATTERN = ' + config.filePattern -%} 
      {%- else -%}
        {%- set filePatternSQL = "" -%} 
     {%- endif -%}

     {%- if config.fileNames | length > 0 %} 
       {% set fileNameSQL = 'FILES = (' + config.fileNames + ')' %} 
     {%- else -%}
       {% set fileNameSQL = "" %} 
     {% endif %}

	 {% set fileFormatLocationName = config.fileFormatLoc %}
     {% set dbff = storageLocations | selectattr('name', 'equalto',fileFormatLocationName) | map(attribute='database') | first %}
     {% set schff = storageLocations | selectattr('name', 'equalto',fileFormatLocationName) | map(attribute='schema') | first %}

   {{ stage('Load-Using Copy-into', true, "sql", "alter") }}


COPY INTO "{{ db }}"."{{ sch }}"."{{ node.name }}" (
            {%- for col in columns %}
                "{{ col.name }}"
            {%- if not loop.last -%}, {% endif %}
            {%- endfor %}
        )
        FROM (SELECT

            {%- for col in sources[0].columns %}
	           {% if not( col.sysLdTs or col.sysFlNm or col.sysFlRwNm or col.sysFlLtMd or col.sysFlScTm or col.sysJSON )%}
                      {%if (config.fileType == 'JSON') or (config.fileType == 'PARQUET') or (config.fileType == 'ORC') or (config.fileType == 'AVRO')%}
                         ${{ ns.counter}}:{{col.name}}::{{ col.dataType}}  AS "{{ col.name }}"
                      {%else%}
                        ${{ ns.counter}}::{{ col.dataType}}   AS "{{ col.name }}" 
                        {% set ns.counter = ns.counter + 1 %}       
                      {%endif%}       
	           {% else %}
	                  {{ get_source_transform(col) }} AS "{{ col.name }}"
	           {%endif%}
            {%- if not loop.last -%}, {% endif %}
            {%- endfor %}

            FROM '@{{ dbStage }}.{{ schStage }}.{{ config.stageName }}') 
            {{ fileNameSQL }}
            {{ filePatternSQL }}

          {%- if config.fileFormatType == 'File Format Name' %}
          FILE_FORMAT = (FORMAT_NAME = '{{ dbff }}.{{ schff }}.{{ config.fileFormatName}}')
         {%else%}
            FILE_FORMAT = ( TYPE = {{ config.fileType}}
             {% if config.compression != "" %}
              COMPRESSION = {{config.compression }}
             {%endif%}

             {% if config.recDelim and config.fileType in ('CSV')%}
              RECORD_DELIMITER = '{{config.recDelim}}'
             {%endif%}

            {% if config.fieldDelim and config.fileType in ('CSV')%}
              FIELD_DELIMITER = '{{config.fieldDelim}}'
            {%endif%}
          {% if config.fieldEnclosed and config.fileType in ('CSV')%}
               FIELD_OPTIONALLY_ENCLOSED_BY ='{{config.fieldEnclosed }}'
          {%endif%}
          {% if config.skipBlankLines and config.fileType in ('CSV')%}
             SKIP_BLANK_LINES =  {{ config.skipBlankLines }}
          {%endif%}
          {% if config.skipHeader and config.fileType in ('CSV')%}
             SKIP_HEADER = {{config.skipHeader}}
          {%endif%}
          {% if config.trimSpace and config.fileType not in ('XML')%}
              TRIM_SPACE = {{config.trimSpace }}
          {%endif%}
          {% if config.replaceinvalidcharacters%}
              REPLACE_INVALID_CHARACTERS = {{config.replaceinvalidcharacters}}
          {%endif%}
          {% if config.stripouterarray and config.fileType in ('JSON')%}
              STRIP_OUTER_ARRAY = {{config.stripouterarray}}
          {%endif%}
          {% if config.dateformat != "AUTO" and config.dateformat != ""   and config.fileType in ('JSON','CSV')%}
              DATE_FORMAT = '{{config.dateformat}}'
	       {% elif config.dateformat == "AUTO" %}
	         DATE_FORMAT = AUTO
           {%endif%}
             {% if config.timeformat != "AUTO" and config.timeformat != ""   and config.fileType in ('JSON','CSV')%}
              TIME_FORMAT = '{{config.timeformat}}'
	       {% elif config.timeformat == "AUTO" %}
	         TIME_FORMAT = AUTO
           {%endif%}
           {% if config.timestampformat != "AUTO" and config.timestampformat != ""   and config.fileType in ('JSON','CSV')%}
              TIMESTAMP_FORMAT = '{{config.timestampformat}}'
	       {% elif config.timestampformat == "AUTO" %}
	         TIMESTAMP_FORMAT = AUTO
           {%endif%} 
          )
        {%endif%}

        {% if config.onError != "" %}
            {% if config.onError in ('SKIP_FILE_<num>') %}
              {% set onErrorReplaced = config.onError | replace('<num>', config.errornumber|string) %}
               ON_ERROR = {{ onErrorReplaced }}
        {%elif config.onError in ('SKIP_FILE_<num>%') %}
              {% set onErrorReplaced = config.onError | replace('<num>', config.errornumber|string) %}
               ON_ERROR = '{{ onErrorReplaced }}'
        {%else%}
               ON_ERROR = {{ config.onError }}
            {%endif%}
        {%endif%}

        {% if config.enforceLength != ""%}
              ENFORCE_LENGTH = {{ config.enforceLength }}
        {%endif%}
        {% if config.truncateColumns != ""%}
              TRUNCATECOLUMNS = {{ config.truncateColumns }}
        {%endif%}

{% else %}

  {{ stage('Snowpipe Enabled - No Test Run') }}
  -- This node is configured to run as a Snowpipe with Auto Ingestion.
  -- Manual execution is only possible when 'Test Copy Statement' is enabled in the configuration.
  -- For more details, review Snowflake for the pipe definition: {{node.name}}_PIPE
  SELECT 1 AS INFO_MESSAGE WHERE FALSE

{%endif%}

create.templateString:
{#
    Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : Snowpipe == #}
{# == Node Type Description    : This node creates an Iceberg target table to load data from internal or external stages using Copy-Into.Also creates a pipe to  loads data from files as soon as they are available in a stage external == #}

{%if desiredState and currentState != desiredState%}
     {%if desiredState.parameters == {} or 'targetIntegrationOrAwsSNSTopic' not in desiredState.parameters or desiredState.parameters.targetIntegrationOrAwsSNSTopic == ''%}

         {{stage('WARNING')}}   
         /*

         1.Add parameter loadType in Workspace and 
          deployment environment if you intend to reload data from source files

         2.Add parameter targetIntegrationOrAwsSNSTopic in Workspace and 
          deployment environment if the snowpipe is enabled for successful execution of node.
         The default value for the parameter is 'DEV ENVIRONMENT'.

         Refer to documentation for more information */

      {%endif%}
{%endif%}


{# Create table first #}

{% if currentState == undefined or currentState.storageLocations|length == 0%}


          {%set extvol = '' %}
          {%set baseloc ='' %}

        {#External volume#}
          {%if desiredState.config.extvol != '' %}
            {%set extvol =  desiredState.config.extvolume %}
          {%endif%}


        {#Baselocation#}
        {%if desiredState.config.basename != '' %}
            {%set baseloc =  desiredState.config.basename %}
        {%endif%}

        {#Catalog sync#}
        {%if desiredState.config.catint != '' and desiredState.config.tcatalog == 'Polaris' %}
           {%set catsync = desiredState.config.catint %}
        {%endif%}

        {#Figure out cluster key#}

        {% set nsVariables = namespace(finalClusterKey="") %}
        {% if desiredState.config.clusterKey == true %}
            {% if desiredState.config.clusterKeyExpressions == true %}
                {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='columnNameExpressions.name') | list, desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='sqlExpression') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% if expression[loop.index0] == "" %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                    {% else %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + [expression[loop.index0]] %}
                    {% endif %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% else %}

                {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% endif %}
        {% endif %}


         {{ stage('Create Iceberg Table') }}

         CREATE OR REPLACE ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
        (
          {% for col in desiredState.columns %}
           "{{ col.name }}" {{icebergcoldatatype( col.dataType)}}
           {% if col.isSurrogateKey %}
               identity
           {% endif %}
           {%- if not col.nullable %} NOT NULL
               {%- if col.defaultValue | length > 0 %} DEFAULT {{ col.defaultValue }}{% endif %}
           {% endif %}
           {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
           {%- if not loop.last -%}, {% endif %}
          {% endfor %})

          {%if desiredState.config.clusterKey == true%} {{ nsVariables.finalClusterKey }}   {%endif%}

         CATALOG  =   'SNOWFLAKE'
        {%if extvol != '' %} EXTERNAL_VOLUME = '{{extvol}}' {%endif%}
        {%if baseloc != '' %} BASE_LOCATION = '{{baseloc}}'{%endif%} 
        {%if catsync != '' and desiredState.config.tcatalog == 'Polaris' %} CATALOG_SYNC = '{{catsync}}' {%endif%}


	    {%- if desiredState.node.description | length > 0 %} COMMENT = '{{ desiredState.node.description | escape }}'

    {% endif %}		    

{%elif currentState!=undefined and currentState!=desiredState and desiredState!=undefined%}


      {% if 
        clusterKeyTest == false or
        clusterKeyExpressionsTest == false or
        clusterKeyConfigTest == false or
        clusterKeyConfigExpressionsTest == false %}

             {% set clusterTest = false %}
        {% else %}
             {% set clusterTest = true %}
        {% endif %}



        {% set nodeCommentTest = currentState.node.description == desiredState.node.description %}
        {% set extvoltest = currentState.config.extvolume == desiredState.config.extvolume %}
        {% set baseloctest = currentState.config.basename == desiredState.config.basename%}


        {% set ns = namespace(
    colchanges = 0,
    colchangescdt = 0,
    acolchanges = 0,
    dcolchanges = 0,
    targetlocationtest =true
) %}

        {#Target location test#}
         {%set currenttargetlocation = currentState.node.location.name %}
         {%set desiredtargetlocation = desiredState.node.location.name %}

            {% set currentDatabase = currentState.storageLocations | selectattr('name', 'equalto', currenttargetlocation) | map(attribute='database') | first %}
            {% set currentSchema = currentState.storageLocations | selectattr('name', 'equalto', currenttargetlocation) | map(attribute='schema') | first %}
            {% set tcurrentDatabaseSchema = currentDatabase + '.' + currentSchema %}

            {% set desiredDatabase = desiredState.storageLocations | selectattr('name', 'equalto', desiredtargetlocation) | map(attribute='database') | first %}
            {% set desiredSchema = desiredState.storageLocations | selectattr('name', 'equalto', desiredtargetlocation) | map(attribute='schema') | first %}
            {% set tdesiredDatabaseSchema = desiredDatabase + '.' + desiredSchema %}

        {%if tdesiredDatabaseSchema != tcurrentDatabaseSchema  %}

         {%set ns.targetlocationtest = false %}
        {%endif%}      

            {# Drop Columns #}

            {% for dropCurCol in currentState.columns %}
                {% if dropCurCol.id not in desiredState.columns | map(attribute="id") %}
                     {% set ns.dcolchanges = ns.dcolchanges + 1 %}
                {% endif %}
            {% endfor %}

            {# Add Columns #}

            {% for addDesCol in desiredState.columns %}
                {% if addDesCol.id not in currentState.columns | map(attribute="id") %}
                   {% set ns.acolchanges = ns.acolchanges + 1 %}
                {%endif%}
            {% endfor %}


            {% for alterCurCol in currentState.columns %}  

             {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}


                    {% set currentDatatype = alterCurCol.dataType %}
                    {% set currentNullable = alterCurCol.nullable %}
                    {% set currentDefaultValue = alterCurCol.defaultValue %}
                    {% set currentDescription = alterCurCol.description %}


                    {% set desiredColumnName = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='name') | first %}
                    {% set desiredDatatype = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='dataType') | first %}
                    {% set desiredNullable = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='nullable') | first %}
                    {% set desiredDefaultValue = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='defaultValue') | first %}
                    {% set desiredDescription = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='description') | first %}


                    {% set datatypeTest = currentDatatype == desiredDatatype %}
                    {% set nullableTest = currentNullable == desiredNullable %}
                    {% set defaultValueTest = currentDefaultValue == desiredDefaultValue %}
                    {% set descriptionTest = currentDescription == desiredDescription %}
                        {% if (
                            nullableTest == false  or
                            defaultValueTest == false or
                            descriptionTest == false) %}
                        {% set ns.colchanges = ns.colchanges + 1 %}

                    {% endif %}
                    {%if 'OBJECT' not in alterCurCol.dataType and 'MAP' not in alterCurCol.dataType and 'ARRAY'  not in alterCurCol.dataType  %} 

                    {% if datatypeTest == false  %}
                        {% set ns.colchanges = ns.colchanges + 1 %}                                                 
                    {% endif %}
                    {%else%}

                    {% if datatypeTest == false  %}
                        {% set ns.colchangescdt = ns.colchangescdt + 1 %}                                                 
                    {% endif %}

                   {% endif %}
              {%endif%} 
            {% endfor %}



        {# Create Iceberg table-redeployment #}

{% if  currentState.node.name != desiredState.node.name or currentState.node.location.name!= desiredState.node.location.name or baseloctest == false  or ns.colchanges > 0 or ns.acolchanges >0 or ns.dcolchanges > 0 or nodeCommentTest == false or extvoltest == false or clusterTest == false or ns.targetlocationtest  == false%}


          {%set extvol = '' %}
          {%set catalogval = '' %}
          {%set catalogtablename ='' %}
          {%set catalogdbname ='' %}
          {%set metafilepath ='' %}
          {%set baseloc ='' %}

        #External volume
        {%if desiredState.config.extvol != '' %}
            {%set extvol =  desiredState.config.extvolume %}
        {%endif%}

        #Baselocation
        {%if desiredState.config.basename != '' %}
            {%set baseloc =  desiredState.config.basename %}
        {%endif%}

        #Catalog sync
        {%if desiredState.config.catint != '' and desiredState.config.tcatalog == 'Polaris' %}
           {%set catsync = desiredState.config.catint %}
        {%endif%}

        #Figure out cluster key

        {% set nsVariables = namespace(finalClusterKey="") %}
        {% if desiredState.config.clusterKey == true %}
            {% if desiredState.config.clusterKeyExpressions == true %}
                {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='columnNameExpressions.name') | list, desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='sqlExpression') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% if expression[loop.index0] == "" %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                    {% else %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + [expression[loop.index0]] %}
                    {% endif %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% else %}

                {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}

                {%- set nsVariables = namespace(clusterValues=[]) %}

                {% for r in column %}
                    {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% endif %}
        {% endif %}

        {%if currentState.node.name != desiredState.node.name or ns.targetlocationtest == false%}

           {{ stage('Drop Iceberg Table at previous target location') }}

           DROP ICEBERG TABLE IF EXISTS {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

        {%endif%}

        {{ stage('Create Iceberg Table') }}

         CREATE OR REPLACE ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
         (
          {% for col in desiredState.columns %}
           "{{ col.name }}" {{icebergcoldatatype( col.dataType)}}
           {% if col.isSurrogateKey %}
               identity
           {% endif %}
           {%- if not col.nullable %} NOT NULL
               {%- if col.defaultValue | length > 0 %} DEFAULT {{ col.defaultValue }}{% endif %}
           {% endif %}
           {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
           {%- if not loop.last -%}, {% endif %}
          {% endfor %}
           )
          {%if desiredState.config.clusterKey == true%} {{ nsVariables.finalClusterKey }}   {%endif%}


        {%if extvol != '' %} EXTERNAL_VOLUME = '{{extvol}}' {%endif%}
        {%if baseloc != '' %} BASE_LOCATION = '{{baseloc}}'{%endif%}
        {%if catsync != '' and desiredState.config.tcatalog == 'Polaris' %} CATALOG_SYNC = '{{catsync}}' {%endif%}
        CATALOG  =   'SNOWFLAKE'

	    {%- if desiredState.node.description | length > 0 %} COMMENT = '{{ desiredState.node.description | escape }}'	
        {%endif%}  

 {%elif  currentState.node.name == desiredState.node.name and
 currentState.node.location.name == desiredState.node.location.name  and ns.colchangescdt > 0 %}


{% set ns1 = namespace(renamefield = false,element_names1 = [],element_names2 = []) %}


     {% for alterCurCol in currentState.columns %}  
         {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}

                    {% set currentDatatype = alterCurCol.dataType %}
                    {% set desiredColname = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='name') | first %}
                    {% set desiredDatatype = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='dataType') | first %}


        {%if 'OBJECT'  in alterCurCol.dataType or 'MAP'  in alterCurCol.dataType or 'ARRAY'   in alterCurCol.dataType  %} 

            {%if 'ARRAY' not in alterCurCol.dataType %}

                    {%if 'OBJECT'  in alterCurCol.dataType %}
                      {% set elements1 = currentDatatype[7:-1].split(',') %}
                      {% set elements2 = desiredDatatype[7:-1].split(',') %}
                    {%elif 'MAP'  in alterCurCol.dataType %}
                      {% set elements1 = currentDatatype[4:-1].split(',') %}
                      {% set elements2 = desiredDatatype[4:-1].split(',') %}
                    {%endif%}


                    {% for element in elements1 %}
                       {% set element_name = element.split()[0] %}
                       {% set ns1.element_names1 = ns1.element_names1 + [element_name] %}
                    {% endfor %}


                    {% for element in elements2 %}
                        {% set element_name = element.split()[0] %}
                        {% set ns1.element_names2 = ns1.element_names2 + [element_name] %}
                    {% endfor %} 

                     {%set ele1 = ns1.element_names1|count %}
                     {%set ele2 = ns1.element_names2|count %}
                    {%if ele1 == ele2 %}
                    {% for name1 in ns1.element_names1 %}
                      {% if name1 not in ns1.element_names2%}

                        {%set  ns1.renamefield = true %}
                      {% endif %}
                    {% endfor %}
                    {%endif%}
            {%endif%}


                    {%if ns1.renamefield == true %}

					    {{ stage('Alter structured data type in Iceberg Table') }}

                        ALTER ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}ALTER COLUMN {{ desiredColname }} SET DATA TYPE {{ desiredDatatype }} RENAME FIELDS
                    {%else%}

                        {{ stage('Alter structured data type in Iceberg Table') }}

                        ALTER ICEBERG TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}ALTER COLUMN {{ desiredColname }} SET DATA TYPE {{ desiredDatatype }}
                    {%endif%}


                {% endif %}                   
         {% endif %}
      {% endfor %}



 {%endif%} 


{%elif  currentState != undefined and desiredState == undefined%}

    {# Table or View Name #}
    {% set targetObjectDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetObjectSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetObjectName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

        {{ stage('Drop iceberg table') }}
         DROP ICEBERG TABLE IF EXISTS {{ fullyQualifiedTargetObjectName }}

{%endif%}


{# Historical load and create pipe #}

{% if desiredState %}

  {% set srcSchName = desiredState.node.location.name %}
     {% set db = desiredState.storageLocations | selectattr('name', 'equalto', srcSchName) | map(attribute='database') | first %}
     {% set sch = desiredState.storageLocations | selectattr('name', 'equalto', srcSchName) | map(attribute='schema') | first %}
     {% set tbl = desiredState.node.name %}
     {% set fqTblName = '"' + db + '"."' + sch + '"."' + tbl + '"' %}
     {% set fqPipeName = '"' + db + '"."' + sch + '"."' + tbl + '_PIPE"' %}

     {% set stageStorageLocationName = desiredState.config.stageStorageLocationName %}
     {% set dbStage = desiredState.storageLocations | selectattr('name', 'equalto', stageStorageLocationName) | map(attribute='database') | first %}
     {% set schStage = desiredState.storageLocations | selectattr('name', 'equalto', stageStorageLocationName) | map(attribute='schema') | first %}
     {% set ns = namespace(counter=1) %}

	  {%- if desiredState.config.filePattern | length > 0 -%} 
        {%- set filePatternSQL = 'PATTERN = ' + desiredState.config.filePattern -%} 
      {%- else -%}
        {%- set filePatternSQL = "" -%} 
     {%- endif -%}

     {%- if desiredState.config.fileNames | length > 0 %} 
       {% set fileNameSQL = 'FILES = (' + desiredState.config.fileNames + ')' %} 
     {%- else -%}
       {% set fileNameSQL = "" %} 
     {% endif %}

	 {% set fileFormatLocationName = desiredState.config.fileFormatLoc %}
     {% set dbff = desiredState.storageLocations | selectattr('name', 'equalto',fileFormatLocationName) | map(attribute='database') | first %}
     {% set schff = desiredState.storageLocations | selectattr('name', 'equalto',fileFormatLocationName) | map(attribute='schema') | first %}

   {%if currentState == undefined or (currentState != undefined and desiredState!=currentState) %} 

        {%if  desiredState.config.flagSnowpipe != 'Test Copy Statement'%}                   

                {%if desiredState.config.flagLoadHistorical == true%}

                        {%- if desiredState.parameters.loadType == 'Reload' -%}

                            {{ stage('Truncate Target Table') }}
                            TRUNCATE TABLE IF EXISTS "{{ db }}"."{{ sch }}"."{{ desiredState.node.name }}"

                            {{ stage('Historical Reload-Using Copy-into') }}
                       {%else %}

                            {{ stage('Historical Full Load-Using Copy-into') }}

                        {%endif%}

                 COPY INTO "{{ db }}"."{{ sch }}"."{{ desiredState.node.name }}" (
                   {%- for col in desiredState.columns %}
                   "{{ col.name }}"
                   {%- if not loop.last -%}, {% endif %}
                   {%- endfor %}
                   )
                 FROM (SELECT

