    {% if desiredState.parameters.targetDynamicTableWarehouse == 'DEV ENVIRONMENT' %}
        {% set dynamicTableWarehouse = desiredState.config.warehouseName %}
    {% else %}
        {% set dynamicTableWarehouse = desiredState.parameters.targetDynamicTableWarehouse %}
    {% endif %}

    {# Desired target node mappings #}
    {% set desiredDatabase = desiredState.storageLocations
                            | selectattr('name', 'equalto', desiredState.node.location.name)
                            | map(attribute='database')
                            | first %}
    {% set desiredSchema = desiredState.storageLocations
                            | selectattr('name', 'equalto', desiredState.node.location.name)
                            | map(attribute='schema')
                            | first %}
    {% set desiredDatabaseSchema = desiredDatabase + '.' + desiredSchema %}

    {# Desired Downstream Option or Lag Specification #}
    {% if desiredState.config.tgtLagSpecification == 'DOWNSTREAM' %}
        {% set dynamicTableLagSpecification = 'DOWNSTREAM' %}
    {% else %}
        {% set dynamicTableLagValue = desiredState.config.lagSpecification.get('items')
                                    | map(attribute='lagValue')
                                    | first %}
        {% set dynamicTableLagValuePeriod = desiredState.config.lagSpecification.get('items')
                                    | map(attribute='lagPeriod')
                                    | first %}

        {% set dynamicTableLagSpecification = dynamicTableLagValue ~ ' ' ~ dynamicTableLagValuePeriod %}
    {% endif %}

    {# Node description #}
    {%- if desiredState.node.description | length > 0 %} 
        {% set dynamicTableComment = 'COMMENT = "' + desiredState.node.description | escape + '"' %}
    {% endif %}

    {# Refresh-type option #}
    {%- if desiredState.config.refresh_mode == '' %}
        {% set dynamicTablerefresh = 'INCREMENTAL' %}
    {%- else %}
        {% set dynamicTablerefresh = desiredState.config.refresh_mode %}
    {% endif %}

    {# Initialize option #}
    {% if desiredState.config.initialize == '' %}
        {% set dynamicTableinitialize = 'ON_CREATE' %}
    {% else %}
        {% set dynamicTableinitialize = desiredState.config.initialize %}
    {% endif %}

    {% set dynamicTableexternalVolume = desiredState.config.externalVolume %}   {# External Volume option #}
    {% set dynamicTablebaseLocation = desiredState.config.baseLocation %}       {# Base Location option #}

    {# Identify all config changes that would cause a CREATE or ALTER #}
    {% if currentState != undefined and currentState != desiredState %} 

        {# --------------------------------------------------------------------------- #}
        {# ---------- Identify all config changes that would cause a CREATE ---------- #}
        {# --------------------------------------------------------------------------- #}

	    {# Desired Namespace Variables #}
        {% set nsVariables = namespace( storageLocationTest = true,
                                        descolchanges = 0,
                                        acolchanges = 0,
                                        dcolchanges = 0,
                                        othercolchanges = 0,
                                        joinTest = true ) %}

        {% set sourcesTest = currentState.sources | count == desiredState.sources | count %}

        {% if sourcesTest == true %}
          {% for src in desiredState.sources %}
            {% if  currentState.sources[loop.index0].join != src.join %}
                {# Set joinTest to false if changes are detected #}
                {% set nsVariables.joinTest = false %}  
            {% endif %}
           {% endfor %}
        {% endif %}

        {# Desired Namespace Variables Transform #}
        {% set desiredTransformArray = desiredState.sources
                                        | map(attribute='columns')
                                        | first
                                        | map(attribute='transform')
                                        | list -%}

        {# Current Namespace Variables Transform #}
        {% set currentTransformArray = currentState.sources
                                        | map(attribute='columns')
                                        | first
                                        | map(attribute='transform')
                                        | list -%}

        {# Test to see if the transform in a column has changed #}
        {% set columnsTransformTest = currentTransformArray == desiredTransformArray %}

        {# Config #}
        {% set partitionByTest = currentState.config.partitionBy | default({'items': [{}]}) == desiredState.config.partitionBy %}
        {% set orderByTest = currentState.config.orderBy | default({'items': [{}]}) == desiredState.config.orderBy %}
        {% set orderByDateTimeTest = currentState.config.orderByDateTime | default({'items': [{}]}) == desiredState.config.orderByDateTime %}
        {% set recordVersioningTest = currentState.config.recordVersioning | default('') == desiredState.config.recordVersioning %}
        {% set granttest = currentState.config.cpygrants | default(false) == desiredState.config.cpygrants%}
        {% set refreshTest = currentState.config.refresh_mode | default('') == desiredState.config.refresh_mode %}
        {% set initializeTest = currentState.config.initialize | default('') == desiredState.config.initialize %}
        {% set externalVolumeTest = currentState.config.externalVolume | default('') == desiredState.config.externalVolume %}
        {% set baseLocationTest = currentState.config.baseLocation | default('') == desiredState.config.baseLocation %}
        {% set materializationTest = currentState.node.materializationType == desiredState.node.materializationType %}

        {# Column description changes and other column level changes #}
        {% for alterCurCol in currentState.columns %}        
            {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}
                {% set currentColumnName = alterCurCol.name %}
                {% set desiredColumnName = desiredState.columns 
                                            | selectattr('id', "equalto", alterCurCol.id) 
                                            | map(attribute='name') 
                                            | first %}                                          

                {% set currentDatatype = icebergcoldatatype(alterCurCol.dataType) %}
                {% set desiredDatatype = icebergcoldatatype(desiredState.columns 
                                            | selectattr('id', "equalto", alterCurCol.id) 
                                            | map(attribute='dataType') 
                                            | first) %}                                            
                {# -- No changes for dynamic iceberg as of now------------------------
                {% set currentNullable = alterCurCol.nullable %}
                {% set desiredNullable = desiredState.columns 
                                            | selectattr('id', "equalto", alterCurCol.id) 
                                            | map(attribute='nullable') 
                                            | first %}

                {% set currentDefaultValue = alterCurCol.defaultValue %}
                {% set desiredDefaultValue = desiredState.columns 
                                            | selectattr('id', "equalto", alterCurCol.id) 
                                            | map(attribute='defaultValue') 
                                            | first %}
                ---------------------------------------------------------------------#}

                {% set currentDescription = alterCurCol.description %}
                {% set desiredDescription = desiredState.columns 
                                            | selectattr('id', "equalto", alterCurCol.id) 
                                            | map(attribute='description') 
                                            | first %}

                {% set datatypeTest = currentDatatype == desiredDatatype %}                
                {% set descriptionTest = currentDescription == desiredDescription %}
                {% set columnnameTest = currentColumnName == desiredColumnName %}

                {% if (descriptionTest == false) %}
                    {% set nsVariables.descolchanges = nsVariables.descolchanges + 1 %}
                {% endif %}

                {% if datatypeTest == false or defaultValueTest == false or columnnameTest == false %}
                    {% set nsVariables.othercolchanges = nsVariables.othercolchanges + 1 %}
                {% endif %}

            {% else %}
                {# Dropped Columns #}
                {% set nsVariables.dcolchanges = nsVariables.dcolchanges + 1 %}
            {%endif%}  
        {% endfor %}

        {# Added Columns #}
        {% for addDesCol in desiredState.columns %}
            {% if addDesCol.id not in currentState.columns | map(attribute="id") %}
                {% set nsVariables.acolchanges = nsVariables.acolchanges + 1 %}
            {%endif%}
        {% endfor %}

        {# Change Node Name or Change Storage Location #}
        {%if currentState.storageLocations | length == 0%}          
            {% set currentDatabase = currentState.storageLocations 
                                    | selectattr('name', 'equalto', currentState.node.location.name)
                                    | map(attribute='database')
                                    | string %}
            {% set currentSchema = currentState.storageLocations
                                    | selectattr('name', 'equalto', currentState.node.location.name)
                                    | map(attribute='schema')
                                    | string %}
            {% set currentDatabaseSchema = currentDatabase + '.' + currentSchema %}

        {%else %}  

            {# Current target node mappings #}
            {% set currentDatabase = currentState.storageLocations
                                    | selectattr('name', 'equalto', currentState.node.location.name)
                                    | map(attribute='database')
                                    | first %}
            {% set currentSchema = currentState.storageLocations 
                                    | selectattr('name', 'equalto', currentState.node.location.name)
                                    | map(attribute='schema')
                                    | first %}
            {% set currentDatabaseSchema = currentDatabase + '.' + currentSchema %}  
        {% endif %}

        {# If any of the above are false then a CREATE must be run #}
        {% if nsVariables.othercolchanges       > 0
            or sourcesTest                      == false
            or nsVariables.joinTest             == false
            or columnsTransformTest             == false
			or partitionByTest                  == false 
            or orderByTest                      == false 
            or orderByDateTimeTest              == false 
            or recordVersioningTest             == false   
            or initializeTest                   == false
            or granttest                        == false
            or refreshTest                      == false
            or externalVolumeTest               == false
            or baseLocationTest                 == false
            or materializationTest              == false
            or nsVariables.acolchanges          > 0
            or nsVariables.dcolchanges          > 0  %}

            {% set createTest = true %}
        {% else %}
            {% set createTest = false %}
        {% endif %}

        {# --------------------------------------------------------------------------- #}
        {# ---------Identify all config changes that would cause an ALTER------------- #}
        {# --------------------------------------------------------------------------- #}

        {#Current Warehouse#}
        {% if currentState.parameters.targetDynamicTableWarehouse == 'DEV ENVIRONMENT' %}
            {% set currentDynamicTableWarehouse = currentState.config.warehouseName | default('') %}
        {% else %}
            {% set currentDynamicTableWarehouse = currentState.parameters.targetDynamicTableWarehouse %}
        {% endif %}

        {% set warehouseTest = dynamicTableWarehouse == currentDynamicTableWarehouse %}

        {% if currentDatabaseSchema != desiredDatabaseSchema %}
            {% set nsVariables.storageLocationTest = false %}
        {% endif %}

        {% set nodeNameTest = currentState.node.name == desiredState.node.name %}

        {% set lagSpecificationTest = currentState.config.tgtLagSpecification | default('') == desiredState.config.tgtLagSpecification %}
        {% if lagSpecificationTest and desiredState.config.tgtLagSpecification == 'TIME BASED' %}
            {% set lagSpecificationTest = desiredState.config.lagSpecification == currentState.config.lagSpecification | default('') %}
        {% endif %}

        {% set nodeCommentTest = currentState.node.description == desiredState.node.description %}

        {# Clustering Test #}
        {% set clusterKeyTest = currentState.config.clusterKey | default(false) == desiredState.config.clusterKey %}
        {% set clusterKeyConfigTest = currentState.config.clusterKeyConfig | default({'items': [{}]}) == desiredState.config.clusterKeyConfig %}

        {% if warehouseTest                     == false
            or lagSpecificationTest             == false
            or nodeCommentTest                  == false
            or clusterKeyTest                   == false
            or clusterKeyConfigTest             == false
            or nsVariables.descolchanges        > 0
            or nsVariables.storageLocationTest  == false
            or nodeNameTest                     == false %}    

            {% set alterOnlyTest = true %}
        {% else %}
            {% set alterOnlyTest = false %}
        {% endif %}
    {% endif %}

    {% if currentState == undefined or createTest %}

        {# --------------------------------------------------------------------------- #}
        {# -------- CREATE table incase of initial deploy or config changes ---------- #}
        {# --------------------------------------------------------------------------- #}

        {# Build Cluster Key #}
        {% set nsVariables = namespace(finalClusterKey="") %}
        {% if desiredState.config.clusterKey %}
            {% set column = desiredState.config.clusterKeyConfig.get('items') 
                            | map(attribute='columnName.name')
                            | list %}

            {%- set nsVariables = namespace(clusterValues=[]) %}

            {% for clustCol in column %}
                {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"' + clustCol + '"'] %}
            {% endfor %}

            {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

        {% endif %}

        {{ stage('Create Dynamic Iceberg Table', true, "sql", "create") }}
        CREATE OR REPLACE DYNAMIC ICEBERG TABLE {{ fullyQualifiedTargetDynamicTableName }}
            {% if desiredState.config.cpygrants %}
                COPY GRANTS
            {% endif %}
            TARGET_LAG = '{{ dynamicTableLagSpecification }}'
            WAREHOUSE = {{ dynamicTableWarehouse }}
            REFRESH_MODE   = {{ dynamicTablerefresh }}
            INITIALIZE = {{ dynamicTableinitialize }}
            {{nsVariables.finalClusterKey }}
            EXTERNAL_VOLUME = {{ dynamicTableexternalVolume }}
            CATALOG = 'SNOWFLAKE'
            BASE_LOCATION = {{ dynamicTablebaseLocation }}
            {{ dynamicTableComment }}
        (
            {% for col in desiredState.columns %}
                "{{ col.name }}" {{ icebergcoldatatype(col.dataType) }}
                {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}' {% endif %}
                {%- if not loop.last -%}, {% endif %}
            {% endfor %}
        )
        AS
        {% for source in desiredState.sources %}
            SELECT
                {% for col in source.columns %}
                    {{ get_source_transform(col) }} AS "{{ col.name }}"
                    {%- if not loop.last -%}, {% endif %}
                {% endfor %}
            {{ source.join }}
        {% endfor %}
        QUALIFY ROW_NUMBER() OVER (PARTITION BY  {{ partition_by() }} ORDER BY {{ order_by_col() }} DESC) = 1

    {% elif currentState != undefined and alterOnlyTest == true %}

        {# --------------------------------------------------------------------------- #}
        {# ------------- ALTER Only config changes and refresh table ----------------- #}
        {# --------------------------------------------------------------------------- #}

        {% set desiredFullyQualifiedTargetDynamicTableName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}
        {% set currentFullyQualifiedTargetDynamicTableName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

        {% if warehouseTest == false
                or lagSpecificationTest == false
                or nodeCommentTest == false %}

            {{ stage('Alter Dynamic Iceberg Table') }}
            ALTER DYNAMIC TABLE {{ desiredFullyQualifiedTargetDynamicTableName }}
            SET
                {% if warehouseTest == false %}
            WAREHOUSE = {{ dynamicTableWarehouse }}
                {% endif %}
                {% if  lagSpecificationTest == false %}
            TARGET_LAG = '{{ dynamicTableLagSpecification }}'
                {% endif %}
                {% if nodeCommentTest == false %}
            {{ dynamicTableComment }}
                {% endif %}

        {% endif %}

        {# Change in storage mappings, target location or node name #}
        {% if nsVariables.storageLocationTest == false or nodeNameTest == false  %}
            {{ stage('Rename Dynamic Iceberg Table') }}
            {% set srcSchName = currentState.node.location.name %}
            {% set cdb = currentState.storageLocations
                        | selectattr('name', 'equalto', srcSchName)
                        | map(attribute='database')
                        | first %}
            {% set csch = currentState.storageLocations
                        | selectattr('name', 'equalto', srcSchName)
                        | map(attribute='schema')
                        | first %}
            ALTER DYNAMIC TABLE IF EXISTS  "{{cdb}}"."{{csch}}"."{{currentState.node.name}}"
            RENAME TO {{ desiredFullyQualifiedTargetDynamicTableName }}
        {% endif %}

        {# Change in column description #}
        {% if nsVariables.descolchanges > 0 %}
            {% for alterCurCol in currentState.columns %}        
                {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}
                    {% set currentDescription = alterCurCol.description %}

                    {% set desiredColumnName = desiredState.columns
                                                | selectattr('id', "equalto", alterCurCol.id)
                                                | map(attribute='name')
                                                | first %}
                    {% set desiredDescription = desiredState.columns
                                                | selectattr('id', "equalto", alterCurCol.id)
                                                | map(attribute='description')
                                                | first %}

                    {% set descriptionTest = currentDescription == desiredDescription %}

                    {% if descriptionTest == false %}
                        {{ stage('Alter Dynamic Iceberg Table-Modify Column') }}
                        ALTER DYNAMIC TABLE {{ desiredFullyQualifiedTargetDynamicTableName }}
                        MODIFY COLUMN {{desiredColumnName}}
                        COMMENT '{{desiredDescription }}'
                    {% endif %}
                {% endif %}
            {% endfor %}
        {% endif %}

        {# Figure out cluster key changes #}
        {% set nsVariables = namespace(finalClusterKey = "", clusterValues = []) %}
        {% if clusterKeyTest == false or clusterKeyConfigTest == false %}
            {% if desiredState.config.clusterKey == true %}
                {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}

                {% for clustCol in column %}
                    {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"' + clustCol + '"']%}
                {% endfor %}

                {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

            {% else %}

                {% set nsVariables.finalClusterKey = 'DROP CLUSTERING KEY' %}

            {% endif %}

            {{ stage('Recluster Dynamic Iceberg Table') }}
            ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
            {{ nsVariables.finalClusterKey }}

        {% endif %}

        {{ stage('Refresh Dynamic Iceberg Table') }}
        ALTER DYNAMIC TABLE {{ desiredFullyQualifiedTargetDynamicTableName }}
        REFRESH

    {% endif %}

{% elif currentState != undefined and desiredState == undefined %}

    {# Dynamic Table Name #}
    {% set targetDynamicTableDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetDynamicTableSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetDynamicTableName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

    {{ stage('Drop Dynamic Iceberg Table') }}
    {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
    DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

{% endif %}

contents.macros:
{# ----------------------------------------------------------------------
  Macro: colcict
  Purpose: Builds a dictionary (ns.column_dict) of columns for all sources
---------------------------------------------------------------------- #}
{% macro colcict(ns) %}
  {% if sources is defined %}
    {% for source_idx in range(sources | length) %}
      {% set source = sources[source_idx] %}

      {# Initialize the source entry if missing #}
      {% if source_idx not in ns.column_dict %}
        {% set _ = ns.column_dict.update({source_idx: {}}) %}
      {% endif %}

      {# Add all columns in this source to the dictionary #}
      {% for column in source.columns %}
        {% set _ = ns.column_dict[source_idx].update({column.id: column}) %}
      {% endfor %}
    {% endfor %}
  {% endif %}
{% endmacro %}


{#--------------------------------------------------------
  Initialize variables for node types that use the 
  advanced deployment strategy
----------------------------------------------------------#}

{% if desiredState %}
    {% set columns = desiredState.columns %}
    {% set storageLocations = desiredState.storageLocations %}
    {% set config = desiredState.config %}
    {% set sources = desiredState.sources %}
    {% set node = desiredState.node %}
    {% set parameters = desiredState.parameters %}

    {% set ns = namespace(column_dict = {}) %}
    {# Populate column dictionary #}
    {{ colcict(ns) }}

{% endif %}



{# ---------------------------------------------------------------------- 
  Macro: partition_by
  Purpose: Builds a partition key string for a node.
           - Uses '~' delimiter for DIM nodes, ',' otherwise.
           - Concatenates partitionBy config columns with proper transforms.
---------------------------------------------------------------------- #}
{% macro partition_by(nodetype) %}

  {# Create namespaces #}
  {% set nsVars = namespace(partition = "", delim = "") %}


  {# Choose delimiter based on node type #}
  {% if nodetype == 'DIM' %}
    {% set nsVars.delim = '~' %}
  {% else %}
    {% set nsVars.delim = ',' %}
  {% endif %}

  {# Build partition expression #}
  {% if config is defined and config.partitionBy is defined %}
    {% for item in config.partitionBy.get('items', []) %}

      {% set part_col = ns.column_dict[0][item.partColName.id] %}

      {%- if loop.first -%}
            {%- set nsVars.partition = get_source_transform(part_col) -%}
        {%- else -%}
            {%- set nsVars.partition = nsVars.partition + nsVars.delim + get_source_transform(part_col) -%}
        {%- endif -%}
    {% endfor %}
  {% endif %}

  {{ nsVars.partition }}
{% endmacro %}


{% macro order_by_col(return) %}

    {% set nsVariables = namespace(orderBy="") -%}

    {% if config.recordVersioning in ('Datetime Column') -%}

        {% set datetimeColSort = config.orderBy.get('items',[]) -%}		
        {% set dateTimeCol = ns.column_dict[0][datetimeColSort[0].colName.id] -%}        
        {% set nsVariables.orderBy = get_source_transform(dateTimeCol) -%}

	{% elif config.recordVersioning in ('Integer Column')%}

        {% set datetimeNumericColSort = config.orderseq.get('items',[]) -%}
	    {% set dateTimeCol = ns.column_dict[0][datetimeNumericColSort[0].colNameseq.id] -%}        
        {% set nsVariables.orderBy = get_source_transform(dateTimeCol) -%}

    {% else -%}
        {% set dateTimeColSort = config.orderByDateTime.get('items',[]) -%}
        {% set dateCol = ns.column_dict[0][dateTimeColSort[0].colNameDate.id] -%}
        {% set timeCol = ns.column_dict[0][dateTimeColSort[0].colNameTimestamp.id] -%}
        {% set nsVariables.orderBy = 'to_timestamp(' + get_source_transform(dateCol) +  '|| ' + '\'T\'' + ' ||' + get_source_transform(timeCol) +  ')' -%}

    {% endif -%}

    {{ nsVariables.orderBy }}

{% endmacro %}

{% macro order_by_col_int(return) %}

    {% set nsVariables = namespace(orderBy="") -%}

      {% set datetimeNumericColSort = config.recordorderBy.get('items',[]) %}
	  {% set dateTimeCol = ns.column_dict[0][datetimeNumericColSort[0].ocolName.id] -%}    
      {% set nsVariables.orderBy = get_source_transform(dateTimeCol) -%} 

    {{ nsVariables.orderBy }}

{% endmacro %}

{% macro dimensionHistoryPk() %}

    {%- set nsVariables = namespace(dimensionHistoryColumns="") -%}

    {%- set partitionBy = partition_by('DIM').split("~") -%}
    {%- set orderBy = order_by_col() -%}

    {%- for col in partitionBy -%}
        {%- if loop.first -%}
            {%- set nsVariables.dimensionHistoryColumns = col -%}
        {%- else -%}
            {%- set nsVariables.dimensionHistoryColumns = nsVariables.dimensionHistoryColumns + ' || ' + '\'-\'' + ' ||' + col -%}
        {%- endif -%}
    {%- endfor -%}

    {%if config.recordVersioning not in ('Integer Column')%}
        {%- set nsVariables.dimensionHistoryColumns = nsVariables.dimensionHistoryColumns + ' || ' + '\'-\'' + ' || date_part(epoch_milliseconds, ' + orderBy + ')' -%}
    {%else%}
        {%- set nsVariables.dimensionHistoryColumns =  nsVariables.dimensionHistoryColumns ~ " || '-' || " ~ orderBy -%}
        {%- set nsVariables.dimensionHistoryColumns = "MD5(" ~ nsVariables.dimensionHistoryColumns ~")" -%}
    {%endif%}

    {{- nsVariables.dimensionHistoryColumns -}}

{% endmacro %}

{########################################################################################### 

Purpose: Determines the correct Snowflake DROP object syntax based on the materialization type. 
Input: materialization (string): The Snowflake object type to be dropped 

  (e.g., table, view, materialized view, dynamic table, external table). 



Returns: string: The appropriate DROP object keyword with IF EXISTS 

  (e.g., 'table IF EXISTS', 'view IF EXISTS', 'materialized view IF EXISTS'). 

#############################################################################################} 

{% macro dropMaterialization(materialization) %} 

    {%- if materialization | lower in ['table', 'transient table','temporary table', 'hybrid table'] -%} 

        TABLE IF EXISTS 

    {%- elif materialization | lower in ['view', 'secure view', 'run view', 'cortex search service'] -%} 

        VIEW IF EXISTS 

    {%- elif materialization | lower in ['dynamic table','transient dynamic table', 'dynamic iceberg table'] -%} 

        DYNAMIC TABLE IF EXISTS 

    {%- elif materialization | lower == 'materialized view' -%} 

        MATERIALIZED VIEW IF EXISTS 

    {%- elif materialization | lower == 'external table' -%} 

        EXTERNAL TABLE IF EXISTS 

    {%- elif materialization | lower == 'iceberg table' -%} 

        ICEBERG TABLE IF EXISTS 

    {%- elif materialization | lower == 'interactive table' -%} 

        INTERACTIVE TABLE IF EXISTS 

    {%- elif materialization | lower == 'stream' -%} 

        STREAM IF EXISTS 

    {%- else -%} 

        TABLE IF EXISTS 

    {%- endif %} 

{% endmacro %} 



{########################################################################################### 

Purpose: Generates SQL-commented warnings or UI notifications when a user attempts to  

change the Node Type or Materialization Type of a node. It identifies  

critical node configurations (Tasks, Streams, Hybrid Views, Cortex, etc.)  

that could lead to data loss or broken dependencies if switched. 



Input: None 



Returns: A string containing a SQL comment warning (starting with '-- ⚠️')  

    and/or triggers a stage-level warning UI notification for critical switches. 

#############################################################################################} 

{% macro getNodeTypeSwitchWarning() %} 

    {%- if currentState.node.nodeType.split(':::')[-1] in ['300', '301'] -%} 

        {# Current Node Type: Deferred Merge Nodes #} 

        -- ⚠️ Warning: This table may be linked to streams and hybrid views. Any required updates/drops must be handled manually. 

    {%- elif currentState.node.nodeType.split(':::')[-1] in ['549', '550', '154', '155'] -%} 

        {# Current Node Type: Root and Resume Tasks Nodes #} 

        -- ⚠️ Warning: These node types are not ideal for switching, as they may act as root or resume tasks. Changing them may disrupt related tasks, cause inconsistencies, or result in data loss. Any required updates/drops must be handled manually. 

    {%- elif currentState.node.materializationType | lower in ['task'] or currentState.node.nodeType.split(':::')[-1] in ['429', '567'] -%} 

        {# Current Node Type: Tasks Related, Insert or Merge with Task, Document AI Nodes#} 

        -- ⚠️ Warning: Tasks or streams are attached to this node. Changing its type may cause task failures, stream inconsistencies, or data loss. Any required updates/drops must be handled manually. 

    {%- elif currentState.node.materializationType | lower in ['stream'] -%} 

        {# Current Node Type: Stream Nodes #} 

        -- ⚠️ Warning: This is a stream node. Changing its type may cause task failures, stream inconsistencies, or data loss. Any required updates/drops must be handled manually. 

    {%- elif currentState.node.materializationType | lower in ['cortex search service'] -%} 

        {# Current Node Type: Cortex Nodes #} 

        -- ⚠️ Warning: Cortex search service is attached to this node. Changing its type may cause service failures, inconsistencies, or data loss. Any required updates/drops must be handled manually. 
    {%- elif currentState.node.nodeType.split(':::')[-1] in ['416', '448'] -%}

        {# Current Node Type: Data Quality related statis table/view #}

        -- ⚠️ Warning: This node is used for data quality checks and may not represent the final static schema. Deployment or execution could fail or interrupt email notifications.

    {%- endif %} 

{% endmacro %} 


{# ---------------------------------------------------------------------- 
  Macro: resolveWarehouseFromSize
  Purpose: Used to create a bridge between the selected warehouse sizes,
            parameters and the actual warehouses
---------------------------------------------------------------------- #}

{% macro resolveWarehouseFromSize(size) %}
    {% if not size %}
        {{ '' }}
    {% else %}
        {% set normalizedSize = size
            | lower
            | replace('-', '')
            | replace(' ', '') %}

        {% set sizeToParam = {
            'xsmall': 'xsDynamicTableWarehouse',
            'small': 'sDynamicTableWarehouse',
            'medium': 'mDynamicTableWarehouse',
            'large': 'lDynamicTableWarehouse',
            'xlarge': 'xlDynamicTableWarehouse',
            '2xlarge': '2xlDynamicTableWarehouse',
            '3xlarge': '3xlDynamicTableWarehouse',
            '4xlarge': '4xlDynamicTableWarehouse',
            '5xlarge': '5xlDynamicTableWarehouse',
            '6xlarge': '6xlDynamicTableWarehouse'
        } %}

        {% set paramKey = sizeToParam.get(normalizedSize) %}
        {{ desiredState.parameters.warehouseSizesDict[paramKey] | default('') }}
    {% endif %}
{% endmacro %}

create.templateString:
{#
    Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : Dynamic Table Work  == #}
{# == Node Type Description    : This node creates and runs dynamic table work.Materialization type and cluster key added with this version == #}

{%if desiredState and currentState != desiredState%}
    {%if not config.advanceWarehouse and (desiredState.parameters == {} or  'targetDynamicTableWarehouse' not in desiredState.parameters or desiredState.parameters.targetDynamicTableWarehouse == '') %}

        {{stage('WARNING')}}

        /*Add parameter targetDynamicTableWarehouse in workspace settings and deployment environment for successful execution of node.
        The default value for the parameter is 'DEV ENVIRONMENT'.
        Refer to documentation for more info */

    {%endif%}
{%endif%}

{% if desiredState  %}
    {%- if currentState != undefined and currentState.node.nodeType != desiredState.node.nodeType %}
        {%- set warningMsg = getNodeTypeSwitchWarning() | default('') %}

        {# Warning display - Node type changes can impact related tasks, streams, or services. #}
        {%- if warningMsg | trim | length > 0 -%}
            {{ stage('Warning! Node Type Switching Detected', false) }}
            {{ warningMsg }}
            select 1=0
        {%- endif -%}
    {%- endif -%}

   {%if  desiredState.node.materializationType == 'transient dynamic table' or  desiredState.node.materializationType == 'dynamic table' %}
        {# Materialization type#}
        {%if  desiredState.node.materializationType == 'transient dynamic table' %}
            {% set keyword = 'TRANSIENT'  %}
        {%endif%}

            {# Advance Warehouse #}
            {% if desiredState.config.advanceWarehouse %}
                {% set refreshWarehouse = resolveWarehouseFromSize(desiredState.config.refreshWarehouseSize) %}
                {% set initializeWarehouse = resolveWarehouseFromSize(desiredState.config.initializeWarehouseSize) %}
            {%  else  %}
                {#Warehouse#}
                {# Can be updated during deployment via a parameter to account for different warehouse names in different deployments#}
                {% if desiredState.parameters.targetDynamicTableWarehouse == 'DEV ENVIRONMENT' %}
                    {% set dynamicTableWarehouse = desiredState.config.warehouseName %}
                {% else %}
                    {% set dynamicTableWarehouse = desiredState.parameters.targetDynamicTableWarehouse %}
                {% endif %}
            {% endif %}

        {# Backfill Source Schema#}
        {% set currentSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %}

        {% if desiredState.config.backfillSourceSchema and desiredState.config.backfillSourceSchema != '' %}
            {% set backfillSchema = desiredState.config.backfillSourceSchema %}
        {% else %}
            {% set backfillSchema = currentSchema %}
        {% endif %}

        {% set backfillTableFQN = backfillSchema ~ '.' ~ desiredState.config.backfillSource %}



        {# Identify all config changes that would cause a CREATE instead of ALTER#}
        {% if currentState != undefined %} 
            {# General metadata #}

            {% set sourcesTest = currentState.sources | count == desiredState.sources | count %}

            {# Desired Namespace Variables #}

            {% set nsVariables = namespace(nsDesiredDepStorageLocations="",nsDesiredSourceStorageLocations="",
            nsDesiredTargetStorageLocations="",
            nsDesiredUsedStorageLocations="",
            storageLocationTest= true,
            descolchanges = 0,
            othercolchanges = 0, joinTest = True ) %}

            {%if sourcesTest == true%}
                {% for src in desiredState.sources %}
                    {% if  currentState.sources[loop.index0].join != src.join %}
                        {% set nsVariables.joinTest = false %}  {# Set joinTest to false if changes are detected #}
                    {% endif %}
                {% endfor %}
            {%endif%}

            {# Test to see if the transform in a column has changed #}
            {# Desired Namespace Variables Transform #}
            {% set desiredTransformArray = desiredState.sources | map(attribute='columns') | first | map(attribute='transform') | list -%}

            {# Test to see if the transform in a column has changed #}
            {# Current Namespace Variables Transform #}
            {% set currentTransformArray = currentState.sources | map(attribute='columns') | first | map(attribute='transform') | list -%}

            {% set columnsTransformTest = currentTransformArray == desiredTransformArray %}

            {# Change Node Name or Change Storage Location #}
            {# Storage Location Tests #}
            {# Test  #}
            {%if currentState.storageLocations|length == 0%}          
                {% set currentDatabase = currentState.storageLocations | selectattr('name', 'equalto', currentState.node.location.name) | map(attribute='database') | string %}
                {% set currentSchema = currentState.storageLocations | selectattr('name', 'equalto', currentState.node.location.name) | map(attribute='schema') | string %}
                {% set currentDatabaseSchema = currentDatabase + '.' + currentSchema %}

            {%else %}   
                {# Current target node mappings #}
                {% set currentDatabase = currentState.storageLocations | selectattr('name', 'equalto', currentState.node.location.name) | map(attribute='database') | first %}
                {% set currentSchema = currentState.storageLocations | selectattr('name', 'equalto', currentState.node.location.name) | map(attribute='schema') | first %}
                {% set currentDatabaseSchema = currentDatabase + '.' + currentSchema %}  
            {% endif %}		 

            {# Desired target node mappings #}
            {% set desiredDatabase = desiredState.storageLocations | selectattr('name', 'equalto', desiredState.node.location.name) | map(attribute='database') | first %}
            {% set desiredSchema = desiredState.storageLocations | selectattr('name', 'equalto', desiredState.node.location.name) | map(attribute='schema') | first %}
            {% set desiredDatabaseSchema = desiredDatabase + '.' + desiredSchema %}           

            {% if currentDatabaseSchema != desiredDatabaseSchema %}
                {% set nsVariables.storageLocationTest = false %}
            {% endif %}

            {# Config #}
            {% set insertStrategyTest = currentState.config.insertStrategy | default('UNION ALL') == desiredState.config.insertStrategy %}
            {% set groupByAllTest = currentState.config.groupByAll | default(false)  == desiredState.config.groupByAll %}
            {% set selectDistinctTest = currentState.config.selectDistinct | default(false)  == desiredState.config.selectDistinct %}

            {# grant config change#}
            {% set granttest = currentState.config.cpygrants | default(false)  == desiredState.config.cpygrants%}

            {# Node#}
            {% set nodeNameTest = currentState.node.name == desiredState.node.name %}
            {% set nodeMaterializationType = currentState.node.materializationType == desiredState.node.materializationType %}
            {% set nodeIsMultisource = currentState.node.isMultisource == desiredState.node.isMultisource %}

            {# Refresh_mode test#}
            {% set refreshTest = currentState.config.refresh_mode | default('') == desiredState.config.refresh_mode %}

            {#Initialize test#}
            {% set initializeTest = currentState.config.initialize | default('') == desiredState.config.initialize %}

            {# Immutability test#}
            {% set immutabilityTest = currentState.config.immutableExpression | default('') == desiredState.config.immutableExpression and currentState.config.immutabilityConstraint | default(false)  == desiredState.config.immutabilityConstraint %}

            {# BackFill Test#}
            {% set backfilltest =
            currentState.config.backfill | default(false)  == desiredState.config.backfill
            and currentState.config.backfillSource | default('') == desiredState.config.backfillSource
            and currentState.config.backfillSourceSchema | default('') == desiredState.config.backfillSourceSchema
            and  currentState.config.timeTravel | default(false)  == desiredState.config.timeTravel
            and currentState.config.timeTraveltype | default('') == desiredState.config.timeTraveltype
            and currentState.config.timeTravelreference | default('') == desiredState.config.timeTravelreference
            and currentState.config.timeTravelvalue | default('') == desiredState.config.timeTravelvalue %}

            {# Column description changes and other column level changes #}
            {% for alterCurCol in currentState.columns %}        
                {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}
                     {% set currentColumnName = currentState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='name') | first %}
                    {% set currentDescription = currentState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='description') | first %}
                    {% set currentDatatype = currentState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='dataType') | first %}
                    {% set currentNullable = currentState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='nullable') | first %}
                    {% set currentDefaultValue = currentState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='defaultValue') | first %}

                    {% set desiredColumnName = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='name') | first %}
                    {% set desiredDescription = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='description') | first %}
                    {% set desiredDatatype = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='dataType') | first %}
                    {% set desiredNullable = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='nullable') | first %}
                    {% set desiredDefaultValue = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='defaultValue') | first %}


                   {% set datatypeTest = currentDatatype == desiredDatatype %}
                   {% set nullableTest = currentNullable == desiredNullable %}
                   {% set defaultValueTest = currentDefaultValue == desiredDefaultValue %}
                   {% set descriptionTest = currentDescription == desiredDescription %}
                   {% set columnnameTest = currentColumnName == desiredColumnName %}

                    {% if (descriptionTest == false) %}
                        {% set nsVariables.descolchanges = nsVariables.descolchanges + 1 %}
                    {%endif%}
			          {# Column nullability is not applicable to Dynamic Table#}
                      {# {%if (datatypeTest == false or nullableTest == false or defaultValueTest == false or columnnameTest == false )%} #}
                      {# {% set nsVariables.othercolchanges = nsVariables.othercolchanges + 1 %} #}
                      {#{% endif %} #}															
                    {%if (datatypeTest == false or defaultValueTest == false or columnnameTest == false )%}
                    {% set nsVariables.othercolchanges = nsVariables.othercolchanges + 1 %}
                    {% endif %}

                {%endif%}    
            {% endfor %}

            {#If any of the above are false then a CREATE must be run#}

            {% if 
                nsVariables.othercolchanges > 0 or
                sourcesTest == false or
                nsVariables.joinTest == false or
                columnsTransformTest == false or
                insertStrategyTest == false or 
                groupByAllTest == false or 
                selectDistinctTest == false or 
                nodeIsMultisource == false or 
                initializeTest == false or
                refreshTest == false or
                backfilltest == false or
                granttest == false or 
                (currentState.storageLocations | length ==0)  %}    

                {% set createTest = true %}
            {% else %}
                {% set createTest = false %}
            {% endif %}      

        {% endif %}

        {# Identify config changes that would only result in ALTER #}
        {% if createTest == false %}
            {% if desiredState.parameters.targetDynamicTableWarehouse == 'DEV ENVIRONMENT' %}
                {% set warehouseTest = currentState.config.warehouseName | default('dev_wh_xs') == desiredState.config.warehouseName %}
            {% else %}
                {% set warehouseTest = currentState.parameters.targetDynamicTableWarehouse == desiredState.parameters.targetDynamicTableWarehouse %}
            {% endif %}
            {% set lagSpecificationTest = currentState.config.lagSpecification == desiredState.config.lagSpecification %}
            {% set downstreamOptionTest = currentState.config.downstreamOption | default(false)  == desiredState.config.downstreamOption %}
            {% set nodeCommentTest = currentState.node.description == desiredState.node.description %}

            {# Advance Warehouse Test #}
            {%set advanceWarehouseTest = currentState.config.advanceWarehouse | default(false)  == desiredState.config.advanceWarehouse%}
            {%set refreshWarehouseTest = currentState.config.refreshWarehouseSize | default('') == desiredState.config.refreshWarehouseSize %}
            {% set initializeWarehouseTest = currentState.config.initializeWarehouseSize | default('') == desiredState.config.initializeWarehouseSize %}

            {# Clustering Test #}
            {% set clusterKeyTest = currentState.config.clusterKey | default(false)  == desiredState.config.clusterKey %}
            {% set clusterKeyExpressionsTest = currentState.config.clusterKeyExpressions | default(false)  == desiredState.config.clusterKeyExpressions %}
            {% set clusterKeyConfigTest = currentState.config.clusterKeyConfig | default({'items': [{}]}) == desiredState.config.clusterKeyConfig %}
            {% set clusterKeyConfigExpressionsTest = currentState.config.clusterKeyConfigExpressions | default({'items': [{}]}) == desiredState.config.clusterKeyConfigExpressions %}

            {% if 
                clusterKeyTest == false or
                clusterKeyExpressionsTest == false or
                clusterKeyConfigTest == false or
                clusterKeyConfigExpressionsTest == false %}

                {% set clusterTest = false %}
            {% else %}
                {% set clusterTest = true %}
            {% endif %}

            {% if 
                warehouseTest == false or
                refreshWarehouseTest == false or
                initializeWarehouseTest == false or
                advanceWarehouseTest ==  false or 
                lagSpecificationTest == false or
                downstreamOptionTest == false or
                nodeCommentTest == false or
                clusterTest == false or 
                immutabilityTest == false or 
                nsVariables.descolchanges > 0 or
                nsVariables.storageLocationTest == false or 
                nodeNameTest == false %}    

                {% set alterOnlyTest = true %}
            {% else %}
                {% set alterOnlyTest = false %}
            {% endif %}
        {% endif %}

        {#CREATE or ALTER#}
        {% if (currentState == undefined) or (createTest == true and desiredState.node.materializationType == currentState.node.materializationType) %}      

            {# Materialization type #}
            {%if  desiredState.node.materializationType == 'transient dynamic table' %}
                {% set keyword = 'TRANSIENT'  %}
            {%endif%}


            {# Figure out cluster key #}
            {% set nsVariables = namespace(finalClusterKey="") %}
            {% if desiredState.config.clusterKey == true %}
                {% if desiredState.config.clusterKeyExpressions == true %}
                    {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='columnNameExpressions.name') | list, desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='sqlExpression') | list %}

                    {%- set nsVariables = namespace(clusterValues=[]) %}

                    {% for r in column %}
                        {% if expression[loop.index0] == "" or expression[loop.index0] is undefined %}

                            {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}

                        {% else %}

                        {% set nsVariables.clusterValues = nsVariables.clusterValues + [expression[loop.index0]] %}        


                        {% endif %}
                    {% endfor %}

                    {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

                {% else %}

                    {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}

                    {%- set nsVariables = namespace(clusterValues=[]) %}

                    {% for r in column %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"'] %}
                    {% endfor %}

                    {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

                {% endif %}
            {% endif %}


            {%if  desiredState.node.materializationType == 'transient dynamic table' %}
            {% set keyword = 'TRANSIENT'  %}
            {%endif%}


            {#Dynamic Table Name#}
            {% set targetDynamicTableDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %} 
            {% set targetDynamicTableSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %} 
            {% set fullyQualifiedTargetDynamicTableName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}


            {#Downstream Option or Lag Specification#}
            {% if desiredState.config.downstreamOption == true %}
                {% set dynamicTableLagSpecification = 'DOWNSTREAM' %}
            {% else %}
                {% set dynamicTableLagValue = desiredState.config.lagSpecification.get('items') | map(attribute='lagValue') | first %}
                {% set dynamicTableLagValuePeriod = desiredState.config.lagSpecification.get('items') | map(attribute='lagPeriod') | first %}

                {% set dynamicTableLagSpecification = dynamicTableLagValue ~ ' ' ~ dynamicTableLagValuePeriod %}
            {% endif %}

            {# Refresh-type option #}
            {%- if desiredState.config.refresh_mode == '' %}
                {% set dynamicTablerefresh = 'INCREMENTAL' %}
            {%- else %}
                {% set dynamicTablerefresh = desiredState.config.refresh_mode %}
            {% endif %}

            {# Initialize option #}
            {% if desiredState.config.initialize == '' %}
                {% set dynamicTableinitialize = 'ON_CREATE' %}
            {% else %}
                {% set dynamicTableinitialize = desiredState.config.initialize %}
            {% endif %}

            {#Node description#}
            {%- if desiredState.node.description | length > 0 %} 
                {% set dynamicTableComment = "COMMENT = " + "'" + desiredState.node.description |escape + "'" %}
            {% endif %}

            {% if createTest == true and  currentState.node.materializationType != desiredState.node.materializationType %}
                {# Change in materialization type #}
                {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
                {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
                DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

            {% endif %}

            {{ stage('Create Work '+ '{{ desiredState.node.materializationType }}', true, "sql", "create") }}
            CREATE OR REPLACE {{ keyword }} DYNAMIC TABLE {{ fullyQualifiedTargetDynamicTableName }}
                {%if desiredState.config.cpygrants%}COPY GRANTS {%endif%}
                TARGET_LAG = '{{ dynamicTableLagSpecification }}'
                {% if desiredState.config.advanceWarehouse %}
                    WAREHOUSE = {{ refreshWarehouse }}
                    INITIALIZATION_WAREHOUSE = {{ initializeWarehouse }}
                {% else %}
                    WAREHOUSE = {{ dynamicTableWarehouse }}
                {% endif %}
                REFRESH_MODE   = {{dynamicTablerefresh}}
                INITIALIZE = {{dynamicTableinitialize}}
                {% if desiredState.config.immutabilityConstraint
                    and desiredState.config.immutableExpression != '' %}
                    IMMUTABLE WHERE ({{ desiredState.config.immutableExpression }})
                {% endif %} 
                {% if desiredState.config.backfill and not desiredState.config.timeTravel %}
                    BACKFILL FROM {{ backfillTableFQN }}
                {% elif desiredState.config.backfill and desiredState.config.timeTravel %}
                    BACKFILL FROM {{ backfillTableFQN }}
                    {{ desiredState.config.timeTraveltype }}
                    (
                        {{ desiredState.config.timeTravelreference }} => 
                        {% if desiredState.config.timeTravelreference == 'STATEMENT' %}
                            '{{desiredState.config.timeTravelvalue}}'
                        {% else %}
                            {{ desiredState.config.timeTravelvalue }}
                        {% endif %}
                    )
                {% endif %} 
                {{ dynamicTableComment  }}
            (
                {% for col in desiredState.columns %}
                    "{{ col.name }}"{{ col.dataType }}
                    {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
                    {%- if not loop.last -%}, {% endif %}
                {% endfor %}
            )
            AS
            {% for source in desiredState.sources %}
                SELECT {% if desiredState.config.selectDistinct %} DISTINCT {% endif %}
                {% for col in source.columns %}
                    {{ get_source_transform(col) }} AS "{{ col.name }}"
                    {%- if not loop.last -%}, {% endif %}
                {% endfor %}

                {{ source.join }}
                {% if desiredState.config.groupByAll %} GROUP BY ALL {% endif %}

                {% if not loop.last %}
                    {% if desiredState.config.insertStrategy in ['UNION', 'UNION ALL'] %}
                        {{ desiredState.config.insertStrategy }}
                    {% endif %}
                {% endif %}
            {% endfor %}


            {% if desiredState.config.clusterKey == true %}
                {{ stage('Apply Table Clustering', true, "sql", "create") }}
                ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }} {{ nsVariables.finalClusterKey }}

                {{ stage('Resume Recluster Table', true, "sql", "create") }}
                ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }} RESUME RECLUSTER

            {% endif %}

        {% elif (currentState != undefined and desiredState != undefined) and (alterOnlyTest == true and desiredState.node.materializationType == currentState.node.materializationType) %}
            {# Desired Dynamic Table Name#}
            {% set desiredTargetDynamicTableDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %} 
            {% set desiredTargetDynamicTableSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %} 
            {% set desiredFullyQualifiedTargetDynamicTableName = ref(desiredState.node.location.name, desiredState.node.name) %}

            {# Current Dynamic Table Name #}

            {% set currentTargetDynamicTableDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
            {% set currentTargetDynamicTableSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
            {% set currentFullyQualifiedTargetDynamicTableName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

            {# Desired Warehouse #}
            {% if desiredState.parameters.targetDynamicTableWarehouse == 'DEV ENVIRONMENT' %}
                {% set desiredDynamicTableWarehouse = desiredState.config.warehouseName %}
            {% else %}
                {% set desiredDynamicTableWarehouse = desiredState.parameters.targetDynamicTableWarehouse %}
            {% endif %}


            {#Desired Downstream Option or Lag Specification#}
            {% if desiredState.config.downstreamOption == true %}
                {% set desiredDynamicTableLagSpecification = 'DOWNSTREAM' %}
            {% else %}
                {% set desiredDynamicTableLagValue = desiredState.config.lagSpecification.get('items') | map(attribute='lagValue') | first %}
                {% set desiredDynamicTableLagValuePeriod = desiredState.config.lagSpecification.get('items') | map(attribute='lagPeriod') | first %}

                {% set desiredDynamicTableLagSpecification = desiredDynamicTableLagValue ~ ' ' ~ desiredDynamicTableLagValuePeriod %}
            {% endif %}


            {# Current Warehouse#}
            {% if currentState.parameters.targetDynamicTableWarehouse == 'DEV ENVIRONMENT' %}
                {% set currentDynamicTableWarehouse = currentState.config.warehouseName | default('') %}
            {% else %}
                {% set currentDynamicTableWarehouse = currentState.parameters.targetDynamicTableWarehouse %}
            {% endif %}

            {# Current Downstream Option or Lag Specification#}
            {% if currentState.config.downstreamOption | default(false)  == true %}
                {% set currentDynamicTableLagSpecification = 'DOWNSTREAM' %}
            {% else %}
                {% set currentDynamicTableLagValue = currentState.config.lagSpecification.get('items') | map(attribute='lagValue') | first %}
                {% set currentDynamicTableLagValuePeriod = currentState.config.lagSpecification.get('items') | map(attribute='lagPeriod') | first %}

                {% set currentDynamicTableLagSpecification = currentDynamicTableLagValue ~ ' ' ~ currentDynamicTableLagValuePeriod %}
            {% endif %}

            {# Alter for Target lag if necessary #}
            {% set dynamicTableLagSpecification = '' %}
            {% if desiredDynamicTableLagSpecification != currentDynamicTableLagSpecification %}
                {% if desiredDynamicTableLagSpecification == 'DOWNSTREAM' %}
                    {% set dynamicTableLagSpecification = 'TARGET_LAG = DOWNSTREAM' %}
                {% else %}
                    {% set dynamicTableLagSpecification = 'TARGET_LAG = ' + '\'' + desiredDynamicTableLagSpecification + '\'' %}
                {% endif %}
            {% endif %}

            {%- if desiredState.node.description | length > 0 %} 
                {% set dynamicTableComment = "COMMENT = " + "'" + desiredState.node.description |escape + "'" %}
            {% endif %}

            {# Change in storage mappings,target location or node name #}
            {% if nsVariables.storageLocationTest == false or 
             nodeNameTest == false  %}
                {{ stage('Alter Dynamic Table',true,"sql","create") }}
				{% set srcSchName = currentState.node.location.name %}
                {% set cdb = currentState.storageLocations | selectattr('name', 'equalto', srcSchName) | map(attribute='database') | first %}
                {% set csch = currentState.storageLocations | selectattr('name', 'equalto', srcSchName) | map(attribute='schema') | first %}
                  ALTER DYNAMIC TABLE IF EXISTS  "{{cdb}}"."{{csch}}"."{{currentState.node.name}}" RENAME TO {{ desiredFullyQualifiedTargetDynamicTableName }}
            {%endif%}

            {# Figure out cluster key #}
            {% set nsVariables = namespace(finalClusterKey="",clusterValues=[]) %}
            {% if clusterTest == false %}
                {% if desiredState.config.clusterKeyExpressions == true %}
                    {% set column, expression = desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='columnNameExpressions.name') | list, desiredState.config.clusterKeyConfigExpressions.get('items') | map(attribute='sqlExpression') | list %}

                    {% for r in column %}
                        {% if expression[loop.index0] == "" or expression[loop.index0] is undefined%}
                            {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"']%}
                        {% else %}
                            {% set nsVariables.clusterValues = nsVariables.clusterValues +[expression[loop.index0]] %}
                        {% endif %}
                    {% endfor %}

                    {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

                {% elif desiredState.config.clusterKey == true %}

                    {% set column = desiredState.config.clusterKeyConfig.get('items') | map(attribute='columnName.name') | list %}

                    {% for r in column %}
                        {% set nsVariables.clusterValues = nsVariables.clusterValues + ['"'+r+'"']%}
                    {% endfor %}

                    {% set nsVariables.finalClusterKey = 'CLUSTER BY (' + nsVariables.clusterValues | join(',') + ')' %}

                {% else %}

                    {% set nsVariables.finalClusterKey = 'DROP CLUSTERING KEY' %}

                {% endif %}

                {{ stage('Recluster TABLE') }}
                ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                {{ nsVariables.finalClusterKey }}

            {% endif %}

            {# Change in column description #}

            {% for alterCurCol in currentState.columns %}        
                {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}

                    {% set currentDescription = alterCurCol.description %}

                    {% set desiredColumnName = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='name') | first %}
                    {% set desiredDescription = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='description') | first %}

                    {% set descriptionTest = currentDescription == desiredDescription %}

                    {% if (descriptionTest == false) %}
                    {{ stage('Alter Dynamic Table') }}
                       ALTER DYNAMIC TABLE {{ desiredFullyQualifiedTargetDynamicTableName }} MODIFY COLUMN {{desiredColumnName}} COMMENT '{{desiredDescription | escape }}'
                    {% endif %}

                {%endif%}    
            {% endfor %}

            {# Immutability Constranit ON -> OFF #}
            {% if desiredState.config.immutabilityConstraint == false %}
