            {% set currentDynamicTableLagSpecification = currentDynamicTableLagValue ~ ' ' ~ currentDynamicTableLagValuePeriod %}
        {% endif %}

        {# Alter for Target lag if necessary #}
        {% set dynamicTableLagSpecification = '' %}
