      ON "{{ source_node_name }}"."{{ datavault4coalesce.config.snapshot_trigger_column }}" = true
    {%- endif -%}
  {% endfor %}

  {%- for col in sources[0].columns %}

    {%- if 'column' in col.sourceColumns[0].keys() %}
