			{%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
			{%- if not loop.last -%},{% endif %}
		{% endfor %}
	)
	{%- if node.description | length > 0 %} COMMENT = '{{ node.description | escape }}'{% endif %}
	AS

  {%- set loc = storageLocations | selectattr('name', "eq", node.location.name) | list | first -%}
  {%- set target_database = loc.database -%}
  {%- set target_schema = loc.name -%}
  {%- set target_node = node.name -%}

  {# Get the snapshot node information. #}
  {%- set snapshot_tbl = [] -%}

  {%- for col in sources[0].columns -%}    
      {%- if 'is_sdts' in col.keys() %}
              {%- set snapshot_source_node_name = col.sourceColumns[0].node.name -%}
              {%- set snapshot_source_node_schema = col.sourceColumns[0].node.location.name -%}
              {%- if snapshot_source_node_name not in snapshot_tbl -%}
              {%- set _ = snapshot_tbl.append(snapshot_source_node_name) -%}
          {%- endif -%}
      {%- endif -%}
  {%- endfor %}

  {# Collect all reference satellite information. #}

  {%- for col in sources[0].columns -%}

      {%- set source_node_name = col.sourceColumns[0].node.name -%}
      {%- set source_node_schema = col.sourceColumns[0].node.location.name -%}

      {%- if 'column' in col.sourceColumns[0].keys() %}
          {%- if 'is_ref_key' not in col.sourceColumns[0].column.keys() -%}
            {%- if source_node_name not in snapshot_tbl and source_node_name != ns.hub_node_name and source_node_name not in ns.ref_satellites_dict -%}
              {%- set _ = ns.ref_satellites_dict.append(source_node_name) -%}
            {%- endif -%}
          {% else %}
            {%- set ns.hub_node_name = source_node_name -%}
            {%- set ns.hub_node_schema = source_node_schema -%}
          {%- endif -%}
      {%- endif -%}
  {%- endfor %}

  WITH 

  dates AS (

  {% set historized = config.historized -%}

  {% if historized in ['Full', 'Latest'] -%}

    {# This part of the code makes the macro run correctly when we dont have a Snapshot table as part of our Reference Table. The list of dates is based on all|maximum loaddates of all satellites. #}

    {%- set date_column = datavault4coalesce.config.ldts_alias -%}
    {% set clear_list = namespace(clear=False) %}

    {%- for tbl in snapshot_tbl -%}
      {%- if tbl in ns.ref_satellites_dict -%}
        {% set clear_list = True %}
      {%- endif -%}
    {%- endfor -%}

    {%- if clear_list -%}
        {% set snapshot_tbl = [] %}
    {% endif %}

    {% if historized == 'Full' -%}
      SELECT distinct {{ date_column }} FROM (
    {% elif historized == 'Latest' -%}
      SELECT MAX({{ date_column }}) as {{ date_column }} FROM (
    {%- endif -%}

    {% for satellite in ns.ref_satellites_dict -%}
      SELECT  
          {{ date_column }}
      FROM {{ ref_no_link(node.location.name, satellite) }}
      WHERE {{ date_column }} != {{ datavault4coalesce__string_to_timestamp(datavault4coalesce.config.timestamp_format, datavault4coalesce.config.end_of_all_times) }}
      {% if not loop.last -%} UNION {% endif %}
    {%- endfor %}

    )

  {% elif historized in ['Snapshot-based'] %}

    {# For snapshot-based reference tables, the active snapshots determine the list of dates. #}

    {%- set date_column = datavault4coalesce.config.sdts_alias -%} 

      {% for snp_tbl in snapshot_tbl -%}
        SELECT 
          {{ date_column }},
          {{ datavault4coalesce.config.snapshot_trigger_column }}
        FROM (
          SELECT 
            {{ datavault4coalesce.config.sdts_alias }},
            {{ datavault4coalesce.config.snapshot_trigger_column }}
          FROM {{ ref_no_link(node.location.name, snp_tbl) }}
          WHERE {{ datavault4coalesce.config.snapshot_trigger_column }}
      {%- endfor %}
          )

  {%- endif %}
  ), 

  records_to_insert AS (
    SELECT

    {% for col in sources[0].columns %}

      {% if 'column' in col.sourceColumns[0].keys() -%}
        {%- if (config.historized == 'Snapshot-based' and col.sourceColumns[0].node.name in snapshot_tbl) or (config.historized != 'Snapshot-based' and col.name == datavault4coalesce.config.ldts_alias) -%}

          {# The sdts column should be selected from the 'ld' CTE. #}

          {%- set source_node_name = 'ld' -%}
          {%- set source_node_schema = col.sourceColumns[0].node.location.name -%}
          {%- set source_column_name = col.sourceColumns[0].column.name -%}
          {%- set target_column_name = col.name -%}
        {% else %}

          {# For all other columns, the source information can be used. #}

          {%- set source_node_name = col.sourceColumns[0].node.name -%}
          {%- set source_node_schema = col.sourceColumns[0].node.location.name -%}
          {%- set source_column_name = col.sourceColumns[0].column.name -%}
          {%- set target_column_name = col.name -%}
        {% endif %}

        {%- if col.sourceColumns[0].column.is_ref_key -%}
          {%- set ns.hub_node_name = source_node_name -%}
          {%- set ns.hub_node_schema = source_node_schema -%}
          COALESCE("{{ source_node_name }}"."{{ target_column_name }}", {{ datavault4coalesce__unknown_key() }}) AS "{{ target_column_name }}"
        {%- elif col.sourceColumns[0].column.is_hk -%}
          COALESCE("{{ source_node_name }}"."{{ source_column_name }}", {{ datavault4coalesce__unknown_key() }}) AS "{{ target_column_name }}"      
        {%- elif source_column_name == datavault4coalesce.config.ldts_alias -%}
          COALESCE("{{ source_node_name }}"."{{ source_column_name }}", {{ datavault4coalesce__string_to_timestamp(datavault4coalesce.config.timestamp_format, datavault4coalesce.config.beginning_of_all_times) }}) AS "{{ target_column_name }}"
        {%- elif col.name == datavault4coalesce.config.sdts_alias -%}
          "{{ source_node_name }}"."{{ target_column_name }}" AS "{{ target_column_name }}"
          {%- set ns.sdts_node_name = col.sourceColumns[0].node.name -%}
        {%- else -%}
          "{{ source_node_name }}"."{{ source_column_name }}" AS "{{ target_column_name }}"
        {%- endif %}

        {%- if not loop.last -%} , {% endif %}
      {%- elif col.is_ref_key -%}
        {{ get_source_transform(col) }} AS "{{ col.name }}",
      {%- endif %}

    {% endfor %}

    FROM {{ ref(ns.hub_node_schema, ns.hub_node_name) }} "{{ ns.hub_node_name }}"

    FULL OUTER JOIN dates "ld" ON 1 = 1  

    {%- set joined_tables = [] -%}
    {%- for col in sources[0].columns %}

      {%- if 'column' in col.sourceColumns[0].keys() %}
        {%- if 'is_ref_key' not in col.sourceColumns[0].column.keys() and not loop.first and col.sourceColumns[0].node.name not in snapshot_tbl and col.sourceColumns[0].node.name != ns.hub_node_name -%}
              {%- set source_node_name = col.sourceColumns[0].node.name -%}
              {%- set source_node_schema = col.sourceColumns[0].node.location.name -%}
              {%- if source_node_name not in joined_tables -%}
                {%- set _ = joined_tables.append(source_node_name) -%}
                {%- set target_node = node.name -%}

                LEFT JOIN {{ ref(source_node_schema, source_node_name) }} "{{ source_node_name }}"
                ON "ld"."{{ date_column }}" BETWEEN "{{ source_node_name }}"."{{ datavault4coalesce.config.ldts_alias }}" AND "{{ source_node_name }}"."{{ datavault4coalesce.config.ledts_alias }}"

                  {%- for ref_key_col in sources[0].columns %}

                    {%- if 'is_ref_key' in ref_key_col.sourceColumns[0].column.keys() and ref_key_col.sourceColumns[0].column.is_ref_key %}
                      AND "{{ ns.hub_node_name }}"."{{ ref_key_col.name}}" = "{{ source_node_name }}"."{{ ref_key_col.name}}"
                    {%- endif -%}
                  {% endfor %}

              {%- endif -%}
          {%- endif -%} 
      {%- endif %}
    {% endfor -%}

    {% if datavault4coalesce.config.include_business_objects_before_appearance == 'false' -%}
      WHERE "{{ ns.hub_node_name }}"."{{ datavault4coalesce.config.ldts_alias }}" <= "ld"."{{ date_column }}"
    {% endif %}

  )


  SELECT * FROM records_to_insert

{% endif %}

run.templateString:
{{ stage('Insert New Rows') }}

{%- set beginning_of_all_times = datavault4coalesce.config.beginning_of_all_times -%}
{%- set end_of_all_times = datavault4coalesce.config.end_of_all_times -%}
{%- set timestamp_format = datavault4coalesce.config.timestamp_format -%}

{%- set ns = namespace(last_cte= "") -%}

{%- set source_relation = ref(sources[0].dependencies[0].node.location.name, sources[0].dependencies[0].node.name) -%}
{%- set tracked_hashkey = (columns | selectattr("tracked_hashkey", "equalto", true) | list | first).name -%}
{%- set disable_hwm = config.disable_hwm -%}
{%- set source_is_single_batch = config.source_is_single_batch -%}


{%- set is_active_alias = datavault4coalesce.config.snapshot_trigger_column -%}
{%- set src_ldts = datavault4coalesce.config.ldts_alias -%}
{%- set src_rsrc = datavault4coalesce.config.rsrc_alias -%}

{% set unknown_value_rsrc = datavault4coalesce.config.default_unknown_rsrc %}


INSERT INTO {{ ref_no_link(node.location.name, node.name) }}

(
  {% for col in sources[0].columns %}
    "{{ col.name }}"{{ "," if not loop.last }}
  {% endfor %}
)

WITH 

{#
    In all cases, the source model is selected, and optionally a HWM is applied. 
#}
source_data AS (

    SELECT
        {{ tracked_hashkey }},
        {{ src_ldts }},
        {{ src_rsrc }}
    FROM {{ source_relation }} src
    WHERE {{ src_ldts }} NOT IN ('{{ beginning_of_all_times }}', '{{ end_of_all_times }}')
    {%- if not disable_hwm %}
    AND src.{{ src_ldts }} > COALESCE((
        SELECT
            MAX({{ src_ldts }})
        FROM {{ this }}
        WHERE {{ src_ldts }} != {{ datavault4coalesce__string_to_timestamp(timestamp_format, end_of_all_times) }}
    ), {{ datavault4coalesce__string_to_timestamp(timestamp_format, beginning_of_all_times) }} )
    {%- endif %}
),

{#
    In all incremental cases, the current status for each hashkey is selected from the existing Effectivity Satellite.
#}
current_status AS (

    SELECT
        {{ tracked_hashkey }},
        {{ is_active_alias }},
        {{ src_rsrc }}
    FROM {{ this }}
    QUALIFY 
        ROW_NUMBER() OVER(PARTITION BY {{ tracked_hashkey }} ORDER BY {{ src_ldts }} DESC) = 1  

),

{#
    This block is for multi-batch processing. 
#}
{% if not source_is_single_batch %}

    {#
        List of all Hashkeys with their date of first appearance in the source model.
    #}
    hashkeys AS (

        SELECT 
            {{ tracked_hashkey }},
            MIN({{ src_ldts }}) as first_appearance
        FROM source_data
        GROUP BY {{ tracked_hashkey }}

    ),

    {#
        Distinct list of load dates in the multi-batch source.
    #}
    load_dates AS (

        SELECT Distinct
            {{ src_ldts }}
        FROM source_data
        
    ),

    {#
        All combinations of hashkeys and loaddates, for loaddates after the first appearance of a hashkey.
    #}
    history AS (

        SELECT 
            hk.{{ tracked_hashkey }},
            ld.{{ src_ldts }}
        FROM hashkeys hk
        CROSS JOIN load_dates ld
        WHERE ld.{{ src_ldts }} >= hk.first_appearance

    ),

    {#
        All theoretical combinations are checked against the actual occurences of hashkeys in each batch / loaddate.
        If a Hashkey is part of a load/batch, is_active_alias is set to 1, because the hashkey was active in that load/batch.
        If a Hashkey is not part of a load/batch, is_active_alias is set to 0, because the hashkey was not active in that load/batch.
    #}
    is_active AS (

        SELECT
            h.{{ tracked_hashkey }},
            h.{{ src_ldts }},
            COALESCE(src.{{ src_rsrc }}, '{{ unknown_value_rsrc }}') AS {{ src_rsrc }},
            CASE 
                WHEN src.{{ tracked_hashkey }} IS NULL THEN 0
                ELSE 1 
            END as {{ is_active_alias }}
        FROM history h
        LEFT JOIN source_data src
            ON src.{{ tracked_hashkey }} = h.{{ tracked_hashkey }}
            AND src.{{ src_ldts }} = h.{{ src_ldts }}

    ),

    {#
        The rows are deduplicated on the is_active_alias, to only include status changes.
    #}
    deduplicated_incoming AS (

        SELECT
            is_active.{{ tracked_hashkey }},
            is_active.{{ src_ldts }},
            is_active.{{ src_rsrc }},
            is_active.{{ is_active_alias }}
        FROM is_active
        QUALIFY 
            CASE 
                WHEN is_active.{{ is_active_alias }} = LAG(is_active.{{ is_active_alias }}) OVER (PARTITION BY {{ tracked_hashkey }} ORDER BY {{ src_ldts }}) THEN FALSE
                ELSE TRUE
            END

    ),

    {% set ns.last_cte = 'deduplicated_incoming' %}

{#
    This block is for single-batch processing
#}
{% else %}

    {#
        In initial loads of single-batch eff sats, every hashkey of the source is set to active.
    #}
    new_hashkeys AS (

        SELECT DISTINCT
            src.{{ tracked_hashkey }},
            src.{{ src_ldts }},
            src.{{ src_rsrc }},
            1 as {{ is_active_alias }}
        FROM source_data src

        {#
            For incremental runs of single-batch eff sats, only hashkeys that are not active right now are set to active. 
            This automatically includes totally new hashkeys, or hashkeys that are currently set to inactive.
        #}
            LEFT JOIN current_status cs
                ON src.{{ tracked_hashkey }} = cs.{{ tracked_hashkey }}
                AND cs.{{ is_active_alias }} = 1
            WHERE cs.{{ tracked_hashkey }} IS NULL

    ),

    {% set ns.last_cte = 'new_hashkeys' %}

{% endif %}

{#
    In all incremental runs, the source needs to be scanned for all currently active hashkeys. 
    If they are no longer present, they will be deactived. 
#}

    {%- if not source_is_single_batch %}
        disappeared_hashkeys AS (

            SELECT DISTINCT 
                cs.{{ tracked_hashkey }},
                ldts.min_ldts as {{ src_ldts }},
                '{{unknown_value_rsrc}}' AS {{ src_rsrc }},
                0 as {{ is_active_alias }}
            FROM current_status cs
            LEFT JOIN (
                SELECT 
                    MIN({{ src_ldts }}) as min_ldts
                FROM deduplicated_incoming) ldts
                ON 1 = 1
            LEFT JOIN deduplicated_incoming src
                ON src.{{ tracked_hashkey }} = cs.{{ tracked_hashkey }}
                AND  src.{{ src_ldts }} = ldts.min_ldts
            WHERE
                cs.{{ is_active_alias }} = 1
                AND src.{{ tracked_hashkey }} IS NULL
                AND ldts.min_ldts IS NOT NULL

        ),
    {% else %}
        disappeared_hashkeys AS (

            SELECT DISTINCT 
                cs.{{ tracked_hashkey }},
                ldts.min_ldts as {{ src_ldts }},
                '{{unknown_value_rsrc}}' AS {{ src_rsrc }},
                0 as {{ is_active_alias }}
            FROM current_status cs
            LEFT JOIN (
                SELECT 
                    MIN({{ src_ldts }}) as min_ldts
                FROM source_data) ldts
                ON 1 = 1
            WHERE NOT EXISTS (
                SELECT 
                    1 
                FROM source_data src
                WHERE src.{{ tracked_hashkey }} = cs.{{ tracked_hashkey }}
            )
            AND cs.{{ is_active_alias }} = 1
            AND ldts.min_ldts IS NOT NULL

        ),
    {% endif %}

records_to_insert AS (

    {#
        This first part of the UNION includes:
            - for single-batch loads: Only is_active_alias = 1, deactivations are handled later
            - for multi-batch loads: Ativation and deactivation inside the multiple loads
    #}
    SELECT
        di.{{ tracked_hashkey }},
        di.{{ src_ldts }},
        di.{{ src_rsrc }},
        di.{{ is_active_alias }}
    FROM {{ ns.last_cte }} di



        {#
            For incremental multi-batch loads, the earliest to-be inserted status is compared to the current status. 
            It will only be inserted if the status changed. 
        #} 
        {%- if not source_is_single_batch %}
            WHERE NOT EXISTS (
                SELECT 1
                FROM current_status
                WHERE current_status.{{ tracked_hashkey}} = di.{{ tracked_hashkey}}
                    AND current_status.{{ is_active_alias }} = di.{{ is_active_alias }}
                    AND di.{{ src_ldts }} = (SELECT MIN({{ src_ldts }}) FROM deduplicated_incoming)
                )
            AND di.{{ src_ldts }} > COALESCE((SELECT MAX({{ src_ldts }}) FROM {{ this }}), {{ datavault4coalesce__string_to_timestamp(timestamp_format, beginning_of_all_times) }} )
        {% endif %}

    {#
        For all incremental loads, the disappeared hashkeys are UNIONed.
    #}
    UNION

    SELECT
        {{ tracked_hashkey }},
        {{ src_ldts }},
        {{ src_rsrc }},
        {{ is_active_alias }}
    FROM disappeared_hashkeys


)

SELECT 

{% for col in columns %}
    {{ col.name }}
    {% if not loop.last %}, {% endif %}

{% endfor %}

FROM records_to_insert ri

WHERE NOT EXISTS (
    SELECT 1
    FROM {{ this }} t
    WHERE t.{{ tracked_hashkey }} = ri.{{ tracked_hashkey }}
        AND t.{{ src_ldts }} = ri.{{ src_ldts }}
)

