#}
{# == Node Type Name           : Document AI == #}
{# == Node Type Description    : This node executes Document AI extraction queries on unstructured documents == #}

{# Parameter Check for Deployment #}
{%if desiredState and currentState != desiredState and desiredState.config.schedulingMode == 'Warehouse Task' %}
     {% if desiredState.parameters == {} or 'targetTaskWarehouse' not in desiredState.parameters or desiredState.parameters.targetTaskWarehouse == ''%}

         {{stage('WARNING')}}

          /*Add parameter targetTaskWarehouse in workspace settings and deployment environment for successful execution of node.
          The default value for the parameter is 'DEV ENVIRONMENT'.
          For more information, refer to the documentation.*/
	{%endif%}
{%endif%}



{% if desiredState %}

    {# Source Object Location and Name #}
	{% set stageStorageLocation =  desiredState.config.stageStorageLocationName | string %}
	{% set stageNameVar =  desiredState.config.stageName | string %}
    {% set refLink = "{{ ref('" + stageStorageLocation + "', '" + stageNameVar +"') }}" %}


    {# Target Stream Location and Name #}
    {% set streamTargetLocationName = desiredState.node.location.name %}
    {% set streamTargetDatabaseName = desiredState.storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='database') | first %}
    {% set streamTargetSchemaName = desiredState.storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='schema') | first %}
    {% set streamName = desiredState.node.name + '_STREAM' %}
    {% set fullyQualifiedStreamName = '"' + streamTargetDatabaseName + '"."' + streamTargetSchemaName + '"."' + streamName + '"' %}

    {# Stream Type #}
    {% if  desiredState.config.sourceType == 'Directory Table' %} 
        {% set streamType = 'STAGE' %}
        {% set streamSourceObjectName = desiredState.config.stageName %}
    {% endif %}

{% endif %}

{# Create Stream first #}
{% if desiredState and desiredState != currentState %}

    {% if currentState == undefined or desiredState.config.redeploymentBehavior == 'Create or Replace' %}
        {{ stage('Create Stream') }}
        CREATE OR REPLACE STREAM {{ ref(streamTargetLocationName, streamName) }}
            ON {{ streamType }} {{ refLink }}

    {% elif currentState != undefined and desiredState.config.redeploymentBehavior == 'Create If Not Exists'%}
        {{ stage('Re-Create Stream at existing offset') }}
        CREATE STREAM IF NOT EXISTS {{ ref(streamTargetLocationName, streamName) }}
            ON {{ streamType }} {{ refLink }}


    {% elif currentState != undefined and desiredState.config.redeploymentBehavior == 'Create At Existing Stream'%}
        {{ stage('Re-Create Stream at existing offset') }}
        CREATE OR REPLACE STREAM {{ ref(streamTargetLocationName, streamName) }}
            ON {{ streamType }} {{ refLink }}

    {% endif %}


{% elif desiredState == undefined and currentState.storageLocations | length > 0 %}

    {# Source Stream Location and Name #}
    {% set streamTargetLocationName = currentState.node.location.name %}
    {% set streamTargetDatabaseName = currentState.storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='database') | first %}
    {% set streamTargetSchemaName = currentState.storageLocations | selectattr('name', 'equalto', streamTargetLocationName) | map(attribute='schema') | first %}
    {% set streamName = currentState.node.name + '_STREAM' %}
    {% set fullyQualifiedStreamName = '"' + streamTargetDatabaseName + '"."' + streamTargetSchemaName + '"."' + streamName %}

    {{ stage('Drop Stream') }}
    DROP STREAM IF EXISTS {{ ref(streamTargetLocationName, streamName) }}

{% endif %}

{% if desiredState %}

    {%- if currentState != undefined and currentState.node.nodeType != desiredState.node.nodeType %}
        {%- set warningMsg = getNodeTypeSwitchWarning() | default('') %}

        {# Warning display - Node type changes can impact related tasks, streams, or services. #}
        {%- if warningMsg | trim | length > 0 -%}
            {{ stage('Warning! Node Type Switching Detected', false) }}
            {{ warningMsg }}
            select 1=0
        {%- endif -%}


    {%- endif -%}


    {% if desiredState.node.materializationType == 'table' or desiredState.node.materializationType == 'transient table'  %}     


        {% if currentState != undefined and (currentState.node.materializationType != desiredState.node.materializationType or currentState.node.nodeType != desiredState.node.nodeType) %}

                {# Change in materialization type #}

                {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
                {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
                DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

                {{ stage('Create'+ ' {{desiredState.node.materializationType}}') }}
               CREATE OR REPLACE {{desiredState.node.materializationType}} {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                (
                {% for col in desiredState.columns %}
                    "{{ col.name }}" {{ col.dataType }}
                    {%- if not col.nullable %} NOT NULL
                        {%- if col.defaultValue | length > 0 %} DEFAULT {{ col.defaultValue }}{% endif %}
                    {% endif %}
                    {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
                    {%- if not loop.last -%}, {% endif %}
                {% endfor %}
                )
               {%- if desiredState.node.description | length > 0 %} COMMENT = '{{ desiredState.node.description | escape }}'{% endif %}


        {% endif %}

        {% if currentState == undefined or currentState.storageLocations|length == 0 %}


            {{ stage('Create '+ ' {{desiredState.node.materializationType}}') }}
                CREATE OR REPLACE {{desiredState.node.materializationType}} {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                (
                    {% for col in desiredState.columns %}
                    "{{ col.name }}" {{ col.dataType }}
                    {%- if not col.nullable %} NOT NULL
                    {%- if col.defaultValue | length > 0 %} DEFAULT {{ col.defaultValue }}{% endif %}
                    {% endif %}
                    {%- if col.description | length > 0 %} COMMENT '{{ col.description | escape }}'{% endif %}
                    {%- if not loop.last -%}, {% endif %}
                    {% endfor %}
                    )
                {%- if desiredState.node.description | length > 0 %} COMMENT = '{{ desiredState.node.description | escape }}'{% endif %}

        {% elif currentState != undefined and currentState.node.materializationType == desiredState.node.materializationType and currentState.node.nodeType == desiredState.node.nodeType %}

            {# Change Node Name or Change Storage Location #}
            {# Storage Location Tests #}
            {# Only need to account for updated Storage Location mappings   #}

            {# Desired Namespace Variables #}
            {% set nsVariables = namespace(
            colchanges=0,
            storageLocationTest=true) %}


            {# Test  #}
            {% set nsVariables.storageLocationTest = true %}
            {% set nodeCommentTest = currentState.node.description == desiredState.node.description %}

            {#Target location test#}
            {%set currenttargetlocation = currentState.node.location.name %}
            {%set desiredtargetlocation = desiredState.node.location.name %}

                {% set currentDatabase = currentState.storageLocations | selectattr('name', 'equalto', currenttargetlocation) | map(attribute='database') | first %}
                    {% set currentSchema = currentState.storageLocations | selectattr('name', 'equalto', currenttargetlocation) | map(attribute='schema') | first %}
                  {% set currentDatabaseSchema = currentDatabase + '.' + currentSchema %}

                  {# Desired mappings #}
                  {% set desiredDatabase = desiredState.storageLocations | selectattr('name', 'equalto', desiredtargetlocation) | map(attribute='database') | first %}
                  {% set desiredSchema = desiredState.storageLocations | selectattr('name', 'equalto', desiredtargetlocation) | map(attribute='schema') | first %}

                 {% set desiredDatabaseSchema = desiredDatabase + '.' + desiredSchema %}

                {% if currentDatabaseSchema != desiredDatabaseSchema%}
                {% set nsVariables.storageLocationTest = false %}
                 {% endif %}



            {# Rename / Move Object #}
            {% if (nsVariables.storageLocationTest == false or currentState.node.name != desiredState.node.name or currentDatabaseSchema != desiredDatabaseSchema ) %}
                {{ stage('Rename and / or Move Table') }}
                ALTER TABLE {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}
                RENAME TO   {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
            {% endif %}

            {# Change table description #}
            {% if currentState.node.description != desiredState.node.description %}
                {{ stage('Change table description') }}
                ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                SET COMMENT = '{{ desiredState.node.description | escape }}'
            {% endif %}

            {# Drop Columns #}

            {% for dropCurCol in currentState.columns %}
                {% if dropCurCol.id not in desiredState.columns | map(attribute="id") %}
                {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}

                    {% if nsVariables.colchanges == 1 %}
                        {{ stage('Drop Columns') }}
                        ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                        DROP COLUMN 
                    {% else %}
                        , 
                    {% endif %}
                    "{{ dropCurCol.name }}"
                {% endif %}
            {% endfor %}

            {# Add Columns #}

            {% for addDesCol in desiredState.columns %}
                {% if addDesCol.id not in currentState.columns | map(attribute="id") %}
                {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}

                    {% if nsVariables.colchanges == 1 %}
                        {{ stage('Add Columns') }}
                        ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                        ADD COLUMN
                    {% else %}
                        ,
                    {% endif %}
                        "{{ addDesCol.name }}" {{ addDesCol.dataType }}
                        {%- if not addDesCol.nullable %} NOT NULL
                            {%- if addDesCol.defaultValue | length > 0 %} DEFAULT {{ addDesCol.defaultValue }}{% endif %}
                        {% endif %}
                        {%- if addDesCol.description | length > 0 %} COMMENT '{{ addDesCol.description | escape }}'{% endif %}
                {% endif %}
            {% endfor %}

            {# Rename Columns #}
            {% for renameCurCol in currentState.columns %}
                {% if renameCurCol.id in desiredState.columns | map(attribute="id") %}
                    {% set desiredColumnName = desiredState.columns | selectattr('id', 'equalto', renameCurCol.id) | map(attribute='name') | first %}
                    {% if renameCurCol.name != desiredColumnName %}
                        {{ stage('Rename Column ' + renameCurCol.name) }}
                        ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                        RENAME COLUMN "{{ renameCurCol.name }}"
                        TO "{{ desiredColumnName }}"
                    {% endif %}
                {% endif %}
            {% endfor %}

            {# Change data types etc #}
            {% set nsVariables.colchanges = 0 %}
            {% for alterCurCol in currentState.columns %}        
                {% if alterCurCol.id in desiredState.columns | map(attribute="id") %}
                    {% set currentDatatype = alterCurCol.dataType %}
                    {% set currentNullable = alterCurCol.nullable %}
                    {% set currentDefaultValue = alterCurCol.defaultValue %}
                    {% set currentDescription = alterCurCol.description %}

                    {% set desiredColumnName = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='name') | first %}
                    {% set desiredDatatype = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='dataType') | first %}
                    {% set desiredNullable = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='nullable') | first %}
                    {% set desiredDefaultValue = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='defaultValue') | first %}
                    {% set desiredDescription = desiredState.columns | selectattr('id', "equalto", alterCurCol.id) | map(attribute='description') | first %}

                    {% set datatypeTest = currentDatatype == desiredDatatype %}
                    {% set nullableTest = currentNullable == desiredNullable %}
                    {% set defaultValueTest = currentDefaultValue == desiredDefaultValue %}
                    {% set descriptionTest = currentDescription == desiredDescription %}

                    {% if (datatypeTest == false or 
                            nullableTest == false  or
                            defaultValueTest == false or
                            descriptionTest == false) %}
                        {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}

                        {% if nsVariables.colchanges == 1 %}
                            {{ stage('Change Column Attributes') }}
                            ALTER TABLE {{ ref_no_link(desiredState.node.location.name, desiredState.node.name) }}
                            MODIFY
                        {% endif %}
                        {% if datatypeTest == false %}
                            {% if nsVariables.colchanges > 1 %},{% endif %}
                            COLUMN "{{ desiredColumnName }}"
                            SET DATA TYPE {{ desiredDatatype }}
                            {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                        {% endif %}
                        {% if nullableTest == false %}
                            {% if nsVariables.colchanges > 1 %},{% endif %}
                            COLUMN "{{ desiredColumnName }}"
                            {% if currentNullable == true %}
                                SET
                            {% else %}
                                DROP
                            {% endif %}
                            NOT NULL
                            {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                        {% endif %}
                        {% if descriptionTest == false %}
                            {% if nsVariables.colchanges > 1 %},{% endif %}
                            COLUMN "{{ desiredColumnName }}"
                            COMMENT '{{ desiredDescription |escape }}'
                            {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                        {% endif %}
                        {% if defaultValueTest == false %}
                            {% if nsVariables.colchanges > 1 %},{% endif %}
                            COLUMN "{{ desiredColumnName }}"
                            {% if desiredDefaultValue == '' %}
                                DROP DEFAULT
                            {% else %}
                                SET DEFAULT {{ desiredDefaultValue }}
                            {% endif %}
                            {% set nsVariables.colchanges = nsVariables.colchanges + 1 %}
                        {% endif %}

                    {% else %}

                    {% endif %}
                {% endif %}
            {% endfor %}            
        {% endif %}
    {% endif %}

{% elif currentState != undefined and desiredState == undefined %}

    {# Table or View Name #}
    {% set targetObjectDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetObjectSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetObjectName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

        {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
        {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
        DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

{% endif %}

{# Create Task Third #}
{% if desiredState and desiredState != currentState %}

        {% if desiredState.config.devMode == false %}

            {# Set Namespace Variables #}
            {% set nsVariables = namespace(taskWhenRun="") %}
            {% set nsVariables = namespace(poll="WHEN ") %}

            {# Target Table Info #}
    {% set targetTableDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %}
    {% set targetTableSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %}
    {% set fullyQualifiedTargetTableName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}

     {# Internal or External Stage locations#}
   {% set stageStorageLocationName = desiredState.config.stageStorageLocationName %}
   {% set dbStage = desiredState.storageLocations | selectattr('name', 'equalto', stageStorageLocationName) | map(attribute='database') | first %}
   {% set schStage = desiredState.storageLocations | selectattr('name', 'equalto', stageStorageLocationName) | map(attribute='schema') | first %}

   {#Subfolder path #}
   {%set subf = ""%}
   {% set subfolder_value = desiredState.config.subfolder | default('') %}
   {%if desiredState.config.subfolder == "" %}
    {%set subf = "" %}
   {%elif desiredState.config.subfolder == None%}
    {%set subf = "" %}
   {%else%}
    {%set subf = "WHERE RELATIVE_PATH LIKE '%"+ subfolder_value +"%'"%}
   {%endif%}

   {# Extraction Query Storage Location#}
   {% set extractionQueryStorageLocationName = desiredState.config.extractionQueryStorageLocationName %}
   {% set dbExtractionQuery = desiredState.storageLocations | selectattr('name', 'equalto', extractionQueryStorageLocationName) | map(attribute='database') | first %}
   {% set schExtractionQuery = desiredState.storageLocations | selectattr('name', 'equalto', extractionQueryStorageLocationName) | map(attribute='schema') | first %}


   {# Extraction Query Details #}
   {% set extractionQueryName = desiredState.config.extractionQueryName %}
   {% set extractionQueryVersion = desiredState.config.extractionQueryVersion %}

         {% set tableColumnIds = columns | map(attribute='id') | list %}
         {% set tableColumnNames = columns | map(attribute='name') | list %}

             {% set targetTableName = desiredState.node.name %}

            {# Task Info #}
            {% set taskName = desiredState.node.name + '_TASK'  %}
            {%- set fullyQualifiedTaskName = targetTableDatabase + '.' + targetTableSchema + '."' + taskName + '"' -%} 

            {# Task Type #}
            {%- if desiredState.config.schedulingMode == 'Warehouse Task' -%} 
                {# Can be updated during deployment via a parameter to account for different warehouse names in different deployments #}
                {% if 'targetTaskWarehouse'  in  desiredState.parameters %}
                {% if desiredState.parameters.targetTaskWarehouse == 'DEV ENVIRONMENT' %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.config.whName %}
                {% else %}
                    {% set taskType = 'WAREHOUSE = ' + desiredState.parameters.targetTaskWarehouse %}
                {% endif %}
                {%-endif -%}
            {%- else -%}
                {%- set taskType = 'USER_TASK_MANAGED_INITIAL_WAREHOUSE_SIZE = ' + desiredState.config.serverlessSize -%} 
            {%- endif -%}


            {# Schedule Type #}
        {%- if desiredState.config.schedulePeriodOption == 'Minutes' %} 
            {%- set execValue = desiredState.config.get('execTime', {})
                                .get('items', [])
                                | map(attribute='value')
                                | first
            %}
            {%- set execPeriod = desiredState.config.get('execTime', {})
                                .get('items', [])
                                | map(attribute='period')
                                | first
            %}
            {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + execValue | trim ~ ' ' ~ execPeriod | trim + "'" %}
        {% elif desiredState.config.schedulePeriodOption == 'CRON' %}
            {%- set nsVariables.taskWhenRun = 'SCHEDULE = ' + "'" + 'USING CRON ' + desiredState.config.scheduleCRON | trim + "'" %}  
        {%- endif -%}

            {# When Stream has data logic #}
            {# Source Stream Location and Name #}
            {% if desiredState.config.flagSrcStream == true %}
                {%- if nsVariables.poll == 'WHEN ' -%}
                    {% set nsVariables.poll = nsVariables.poll + 'SYSTEM$STREAM_HAS_DATA (\'' + fullyQualifiedStreamName + '\')'  %}
                {%- endif -%}
            {% endif -%}

        {%- set nsTaskVar = namespace(nodeComment='',
                                    userServiceAcct='',
                                    suspendTask='',
                                    autoTry='',
                                    overLapExec='',
                                    configJSON='',
                                    errorIntegration='',
                                    successIntegration='') %}
        {{ getadvancedTaskOptions(nsTaskVar) }}


            {% set tableColumnIds = desiredState.columns | map(attribute='id') | list %}
            {% set tableColumnNames = desiredState.columns | map(attribute='name') | list %}    


        {% set nsDocAI = namespace(formatPairs=[]) %}

        {% set configRows = desiredState.config.columnFamiliesConfig.get('items') if desiredState.config.columnFamiliesConfig else [] %}

        {% if configRows %}
            {% for row in configRows %}
                {% set fName = row.get('fieldName', '') %}
                {% set qString = row.get('qualifierString', '') %}

                {% set pairString = "['" + fName + "', '" + qString + "']" %}

                {% set nsDocAI.formatPairs = nsDocAI.formatPairs + [pairString] %}
            {% endfor %}
        {% endif %}

        {% set finalResponseFormat = "responseFormat => [" + nsDocAI.formatPairs | join(', ') + "]" %}

            {{ stage('Create Task') }}
            CREATE OR REPLACE TASK 
                {{ fullyQualifiedTaskName }} 
                {{ taskType}} 
                {{ nsTaskVar.nodeComment }}
                {{ nsVariables.taskWhenRun }}
                {%- if desiredState.config.schedulePeriodOption != 'Predecessor' %}
                    {{ nsTaskVar.overLapExec }}
                    {%- if desiredState.config.autoSuspendToggle %}
                    {{ nsTaskVar.suspendTask }}
                    {%- endif %}
                    {%- if desiredState.config.autoRetryToggle %}
                        {{ nsTaskVar.autoTry }}
                    {%- endif %}
                    {%- if desiredState.config.taskGraphToggle %}
                        {{ nsTaskVar.configJSON }}
                    {%- endif %}
                {%- if desiredState.config.errNotifyToggle %}
                    {{ nsTaskVar.errorIntegration }}
                {%- endif %}
                {%- if desiredState.config.successNotifyToggle %}
                    {{ nsTaskVar.successIntegration }}
                {%- endif %}
                {%- endif %}
                {%- if desiredState.config.spfcUserToggle %}
                    {{ nsTaskVar.userServiceAcct }}
                {%- endif %} 
                {% if nsVariables.poll != 'WHEN ' %} {{ nsVariables.poll }} {% endif %}
            AS 
        INSERT INTO {{ fullyQualifiedTargetTableName }}
            SELECT
           {%- for col in desiredState.sources[0].columns %}
              {%- if col.extractedData %}
              AI_EXTRACT(
                file => TO_FILE('@"{{ dbStage }}"."{{ schStage }}".{{ desiredState.config.stageName }}', RELATIVE_PATH),
                {%- if desiredState.config.optionJsonToggle == true %}
                responseFormat => {{ desiredState.config.optionsJson }}
                {%- else %}
                {{ finalResponseFormat }}
                {%- endif %}
              ) AS "{{ col.name }}"
              {%- else %}
              {{ get_source_transform(col) }} AS "{{ col.name }}"
              {%- endif %}
              {%- if not loop.last -%}, {% endif %}
            {%- endfor %}           
            FROM {{ ref(streamTargetLocationName, streamName) }}
            {% set ret_clause = get_clause( desiredState.sources[0].join ).lstrip()%}
            {% if subf != "" %} {{subf}}
			  {% if ret_clause|trim !='' %}
			     {{ret_clause}}
			  {% endif %}
			{%- else -%}
			  {% set join_clause = ret_clause | replace("AND ", "WHERE ", 1) if ret_clause.startswith("AND ") else ret_clause %}
			  {{join_clause}}
			{% endif %}
            {% if desiredState.config.groupByAll %}GROUP BY ALL{% endif %}

        {%- if desiredState.config.schedulePeriodOption != 'Predecessor' -%} 
                {{ stage('Resume Task') }}
                ALTER TASK {{ fullyQualifiedTaskName }} RESUME;
            {%- endif -%}

        {%- endif -%}

{% elif currentState != undefined and desiredState == undefined %}

    {# Target Table Info #}
    {% set targetTableDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetTableSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetTableName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

    {% if currentState.config.devMode | default(false) == false  %}
        {# FQ Root Task name #}
        {% set fullyQualifiedRootTaskName = targetTableDatabase + '.' + targetTableSchema + '."' + currentState.config.rootTask | default('') + '"'%}

        {# Task Info #}
        {% set taskName = currentState.node.name + '_TASK'  %}
        {%- set fullyQualifiedTaskName = targetTableDatabase + '.' + targetTableSchema + '."' + taskName + '"' -%} 

        {{ stage('Drop Current Task') }}
            DROP TASK IF EXISTS {{ fullyQualifiedTaskName }} 

    {%- endif -%}

{% endif %}

run.templateString:
{#
    Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : Cortex Search Service == #}
{# == Node Type Description    : This node creates a target view with the search results of Cortex Search Service  == #}

{%if config.querycortex %}
{#Cortex Search Service#}
{%if config.excss %}
      {% set CSSDatabase = storageLocations | selectattr('name', 'equalto',config.locCSS) | map(attribute='database') | first %} 
      {% set CSSSchema = storageLocations | selectattr('name', 'equalto',config.locCSS) | map(attribute='database') | first %} 
      {% set fullyQualifiedTargeCSSName = ref_no_link(config.locCSS, config.namCSS) %}  
{%else%}
      {% set fullyQualifiedTargeCSSName = ref_no_link(node.location.name, node.name) %}
{%endif%}


        {% set CSSDatabase = ref_no_link(node.location.name, node.name).split('.')[0] %} 
        {% set CSSSchema = ref_no_link(node.location.name,node.name).split('.')[1] %} 
        {% set fullyQualifiedTargeCSSTableName = ref_no_link(node.location.name, node.name) %}

{#Namespace variables#}

{%- set ns = namespace(numb="",timdec="",filcrit="") %}

{#Cortex Search Service target view#}

{% if config.allcol == false%}
  {% set tcolumns = config.colpreview.get('items') | map(attribute='columnName.name')| list %}
  {% set columnmod = tcolumns | map('string') | join('","') %}
{%else%}
  {% set allcol = columns| map(attribute='name')| list%}
  {% set columnmod = allcol | map('string') | join('","') %}
{%endif%}

{#Numeric boosts#}

{%if config.numboost%}
     {% set column, weightage = config.numericboost.get('items') | map(attribute='colname.name') | list, config.numericboost.get('items') | map(attribute='wage') | list %}

     {%for ncol in column %}
         {%set ns.numb = ns.numb + '{"column":"'+ ncol +'"'+ ',"weight":"' + weightage[loop.index0] + '"}' %}
         {%if  not loop.last%} {%set ns.numb = ns.numb + ','%}{%endif%}
    {%endfor%}
{%endif%}

{#Timedecay#}
{%if config.timdec%}
    {% set column, weightage,lhours,reft = config.timedecay.get('items') | map(attribute='tcolname.name') | list, config.timedecay.get('items') | map(attribute='twage') | list,config.timedecay.get('items') | map(attribute='lhours') | list,config.timedecay.get('items') | map(attribute='reftstmp')|list %}

    {%for ncol in column %}
         {%set ns.timdec = ns.timdec + '{"column":"'+ ncol +'"'+ ',"weight":"' + weightage[loop.index0] + '","limit_hours":"'+ lhours[loop.index0]+'"' %}
          {%if reft[loop.index0]!="" %}
         {%set ns.timdec = ns.timdec +',"now":"'+ reft[loop.index0]+'"}'%}
         {%else%}
         {%set ns.timdec = ns.timdec + '}'%}
         {%endif%}
         {%if  not loop.last%} {%set ns.numb = ns.numb + ','%}{%endif%}
    {%endfor%}       

{%endif%}

{#Filter#}
{%if config.filtoggle%}
     {% set column, mopt,val = config.filcrit.get('items') | map(attribute='filcolname.name') | list, config.filcrit.get('items') | map(attribute='mopt') | list,config.filcrit.get('items') | map(attribute='filcolval')|list%}

     {%if config.mulfilcon %}
         {%set ns.filcrit = ns.filcrit + '"@' + config.lopt + '":['  %}
     {%endif%}
     {%for ncol in column %}
         {%set ns.filcrit = ns.filcrit + '{"@'+ mopt[loop.index0] + '": {"'+ ncol +'":"' + val[loop.index0] + '"}}' %}
         {%if  not loop.last%} {%set ns.filcrit = ns.filcrit + ','%}{%endif%}
    {%endfor%}
    {%if config.mulfilcon %}
         {%set ns.filcrit = ns.filcrit + ']'  %}
     {%endif%}
{%endif%}



{{ stage(' Search Service preview', true, "sql", "create") }}

CREATE OR REPLACE VIEW {{ fullyQualifiedTargeCSSTableName }}
AS
SELECT
{%if config.allcol %}
   {%- for col in sources[0].columns  %} 
			value['{{col.name}}']::{{col.dataType}} as {{col.name}}
            {%- if not loop.last %}, {%- endif %}
    {%- endfor %}
{%else %}

      {%- for col in sources[0].columns  %} 
      {%if col.name in tcolumns%}
			value['{{col.name}}']::{{col.dataType}} as {{col.name}}
            {%- if not loop.last %}, {%- endif %}
{%endif%}
    {%- endfor %}
{%endif%}
FROM TABLE(FLATTEN(PARSE_JSON(SNOWFLAKE.CORTEX.SEARCH_PREVIEW(
    '{{ fullyQualifiedTargeCSSName }}',
    '{
      "query": "{{config.query1}}",
      "columns": ["{{columnmod}}"] ,
      "scoring_config": {
        "functions": {
          "numeric_boosts": [{{ns.numb}}],
          "time_decays":[{{ns.timdec}}],
          "filter":{ {{ns.filcrit}} }
        }
      }
    }'
))['results'] ))

{% else %}

    {{ stage('Preview/Query Mode Off') }}
    -- This node is configured not to run Cortex Search Service Queries
    -- Please enable 'Preview/Query the Cortex Service' in the node configuration to activate this functionality and choose appropriate settings
    SELECT 1 AS INFO_MESSAGE WHERE FALSE

{% endif %}

create.templateString:
{#
    Copyright (c) 2023 Coalesce. All rights reserved.
This script and its associated documentation are confidential and proprietary to Coalesce.
Unauthorized reproduction, distribution, or disclosure of this material is strictly prohibited.
Coalesce permits you to copy and modify this script for the purposes of using with Coalesce but
does not permit copying or modification for any other purpose.  
#}
{# == Node Type Name           : Cortex Search Service == #}
{# == Node Type Description    : This node creates a Cortex Search Service in snowflake  == #}

{%if desiredState and currentState != desiredState%}
     {%if desiredState.parameters == {} or  'searchServiceWarehouse' not in desiredState.parameters or desiredState.parameters.searchServiceWarehouse == ''%}

         {{stage('WARNING')}}

         /*Add parameter searchServiceWarehouse in workspace settings and deployment environment for successful execution of node.
         The default value for the parameter is 'DEV ENVIRONMENT'.
         Refer to documentation for more info */

      {%endif%}
  {%endif%}

{#Create Cortex search service #}

{% if desiredState  %}
    {%- if currentState != undefined and currentState.node.nodeType != desiredState.node.nodeType %}
        {%- set warningMsg = getNodeTypeSwitchWarning() | default('') %}

        {# Warning display - Node type changes can impact related tasks, streams, or services. #}
        {%- if warningMsg | trim | length > 0 -%}
            {{ stage('Warning! Node Type Switching Detected', false) }}
            {{ warningMsg }}
            select 1=0
        {%- endif -%}

        {% if currentState.node.materializationType != desiredState.node.materializationType %}
                {# Change in materialization type #}
                {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
                {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
                DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}

        {% endif %}
    {%- endif -%}


   {# Identify all config changes that would cause a CREATE instead of ALTER#}
   {% if currentState != undefined %} 
        {# General metadata #}

        {% set sourcesTest = currentState.sources | count == desiredState.sources | count %}

	     {# Desired Namespace Variables #}

        {% set nsVariables = namespace(nsDesiredDepStorageLocations="",nsDesiredSourceStorageLocations="",
        nsDesiredTargetStorageLocations="",
        nsDesiredUsedStorageLocations="",
        storageLocationTest= true,
        descolchanges = 0,
        othercolchanges = 0, joinTest = True ) %}

        {% for src in desiredState.sources %}
            {% if  currentState.sources[loop.index0].join != src.join %}
                {% set nsVariables.joinTest = false %}  {# Set joinTest to false if changes are detected #}
            {% endif %}
            {% endfor %}


        {# Test to see if the transform in a column has changed #}
        {# Desired Namespace Variables Transform #}
        {% set desiredTransformArray = desiredState.sources | map(attribute='columns') | first | map(attribute='transform') | list -%}

        {# Test to see if the transform in a column has changed #}
        {# Current Namespace Variables Transform #}
        {% set currentTransformArray = currentState.sources | map(attribute='columns') | first | map(attribute='transform') | list -%}

        {% set columnsTransformTest = currentTransformArray == desiredTransformArray %}

            {# Change Node Name or Change Storage Location #}
            {# Storage Location Tests #}
            {# Test  #}
            {%if currentState.storageLocations|length == 0%}          
              {% set currentDatabase = currentState.storageLocations | selectattr('name', 'equalto', currentState.node.location.name) | map(attribute='database') | string %}
              {% set currentSchema = currentState.storageLocations | selectattr('name', 'equalto', currentState.node.location.name) | map(attribute='schema') | string %}
               {% set currentDatabaseSchema = currentDatabase + '.' + currentSchema %}

            {%else %}   
            {# Current target node mappings #}
            {% set currentDatabase = currentState.storageLocations | selectattr('name', 'equalto', currentState.node.location.name) | map(attribute='database') | first %}
            {% set currentSchema = currentState.storageLocations | selectattr('name', 'equalto', currentState.node.location.name) | map(attribute='schema') | first %}
            {% set currentDatabaseSchema = currentDatabase + '.' + currentSchema %}  
			{% endif %}		 

            {# Desired target node mappings #}
            {% set desiredDatabase = desiredState.storageLocations | selectattr('name', 'equalto', desiredState.node.location.name) | map(attribute='database') | first %}
            {% set desiredSchema = desiredState.storageLocations | selectattr('name', 'equalto', desiredState.node.location.name) | map(attribute='schema') | first %}
            {% set desiredDatabaseSchema = desiredDatabase + '.' + desiredSchema %}           

             {% if currentDatabaseSchema != desiredDatabaseSchema %}
                {% set nsVariables.storageLocationTest = false %}
             {% endif %}


        {# Node#}
        {% set nodeNameTest = currentState.node.name == desiredState.node.name %}

        {# Initialize test #}
        {% set initialtest = currentState.config.initialize | default('') == desiredState.config.initialize %}

        {# Embedding model test #}
        {% set embmodtest = currentState.config.embmodel | default('') == desiredState.config.embmodel %}

        {#Search columns#}
        {%set searchcoltest = desiredState.config.searchcol.name == (currentState.config.searchcol | default({})).name | default('') %}

        {#Attribute columns#}
        {%set desiredattrcolarray = desiredState.config.attrcol.get('items') | map(attribute='acolname.name')| list %}
        {%set currentattrcolarray = (currentState.config.attrcol | default({})).get('items', []) | map(attribute='acolname.name')| list %}
        {%set attrcoltest = desiredattrcolarray == currentattrcolarray %}

        {#If any of the above are false then a CREATE must be run#}

        {% if 
            nsVariables.othercolchanges > 0 or
            sourcesTest == false or
            nsVariables.joinTest == false or
            columnsTransformTest == false or
            attrcoltest ==false or
            embmodtest == false or
            searchcoltest == false or
            initialtest == false or
            (currentState.storageLocations | length ==0)  %}    

            {% set createTest = true %}
        {% else %}
            {% set createTest = false %}
        {% endif %}      

    {% endif %}

        {# Identify config changes that would only result in ALTER #}
    {% if createTest == false %}
        {% if desiredState.parameters.searchServiceWarehouse == 'DEV ENVIRONMENT' %}
            {% set warehouseTest = currentState.config.warehouseName | default('') == desiredState.config.warehouseName %}
        {% else %}
            {% set warehouseTest = currentState.parameters.searchServiceWarehouse == desiredState.parameters.searchServiceWarehouse %}
        {% endif %}
        {% set lagSpecificationTest = currentState.config.lagSpecification == desiredState.config.lagSpecification %}
        {% set nodeCommentTest = currentState.node.description == desiredState.node.description %}

        {% if 
            warehouseTest == false or
            lagSpecificationTest == false or
            nodeCommentTest == false 
             %}    

            {% set alterOnlyTest = true %}
        {% else %}
            {% set alterOnlyTest = false %}
        {% endif %}

    {% endif %}

    {% if (currentState == undefined or createTest == true ) and desiredState.config.createcortex == true %}      


        {#Cortex search service Name#}
        {% set targetCSSDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %} 
        {% set targetCSSSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %} 
        {% set fullyQualifiedTargetCSSName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}

        {#Initialize option#}
        {% if desiredState.config.initialize == ''%}
            {% set CSSinitialize = 'ON_CREATE'%}
        {% else %}
            {% set CSSinitialize = desiredState.config.initialize %}
        {% endif %}

        {#Warehouse#}
        {# Can be updated during deployment via a parameter to account for different warehouse names in different deployments#}
        {% if desiredState.parameters.searchServiceWarehouse == 'DEV ENVIRONMENT' %}
            {% set CSSWarehouse = desiredState.config.warehouseName %}
        {% else %}
            {% set CSSWarehouse = desiredState.parameters.searchServiceWarehouse %}
        {% endif %}

        {#Downstream Option or Lag Specification#}

            {% set CSSLagValue = desiredState.config.lagSpecification.get('items') | map(attribute='lagValue') | first %}
            {% set CSSLagValuePeriod = desiredState.config.lagSpecification.get('items') | map(attribute='lagPeriod') | first %}
            {% set CSSLagSpecification = CSSLagValue ~ ' ' ~ CSSLagValuePeriod %}

        {#Node description#}
        {%- if desiredState.node.description !=""  %} 
            {% set CSSComment = "COMMENT = " + "'" + desiredState.node.description |escape + "'" %}
        {% endif %}

        {#Attribute columns#}
        {%- if desiredState.config.attrcol.get('items') | length >0 %}
            {%set attrcol = desiredState.config.attrcol.get('items') | map(attribute='acolname.name')| list %}
        {%endif%}

        {#Source query colummns#}
        {{ stage('Create Cortex Search Service', true, "sql", "create") }}
            CREATE OR REPLACE CORTEX SEARCH SERVICE {{ fullyQualifiedTargetCSSName }}
            ON {{desiredState.config.searchcol.name}}
            ATTRIBUTES {{attrcol|map("string")|join(',')}}
            TARGET_LAG = '{{ CSSLagSpecification }}'
            WAREHOUSE = {{CSSWarehouse}}
            INITIALIZE = {{CSSinitialize}}

            {% if desiredState.config.embmodel != '' %}
                EMBEDDING_MODEL = '{{desiredState.config.embmodel}}'
            {% endif %}
            {{ CSSComment  }}
        AS 
        (SELECT 
        {% for source in desiredState.sources %}          
            {% for col in source.columns %}

                {%if col.transform != ""%}
                      {{col.transform}} AS {{col.name}}
                {%else%}
                      "{{col.name}}" AS {{col.name}}
                {%endif%}
                {%- if not loop.last -%}, {% endif %}
            {% endfor %}

            {{ source.join }}
        {% endfor %})


    {% elif (currentState != undefined and desiredState != undefined) and (alterOnlyTest == true) %}

        {#Cortex search service Name#}
        {% set targetCSSDatabase = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[0] %} 
        {% set targetCSSSchema = ref_no_link(desiredState.node.location.name, desiredState.node.name).split('.')[1] %} 
        {% set fullyQualifiedTargetCSSName = ref_no_link(desiredState.node.location.name, desiredState.node.name) %}


        {# Desired Warehouse #}
        {% if desiredState.parameters.searchServiceWarehouse == 'DEV ENVIRONMENT' %}
            {% set desiredCSSWarehouse = desiredState.config.warehouseName %}
        {% else %}
            {% set desiredCSSWarehouse = desiredState.parameters.searchServiceWarehouse %}
        {% endif %}


        {#Desired Downstream Option or Lag Specification#}
        {% if desiredState.config.downstreamOption == true %}
            {% set desiredCSSLagSpecification = 'DOWNSTREAM' %}
        {% else %}
            {% set desiredCSSLagValue = desiredState.config.lagSpecification.get('items') | map(attribute='lagValue') | first %}
            {% set desiredCSSLagValuePeriod = desiredState.config.lagSpecification.get('items') | map(attribute='lagPeriod') | first %}

            {% set desiredCSSLagSpecification = desiredCSSLagValue ~ ' ' ~ desiredCSSLagValuePeriod %}
        {% endif %}


        {# Current Warehouse#}
        {% if currentState.parameters.searchServiceWarehouse == 'DEV ENVIRONMENT' %}
            {% set currentCSSWarehouse = currentState.config.warehouseName | default('') %}
        {% else %}
            {% set currentCSSWarehouse = currentState.parameters.searchServiceWarehouse %}
        {% endif %}

        {# Current Downstream Option or Lag Specification#}
        {% if currentState.config.downstreamOption | default(false) == true %}
            {% set currentCSSLagSpecification = 'DOWNSTREAM' %}
        {% else %}
            {% set currentCSSLagValue = currentState.config.lagSpecification.get('items') | map(attribute='lagValue') | first %}
            {% set currentCSSLagValuePeriod = currentState.config.lagSpecification.get('items') | map(attribute='lagPeriod') | first %}

            {% set currentCSSLagSpecification = currentCSSLagValue ~ ' ' ~ currentCSSLagValuePeriod %}
        {% endif %}


        {# ALTER for Warehouse if necessary #}
        {% set CSSWarehouse = '' %}
        {% if desiredCSSWarehouse != currentCSSWarehouse %}
            {% set CSSWarehouse = 'WAREHOUSE = ' + desiredCSSWarehouse %}
        {% endif %}

        {# Alter for Target lag if necessary #}
        {% set CSSLagSpecification = '' %}
        {% if desiredCSSLagSpecification != currentCSSLagSpecification %}
            {% if desiredCSSLagSpecification == 'DOWNSTREAM' %}
                {% set CSSLagSpecification = 'TARGET_LAG = DOWNSTREAM' %}
            {% else %}
                {% set CSSLagSpecification = 'TARGET_LAG = ' + '\'' + desiredCSSLagSpecification + '\'' %}
            {% endif %}
        {% endif %}

        {%- if desiredState.node.description != "" %} 
            {% set CSSComment = "COMMENT = " + "'" + desiredState.node.description |escape + "'" %}
        {% endif %}

            {% if  warehouseTest == false or lagSpecificationTest == false or downstreamOptionTest == false or nodeCommentTest == false %}

                {{ stage('Alter Cortex Search Service') }}

				ALTER CORTEX SEARCH SERVICE {{fullyQualifiedTargetCSSName }} SET
                 {{ CSSWarehouse }}
                 {{ CSSLagSpecification }}
                 {{ CSSComment}}


            {%endif%}

              {{ stage('Refresh Cortex Search Service') }}
               ALTER CORTEX SEARCH SERVICE {{fullyQualifiedTargetCSSName }} REFRESH

    {%endif%}

{% elif currentState != undefined and desiredState == undefined %}

    {# Dynamic Table Name#}
    {% set targetCSSDatabase = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[0] %} 
    {% set targetCSSSchema = ref_no_link(currentState.node.location.name, currentState.node.name).split('.')[1] %} 
    {% set fullyQualifiedTargetCSSName = ref_no_link(currentState.node.location.name, currentState.node.name) %}

    {{ stage('Drop ' + ref_no_link(currentState.node.location.name, currentState.node.name)) }}
    {%- set materialization = dropMaterialization(currentState.node.materializationType) %}
    DROP {{ materialization }} {{ ref_no_link(currentState.node.location.name, currentState.node.name) }}			  

{%endif%}

